comms.text:
@1 בְּקַדְמִין בְּרָא יְיָ יָת שְׁמַיָּא וְיָת אַרְעָא:
@2 וְאַרְעָא הֲוַת צָדְיָא וְרֵיקַנְיָא וַחֲשׁוֹכָא פָּרַשׂ עַל אַפֵּי תְהוֹמָא וְרוּחָא מִן קֳדָם יְיָ מְנַשְּׁבָא עַל אַפֵּי מַיָּא:
@3 וַאֲמַר יְיָ יְהֵי נְהוֹרָא וַהֲוָה נְהוֹרָא:
@4 וַחֲזָא יְיָ יָת נְהוֹרָא אֲרֵי טָב וְאַפְרֵשׁ יְיָ בֵּין נְהוֹרָא וּבֵין חֲשׁוֹכָא:
@5 וּקְרָא יְיָ לִנְהוֹרָא יְמָמָא וְלַחֲשׁוֹכָא קְרָא לֵילְיָא וַהֲוָה רְמַשׁ וַהֲוָה צְפַר יוֹמָא חָד:
@6 וַאֲמַר יְיָ יְהִי רְקִיעָא בִּמְצִיעוּת מַיָּא וִיהִי מַפְרִישׁ בֵּין מַיָּא לְמַיָּא:
@7 וַעֲבַד יְיָ יָת רְקִיעָא וְאַפְרֵישׁ בֵּין מַיָּא דִּי מִלְרַע לִרְקִיעָא וּבֵין מַיָּא דִּי מֵעַל לִרְקִיעָא וַהֲוָה כֵן:
@8 וּקְרָא יְיָ לִרְקִיעָא שְׁמַיָּא וַהֲוָה רְמַשׁ וַהֲוָה צְפַר יוֹם תִּנְיָן:
@9 וַאֲמַר יְיָ יִתְכַּנְשׁוּן מַיָּא מִתְּחוֹת שְׁמַיָּא לַאֲתַר חָד וְתִתְחֲזֵי יַבֶּשְׁתָּא וַהֲוָה כֵן:
@10 וּקְרָא יְיָ לְיַבֶּשְׁתָּא אַרְעָא וּלְבֵית כְּנִישׁוּת מַיָּא קְרָא יַמְמֵי וַחֲזָא יְיָ אֲרֵי טָּב:
@11 וַאֲמַר יְיָ תַּדְאֵית אַרְעָא דִּיתְאָה עִסְבָּא דְּבַר זַרְעֵהּ מִזְדְּרַע אִילַן פֵּירִין עָבַד פֵּירִין לִזְנֵהּ דִּי בַר זַרְעֵהּ בֵּהּ עַל אַרְעָא וַהֲוָה כֵן:
@12 וְאַפֵּקַת אַרְעָא דִּיתְאָה עִסְבָּא דְּבַר זַרְעֵהּ מִזְדְּרַע לִזְנוֹהִי וְאִילַן עָבֵד פֵּירִין דְּבַר זַרְעֵהּ בֵּהּ לִזְנוֹהִי וַחֲזָא יְיָ אֲרֵי טָב:
@13 וַהֲוָה רְמַשׁ וַהֲוָה צְפַר יוֹם תְּלִיתָאִי:
@14 וַאֲמַר יְיָ יְהוֹן נְהוֹרִין בִּרְקִיעָא דִּשְׁמַיָּא לְאַפְרָשָׁא בֵּין יְמָמָא וּבֵין לֵילְיָא וִיהוֹן לְאָתִין וּלְזִמְנִין וּלְמִימְנֵי בְהוֹן יוֹמִין וּשְׁנִין:
@15 וִיהוֹן לִנְהוֹרִין בִּרְקִיעָא דִּשְׁמַיָּא לְאַנְהָרָא עַל אַרְעָא וַהֲוָה כֵן:
@16 וַעֲבַד יְיָ יָת תְּרֵין נְהוֹרַיָּא רַבְרְבַיָּא יָת נְהוֹרָא רַבָּא לְמִשְׁלַט בִּימָמָא וְיָת נְהוֹרָא זְעֵרָא לְמִשְׁלַט בְּלֵילְיָא וְיָת כּוֹכְבַיָּא:
@17 וִיהַב יָתְהוֹן יְיָ בִּרְקִיעָא דִּשְׁמַיָּא לְאַנְהָרָא עַל אַרְעָא:
@18 וּלְמִשְׁלַט בִּימָמָא וּבְלֵילְיָא וּלְאַפְרָשָׁא בֵּין נְהוֹרָא וּבֵין חֲשׁוֹכָא וַחֲזָא יְיָ אֲרֵי טָב:
@19 וַהֲוָה רְמַשׁ וַהֲוָה צְפַר יוֹם רְבִיעָאִי:
@20 וַאֲמַר יְיָ יִרְחֲשׁוּן מַיָּא רְחֵשׁ נַפְשָׁא חַיְתָא וְעוֹפָא יְפָרַח עַל אַרְעָא עַל אַפֵּי רְקִיעָא דִּשְׁמַיָּא:
@21 וּבְרָא יְיָ יָת תַּנִּינַיָּא רַבְרְבַיָּא וְיָת כָּל נַפְשָׁא חַיְתָא דִּרְחִשָׁא דִּי אַרְחִישׁוּ מַיָּא לִזְנֵיהוֹן וְיָת כָּל עוֹפָא דְפָרַח לִזְנוֹהִי וַחֲזָא יְיָ אֲרֵי טָב:
@22 וּבָרִיךְ יָתְהוֹן יְיָ לְמֵימָר פּוּשׁוּ וּסְגוּ וּמְלוּ יָת מַיָּא בְּיַמְמַיָּא וְעוֹפָא יִסְגֵּי בְּאַרְעָא:
@23 וַהֲוָה רְמַשׁ וַהֲוָה צְפַר יוֹם חֲמִישָׁאִי:
@24 וַאֲמַר יְיָ תַּפֵּק אַרְעָא נַפְשָׁא חַיְתָא לִזְנַהּ בְּעִיר וּרְחֵשׁ וְחֵוַת אַרְעָא לִזְנַהּ וַהֲוָה כֵן:
@25 וַעֲבַד יְיָ יָת חֵוַת אַרְעָא לִזְנַהּ וְיָת בְּעִירָא לִזְנַהּ וְיָת כָּל רִחֲשָׁא דְאַרְעָא לִזְנוֹהִי וַחֲזָא יְיָ אֲרֵי טָב:
@26 וַאֲמַר יְיָ נַעֲבִיד אֶינָשָׁא בְּצַלְמֵנָא כִּדְמוּתָנָא וְיִשְׁלְטוּן בְּנוּנֵי יַמָּא וּבְעוֹפָא דִּשְׁמַיָּא וּבִבְעִירָא וּבְכָל אַרְעָא וּבְכָל רִחֲשָׁא דְּרָחֵשׁ עַל אַרְעָא:
@27 וּבְרָא יְיָ יָת אָדָם בְּצַלְמֵהּ בְּצַלְמָא דַיְיָ בְּרָא יָתֵהּ דְּכַר וְנוּקְבָא בְּרָא יָתְהוֹן:
@28 וּבָרִיךְ יָתְהוֹן יְיָ וַאֲמַר לְהוֹן יְיָ פּוּשׁוּ וּסְגוּ וּמְלוּ יָת אַרְעָא וּתְקוּפוּ עֲלַהּ וּשְׁלוּטוּ בְּנוּנֵי יַמָּא וּבְעוֹפָא דִּשְׁמַיָּא וּבְכָל חַיְתָא דְּרָחֵשָׁא עַל אַרְעָא:
@29 וַאֲמַר יְיָ הָא יְהָבִית לְכוֹן יָת כָּל עִסְבָּא דְּבַר זַרְעֵהּ מִזְדְּרַע דִּי עַל אַפֵּי כָל אַרְעָא וְיָת כָּל אִילָנָא דִּי בֵהּ פֵּירֵי אִילָנָא דְּבַר זַרְעֵהּ מִזְדְּרָע לְכוֹן יְהֵא לְמֵיכָל:
@30 וּלְכָל חֵוַת אַרְעָא וּלְכָל עוֹפָא דִּשְׁמַיָּא וּלְכֹל דְּרָחֵשׁ עַל אַרְעָא דִּי בֵהּ נַפְשָׁא חַיְתָא יָת כָּל יְרוֹק עִסְבָּא לְמֵיכָל וַהֲוָה כֵן:
@31 וַחֲזָא יְיָ יָת כָּל דִּי עֲבַד וְהָא תַקִּין לַחֲדָא וַהֲוָה רְמַשׁ וַהֲוָה צְפַר יוֹם שְׁתִיתָאִי:
@32 וְאִשְׁתַּכְלָלוּ שְׁמַיָּא וְאַרְעָא וְכָל חֵילֵיהוֹן:
@33 וְשֵׁיצֵי יְיָ בְּיוֹמָא שְׁבִיעָאָה עֲבִדְתֵּהּ דִּי עֲבָד וְנַח בְּיוֹמָא שְׁבִיעָאָה מִכָּל עֲבִדְתֵּהּ דִּי עֲבָד:
@34 וּבָרִיךְ יְיָ יָת יוֹמָא שְׁבִיעָאָה וְקַדִּישׁ יָתֵהּ אֲרֵי בֵהּ נַח מִכָּל עֲבִדְתֵּהּ דִּי בְרָא יְיָ לְמֶעְבַּד:
@35 אִלֵּין תּוּלְדַת שְׁמַיָּא וְאַרְעָא כַּד אִתְבְּרִיאוּ בְּיוֹמָא דִּי עֲבַד יְיָ אֱלֹהִים אַרְעָא וּשְׁמַיָּא:
@36 וְכֹל אִילָנֵי חַקְלָא עַד לָא הֲווּ בְאַרְעָא וְכָל עִסְבָּא דְחַקְלָא עד לָא צְמָח אֲרֵי לָא אָחִית מִטְרָא יְיָ אֱלֹהִים עַל אַרְעָא וְאֱנַשׁ לֵית לְמִפְלַח יָת אַדְמְתָא:
@37 וַעֲנָנָא הֲוָה סָלֵיק מִן אַרְעָא וְאַשְׁקֵי יָת כָּל אַפֵּי אַדְמְתָא:
@38 וּבְרָא יְיָ אֱלֹהִים יָת אָדָם עַפְרָא מִן אַדְמְתָא וּנְפַח בְּאַפּוֹהִי נִשְׁמְתָא דְחַיֵּי וַהֲוַת בְּאָדָם לְרוּחַ מְמַלְלָא:
@39 וּנְצִיב יְיָ אֱלֹהִים גִּינְתָא בְעֵדֶן מִלְּקַדְמִין וְאַשְׁוֵי תַמָּן יָת אָדָם דִּי בְרָא:
@40 וְאַצְמַח יְיָ אֱלֹהִים מִן אַרְעָא כָּל אִילַן דִּמְרַגֵּג לְמֶחֱזֵי וְטַב לְמֵיכַל וְאִילַן חַיָּא בִּמְצִיעוּת גִּינְתָא וְאִילַן דְּאָכְלִין פֵּירוֹהִי חַכִּימִין בֵּין טַב לְבִישׁ:
@41 וְנַהֲרָא הֲוָה נָפִיק מֵעֵדֶן לְאַשְׁקָאָה יָת גִּינְתָא וּמִתַּמָּן יִתְפָּרִשׁ וַהֲוֵי לְאַרְבְּעָה רֵישֵׁי נַהֲרִין:
@42 שׁוּם חָד פִּישׁוֹן הוּא מַקִּיף יָת כָּל אֲרַע דַּחֲוִילָה דִּי תַמָּן דַּהֲבָא:
@43 וְדַהֲבָא דְאַרְעָא הַהִיא טָב תַּמָן בְּדָלְחָא וְאַבְנֵי בוּרְלָא:
@44 וְשׁוּם נַהֲרָא תִנְיָנָא גִּיחוֹן הוּא מַקִּיף יָת כָּל אַרְעָא דְכוּשׁ:
@45 וְשׁוּם נַהֲרָא תְּלִיתָאָה דִּיגְלַת הוּא מְהַלֵּךְ לְמַדִּינְחָא דְאַתּוּר וְנַהֲרָא רְבִיעָאָה הוּא פְרָת:
@46 וּדְבַר יְיָ אֱלֹהִים יָת אָדָם וְאַשְׁרֵיהּ בְּגִינְתָא דְעֵדֶן לְמִפְלְחַהּ וּלְמִטְרַהּ:
@47 וּפַקִּיד יְיָ אֱלֹהִים עַל אָדָם לְמֵימָר מִכֹּל אִילַן גִּינְתָא מֵיכַל תֵּיכוּל:
@48 וּמֵאִילָן דְּאָכְלִין פֵּירוֹהִי חַכִּימִין בֵּין טַב לְבִישׁ לָא תֵיכוּל מִנֵּהּ אֲרֵי בְּיוֹמָא דְתֵיכוּל מִנֵּהּ מֵימַת תְּמוּת:
@49 וַאֲמַר יְיָ אֱלֹהִים לָא תַקִּין לְמֶהֱוֵי אָדָם בִּלְחוֹדוֹהִי אַעֲבֵד לֵהּ סְמַךְ לְקִבְלֵהּ:
@50 וּבְרָא יְיָ אֱלֹהִים מִן אַרְעָא כָּל חֵוַת בְּרָא וְיָת כָּל עוֹפָא דִּשְׁמַיָּא וְאַיְתֵהּ לְוַת אָדָם לְמֶחֱזֵי מַה יִּקְרֵי לֵהּ וְכֹל דִּי הֲוָה קָרֵי לֵהּ אָדָם נַפְשָׁא חַיְתָא הוּא שְׁמֵהּ:
@51 וּקְרָא אָדָם שְׁמָהָן לְכָל בְּעִירָא וּלְעוֹפָא דִּשְׁמַיָּא וּלְכָל חֵוַת בְּרָא וּלְאָדָם לָא אַשְׁכַּח סָמֵךְ לְקִבְלֵהּ:
@52 וּרְמָא יְיָ אֱלֹהִים שִׁינְתָא עַל אָדָם וּדְמֵךְ וּנְסִיב חֲדָא מֵעִלְעוֹהִי וּמְלֵי בִשְׂרָא תְּחוֹתַהּ:
@53 וּבְנָא יְיָ אֱלֹהִים יָת עִלְעָא דִּנְסִיב מִן אָדָם לְאִתְּתָא וְאַיְתַהּ לְוַת אָדָם:
@54 וַאֲמַר הָאָדָם הֲדָא זִמְנָא גַּרְמָא מִגַּרְמַי וּבִסְרָא מִבִּסְרִי לְדָא יִתְקְרֵי אִתְּתָא אֲרֵי מִבַּעְלָא נְסִיבָא דָא:
@55 עַל כֵּן יִשְׁבּוֹק גְּבַר בֵּית מִשְׁכְּבֵי אַבוּהִי וְאִמֵּהּ וְיִדְבַּק בְּאִתְּתֵהּ וִיהוֹן לְבִסְרָא חָדּ:
@56 וַהֲווֹ תַרְוֵיהוֹן עַרְטִילָאִין אָדָם וְאִתְּתֵהּ וְלָא מִתְכַּלְמִין:
@57 וְחִוְיָא הֲוָה חַכִּים מִכֹּל חֵוַת בְּרָא דִּי עֲבַד יְיָ אֱלֹהִים וַאֲמַר לְאִתְּתָא בְּקוּשְׁטָא אֲרֵי אֲמַר יְיָ לָא תֵיכְלוּן מִכֹּל אִילַן גִּינְתָא:
@58 וַאֲמָרַת אִתְּתָא לְחִוְיָא מִפֵּירֵי אִילַן גִּינְתָא נֵיכוּל:
@59 וּמִפֵּירֵי אִילָנָא דִּי בִמְצִיעוּת גִּינְתָא אֲמַר יְיָ לָא תֵיכְלוּן מִנֵּהּ וְלָא תְקַרְבוּן בֵּהּ דִּילְמָא תְּמוּתוּן:
@60 וַאֲמַר חִוְיָא לְאִיתְּתָא לָא מוּת תְּמוּתוּן:
@61 אֲרֵי גַּלֵּי קֳדָם יְיָ אֲרֵי בְּיוֹמָא דְּתֵיכְלוּן מִנֵּהּ וְיִתְפַּתְּחַן עֵינֵיכוֹן וּתְהוֹן כְּרַבְרְבִין חַכִּימִין בֵּין טַב לְבִישׁ:
@62 וַחֲזַת אִתְּתָא אֲרֵי טַב אִילַן לְמֵיכָל וַאֲרֵי אַסֵּי הוּא לְעַיְנִין וּמְרַגֵּג אִילָנָא לְאִסְתַּכָּלָא בֵהּ וּנְסֵיבַת מֵאִבֵּהּ וַאֲכָלַת וִיהָבַת אַף לְבַעְלַהּ עִמַּהּ וַאֲכָל:
@63 וְאִתְפַּתָּחָא עֵינֵי תַרְוֵיהוֹן וִידָעוּ אֲרֵי עַרְטִילָאִין אִינוּן וְחַטִּיטוּ לְהוֹן טַרְפֵי תְאֵנִין וַעֲבָדוּ לְהוֹן זְרָזִין:
@64 וּשְׁמָעוּ יָת קַל מֵימְרָא דַּיְיָ אֱלֹהִים מְהַלֵּךְ בְּגִינְתָא לִמְנַח יוֹמָא וְאִיטַמַּר אָדָם וְאִתְּתֵהּ מִן קֳדָם יְיָ אֱלֹהִים בְּגוֹ אִילַן גִּינְתָא:
@65 וּקְרָא יְיָ אֱלֹהִים לְאָדָם וַאֲמַר לֵהּ אָן אָתְּ:
@66 וַאֲמַר יָת קַל מֵימְרָךְ שַׁמְעִית בְּגִינְתָא וּדְהֵילִית אֲרֵי עַרְטִילַאי אֲנָא וְאִיטַמָּרִית:
@67 וַאֲמַר מָן חַוֵי לָךְ אֲרֵי עַרְטִילַאי אָתְּ הֲמִן אִילָנָא דִּפַקֶּדְתָּךְ בְּדִיל דְּלָא לְמֵיכַל מִנֵּהּ אֲכָלְתְּ:
@68 וַאֲמַר הָאָדָם אִתְּתָא דִּיהַבְתָּ עִמִּי הִיא יַהֲבַת לִי מִן אִילָנָא וַאֲכָלִית:
@69 וַאֲמַר יְיָ אֱלֹהִים לְאִתְּתָא מַה דָּא עַבְדָת וַאֲמָרַת אִתְּתָא חִוְיָא אַטְעַיָנִי וַאֲכָלִית:
@70 וַאֲמַר יְיָ אֱלֹהִים לְחִוְיָא אֲרֵי עֲבַדְתָּ דָּא לִיט אַתְּ מִכָּל בְּעִירָא וּמִכֹּל חֵוַת בָּרָא עַל מְעָךְ תֵּיזִילּ וְעַפְרָא תֵיכוּל כָּל יוֹמֵי חַיָּיךְ:
@71 וּדְבָבוּ אֱשַׁוֵּי בֵּינָךְ וּבֵין אִתְּתָא וּבֵין בְּנָךְ וּבֵין בְּנָהַהּ הוּא יְהֵי דְּכִיר לָךְ מַה דִּעֲבַדְתָּ לֵהּ מִלְּקַדְמִין וְאַתְּ תְּהֵא נָטִיר לֵהּ לְסוֹפָא:
@72 לְאִתְּתָא אֲמַר אַסְגָּאָה אַסְגֵּי צַעֲרַיְכִי וְעִדּוּיַיְכִי בְּצְעַר תֵּלְדִי בְנִין וּלְוַת בַּעְלִךְ תְּהֵא תִּאוּבְתִּיךְ וְהוּא יִשְׁלַט בִּךְ:
@73 וּלְאָדָם אֲמַר אֲרֵי קַבֵּילְתָּ לְמֵימַר אִתְּתָךְ וַאֲכַלְתָּ מִן אִילָנָא דִּי פַקֵּידְתָּךְ לְמֵימַר לָא תֵיכוּל מִנֵּהּ לִיטָא אַרְעָא בְּדִילָךְ בַּעֲמַל תִּיכְלִינַהּ כָּל יוֹמֵי חַיָּיךְ:
@74 וְכוּבִין וְאַטְדִּין תַּצְמַח לָךְ וְתֵיכוּל יָת עִסְבָּא דְחַקְלָא:
@75 בְּזִעֲתָא דְאַפָּךְ תֵּיכוּל לַחְמָא עַד דְּתִיתוּב לְאַרְעָא דְּמִנַּהּ אִתְבְּרֵיתָא אֲרֵי עַפְרָא אַתְּ וּלְעַפְרָא תְּתוּב:
@76 וּקְרָא אָדָם שׁוּם אִתְּתֵהּ חַוָּה אֲרֵי הִיא הֲוַת אִמָּא דְכָל בְּנֵי אֱנָשָׁא:
@77 וַעֲבַד יְיָ אֱלֹהִים לְאָדָם וּלְאִתְּתֵהּ לְבוּשִׁין דִּיקָר עַל מְשַׁךְ בִּשְׂרֵיהוֹן וְאַלְבִּישִׁינוּן:
@78 וַאֲמַר יְיָ אֱלֹהִים הָא אָדָם הֲוָה יְחִידַי בְּעַלְמָא מִנֵּהּ לְמִידַע טַב וּבִישׁ וּכְעַן דִּילְמָא יוֹשִׁיט יְדֵהּ וְיִסַב אַף מֵאִילָן חַיָּיא וְיֵכוּל וִיחֵי לְעָלָם:
@79 וְשַׁלְּחֵהּ יְיָ אֱלֹהִים מִגִּינְתָא דְעֵדֶן לְמִפְלַח יַת אַדְמְתָא דְּאִתְבְּרִי מִתַּמָּן:
@80 וְתָרִךְ יָת אָדָם וְאַשְׁרֵי מִלְּקַדְמִין לְגִינְתָא דְעֵדֶן יָת כְּרוּבַיָּא וְיָת שְׁנַן חַרְבָּא דְּמִתְהַפְּכָא לְמִיטַר יָת אוֹרַח אִילַן חַיָּיא:
@81 וְאָדָם יְדַע יָת חַוָּה אִתְּתֵהּ וְעַדִּיאַת וִילִידַת יָת קַיִן וַאֲמֶרֶת קָנִיתִי גַּבְרָא (מִן) קֳדָם יְיָ:
@82 וְאוֹסִיפַת לְמֵילַד יָת אֲחוֹהִי יָת הָבֶל וַהֲוָה הֶבֶל רָעֵי עָנָא וְקַיִן הֲוָה פָלַח בְּאַרְעָא:
@83 וַהֲוָה מִסּוֹף יוֹמִין וְאַיְתִי קַיִן מֵאִבָּא דְאַרְעָא תִּקְרוּבְתָּא קֳדָם יְיָ:
@84 וְהֶבֶל אַיְתִי אַף הוּא מִבַּכִּירֵי עָנֵהּ וּמִשַׁמִּנְהוֹן וַהֲוַת רַעֲוָא מִן קֳדָם יְיָ בְּהֶבֶל וּבְּקוּרְבָּנֵהּ:
@85 וּבְּקַיִן וּבְּקוּרְבָּנֵהּ לָא הֲוַת רַעֲוָא וּתְקֵף לְקַיִן לַחֲדָא וְאִתְכְּבִישׁוּ אַפּוֹהִי:
@86 וַאֲמַר יְיָ לְקָיִן לְמָא תְּקִיף לָךְ וּלְמָא אִתְכְּבִישׁוּ אַפָּיךְ:
@87 הֲלָא אִם תּוֹטִיב עוֹבָדָךְ יִשְׁתְּבֵק לָךְ וְאִם לָא תּוֹטִיב עוֹבָדָךְ לְיוֹם דִּינָא חֶטְאָךְ נְטִיר דִיעֲתִיד לְאִתְפָּרְעָא מִנָּךְ אִם לָא תְתוּב וְאִם תְּתוּב יִשְׁתְּבֵק לָךְ:
@88 וַאֲמַר קַיִן לְהֶבֶל אַחוֹהִי וַהֲוָה בְּמֶהֱוֵיהוֹן בְּחַקְלָא וְקָם קַיִן עַל הֶבֶל אַחוֹהִי וְקַטְלֵהּ:
@89 וַאֲמַר יְיָ לְקַיִן אָן הֶבֶל אָחוּךְ וַאֲמַר לָא יָדַעֲנָא הֲנָטֵר אָחִי אֲנָא:
@90 וַאֲמַר מֶה עֲבַדְתָּא קַל דַם זַרְעִין דִעֲתִידִין לְמֵפַק מִן אָחוּךְ קַבְלִין קֳדָמַי מִן אַרְעָא:
@91 וּכְעַן לִיט אָתְּ מִן אַרְעָא דִּפְתָחַת יָת פּוּמַהּ וְקַבִּילַת יָת דְּמֵהּ דְּאָחוּךְ מִן יְדָךְ:
@92 אֲרֵי תִפְלַח בְאַרְעָא לָא תוֹסִיף לְמִתַּן חֵילַהּ לָךְ מִטַלְטֵּל וְגָלֵי תְּהֵא בְאַרְעָא:
@93 וַאֲמַר קַיִן קֳדָם יְיָ סַגִּי חוֹבִי מִלְּמִשְׁבָּק:
@94 הָא תָרִיכְתָּא יָתִי יוֹמָא דֵּין מֵעַל אַפֵּי אַרְעָא וּמִן קֳדָמָךְ לֵית אֶפְשָׁר לְאִטַּמָּרָא וָאֱהִי מְטַלְטֵל וְגָלֵי בְּאַרְעָא וִיהֵי כָל דְּיִשְׁכְּחִנַנִי יִקְטְּלִינַנִי:
@95 וַאֲמַר לֵהּ יְיָ בְּכֵן כָּלּ קָטִיל קַיִן לְשַׁבְעָא דָּרִין יִתְפְּרַע מִנֵּהּ וְשַׁוִּי יְיָ לְקַיִן אָתָא בְּדִיל דְּלָא לְמִקְטַל יָתֵהּ כָּל דִיִשְׁכְּחֻנֵהּ:
@96 וּנְפַק קַיִן מִן קֳדָם יְיָ וִיתֵיב בְּאַרְעָא גָּלֵי וּמִטַּלְטַל דַּהֲוָה עֲבִידָא עֲלוֹהִי מִלְּקַדְמִין דְּגִינְתָא דְעֵדֶן:
@97 וִידַע קַיִן יָת אִתְּתֵהּ וְעַדִּיאַת וִילֵידַת יָת חֲנוֹךְ וַהֲוָה בָּנֵי קַרְתָּא וּקְרָא שְׁמָא דְקַרְתָּא כְּשׁוּם בְּרֵהּ חֲנוֹךְ:
@98 וְאִתְיְלִיד לַחֲנוֹךְ יָת עִירָד וְעִירָד אוֹלִיד יָת מְחוּיָאֵל וּמְחִיָּיאֵל אוֹלִיד יָת מְתוּשָׁאֵל וּמְתוּשָׁאֵל אוֹלִיד יָת לָמֶךְ:
@99 וּנְסִיב לֵהּ לֶמֶךְ תַּרְתֵּין נְשִׁין שׁוּם חֲדָא עָדָה וְשׁוּם תִּנְיֵתָא צִלָּה:
@100 וִילֵידַת עָדָה יָת יָבָל הוּא הֲוָה רַבְּהוֹן דְּיָתְבֵי מַשְׁכְּנִין וּמָרֵי בְעִיר:
@101 וְשׁוּם אֲחוֹהִי יוּבָל הוּא הֲוָה רַבְּהוֹן דְּכָל דִּמְנַגֵּן עַל פּוּם נִבְלָא יָדְעֵי זְמַר כִּנּוֹרָא וְאַבּוּבָא:
@102 וְצִלָּה אַף הִיא יְלֵידַת יָת תּוּבַל קַיִן רַבְּהוֹן דְכָל דְּיָדְעֵי עִיבִידַת נְחָשָׁא וּפַרְזְלָא וַאֲחָתֵהּ דְתוּבַל קַיִן נַעֲמָה:
@103 וַאֲמַר לֶמֶךְ לִנְשׁוֹהִי עָדָה וְצִלָּה שִׁמְעַן קָלִי נְשֵׁי לֶמֶךְ אֲצֵיתָא לְמֵמְרִי לָא גַּבְרָא קְטָלִית דִּבְדִילֵהּ אֲנָא סָבִיל חוֹבִין וְאַף לָא עוּלֵימָא חַבָּלִית דִּבְדִילֵהּ יִשְׁתֵּיצֵי זַרְעִי:
@104 אֲרֵי שַׁבְעָא דָּרִין אִיתְלִאוּ לְקָיִן הֲלָא לְלֶמֶךְ בְּרֵהּ שַׁבְעִין וְשַׁבְעָא:
@105 וִידַע אָדָם עוֹד יָת אִתְּתֵהּ וִילֵידַת בַּר וּקְרַת יָת שְׁמֵהּ שֵׁת אֲרֵי אַמָרַת יְהַב לִי יְיָ בַּר אוֹחֲרָן חֲלַף הֶבֶל דִּקַטְלֵהּ קָיִן:
@106 וּלְשֵׁת אַף הוּא אִתְיְלִיד בַּר וּקְרָא יָת שְׁמֵהּ אֱנוֹשׁ בְּכֵן בְּיוֹמוֹהִי חָלוּ בְנֵי אֱנָשָׁא מִלְּצַלָּאָה בִּשְׁמָא דַּיְיָ:
@107 דֵּין סְפַר תּוּלְדַת אָדָם בְּיוֹמָא דִּבְרָא יְיָ אָדָם בִּדְמוּת אֱלֹהִים עָבַד יָתֵהּ:
@108 דְּכַר וְנוּקְבָא בְּרָאנוּן וּבָרִיךְ יָתְהוֹן וּקְרָא יָת שְׁמָהוֹן אָדָם בְּיוֹמָא דְאִתְבְּרִיאוּ:
@109 וַחֲיָא אָדָם מְאָה וּתְלָתִין שְׁנִין וְאוֹלִיד בִּדְמוּתֵהּ דְּדָמֵי לֵהּ וּקְרָא יָת שְׁמֵהּ שֵׁת:
@110 וַהֲווֹ יוֹמֵי אָדָם בָּתַר דְּאוֹלִיד יָת שֵׁת תַּמְנֵי מְאָה שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@111 וַהֲווֹ כָּל יוֹמֵי אָדָם דַחֲיָא תְּשַׁע מְאָה וּתְלָתִין שְׁנִין וּמִית:
@112 וַחֲיָא שֵׁת מְאָה וַחֲמֵשׁ שְׁנִין וְאוֹלִיד יָת אֱנוֹשׁ:
@113 וַחֲיָא שֵׁת בָּתַר דְּאוֹלִיד יָת אֱנוֹשׁ תַּמְנֵי מְאָה וּשְׁבַע שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@114 וַהֲווֹ כָּל יוֹמֵי שֵׁת תְּשַׁע מְאָה וְתַרְתֵּי עַשְׂרֵי שְׁנִין וּמִית:
@115 וַחֲיָא אֱנוֹשׁ תִּשְׁעִין שְׁנִין וְאוֹלִיד יָת קֵינָן:
@116 וַחֲיָא אֱנוֹשׁ בָּתַר דְאוֹלִיד יָת קֵינָן תַּמְנֵי מְאָה וַחֲמֵשׁ עַשְׂרֵי שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@117 וַהֲווֹ כָּל יוֹמֵי אֱנוֹשׁ תְּשַׁע מְאָה וַחֲמֵשׁ שְׁנִין וּמִית:
@118 וַחֲיָא קֵינָן שַׁבְעִין שְׁנִין וְאוֹלִיד יָת מַהֲלַלְאֵל:
@119 וַחֲיָא קֵינָן בָּתַר דְּאוֹלִיד יָת מַהֲלַלְאֵל תַּמְנֵי מְאָה וְאַרְבְּעִין שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@120 וַהֲווֹ כָּל יוֹמֵי קֵינָן תְּשַׁע מְאָה וַעֲשַׂר שְׁנִין וּמִית:
@121 וַחֲיָא מַהֲלַלְאֵל שִׁתִּין וַחֲמֵשׁ שְׁנִין וְאוֹלִיד יָת יָרֶד:
@122 וַחֲיָא מַהֲלַלְאֵל בָּתַר דְּאוֹלִיד יָת יֶרֶד תַּמְנֵי מְאָה וּתְלָתִין שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@123 וַהֲווֹ כָּל יוֹמֵי מַהֲלַלְאֵל תַּמְנֵי מְאָה וְתִשְׁעִין וַחֲמֵשׁ שְׁנִין וּמִית:
@124 וַחֲיָא יֶרֶד מְאָה וְשִׁתִּין וְתַרְתֵּין שְׁנִין וְאוֹלִיד יָת חֲנוֹךְ:
@125 וַחֲיָא יֶרֶד בָּתַר דְּאוֹלִיד יָת חֲנוֹךְ תַּמְנֵי מְאָה שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@126 וַהֲווֹ כָּל יוֹמֵי יֶרֶד תְּשַׁע מְאָה וְשִׁתִּין וְתַרְתֵּין שְׁנִין וּמִית:
@127 וַחֲיָא חֲנוֹךְ שִׁתִּין וַחֲמֵשׁ שְׁנִין וְאוֹלִיד יָת מְתוּשָׁלַח:
@128 וְהַלִּיךְ חֲנוֹךְ בְּדַחַלְתָּא דַּיְיָ בָּתַר דְּאוֹלִיד יָת מְתוּשֶׁלַח תְּלַת מְאָה שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@129 וַהֲוָה כָּל יוֹמֵי חֲנוֹךְ תְּלַת מְאָה וְשִׁתִּין וַחֲמֵשׁ שְׁנִין:
@130 וְהַלִּיךְ חֲנוֹךְ בְּדַחַלְתָּא דַּיְיָ וְלַיְתוֹהִי אֲרֵי (לָא) אֲמֵית יָתֵהּ יְיָ:
@131 וַחֲיָא מְתוּשֶׁלַח מְאָה וְתַמְנִין וּשְׁבַע שְׁנִין וְאוֹלִיד יָת לָמֶךְ:
@132 וַחֲיָא מְתוּשֶׁלַח בָּתַר דְּאוֹלִיד יָת לֶמֶךְ שְׁבַע מְאָה וְתַמְנִין וְתַרְתֵּין שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@133 וַהֲווֹ כָּל יוֹמֵי מְתוּשֶׁלַח תְּשַׁע מְאָה וְשִׁתִּין וּתְשַׁע שְׁנִין וּמִית:
@134 וַחֲיָא לֶמֶךְ מְאָה וְתַמְנִין וְתַרְתֵּין שְׁנִין וְאוֹלִיד בָּר:
@135 וּקְרָא יָת שְׁמֵהּ נֹחַ לְמֵימָר דֵּין יְנַחֲמִנָּנָא מֵעוֹבָדָנָא וּמִלֵּאוּת יְדָנָא מִן אַרְעָא דִּי לַטְטַהּ יְיָ:
@136 וַחֲיָא לֶמֶךְ בָּתַר דְּאוֹלִיד יָת נֹחַ חֲמֵשׁ מְאָה וְתִשְׁעִין וַחֲמֵשׁ שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@137 וַהֲווֹ כָּל יוֹמֵי לֶמֶךְ שְׁבַע מְאָה וְשַׁבְעִין וּשְׁבַע שְׁנִין וּמִית:
@138 וַהֲוָה נֹחַ בַּר חֲמֵשׁ מְאָה שְׁנִין וְאוֹלִיד נֹחַ יָת שֵׁם יָת חָם וְיָת יָפֶת:
@139 וַהֲוָה כַּד שְׁרִיאוּ בְנֵי אֱנָשָׁא לְמִסְגֵּי עַל אַפֵּי אַרְעָא וּבְנָתָא אִתְיְלִידוּ לְהוֹן:
@140 וַחֲזוֹ בְנֵי רַבְרְבַיָּא יָת בְּנַת אֱנָשָׁא אֲרֵי שַׁפִּירָן אִנוּן וּנְסִיבוּ לְהוֹן נְשִׁין מִכֹּל דִּי אִתְרְעִיאוּ:
@141 וַאֲמַר יְיָ לָא יִתְקַיַם דָרָא בִישָׁא הָדֵין קֳדָמַי לְעַלָם בְּדִיל דְאִנוּן בִּשְׂרָא וְעוֹבָדֵיהוֹן בִּישַׁיָא אַרְכָא יְהִיבַת לְהוֹן מְאָה וְעַשְׂרִין שְׁנִין אִם יְתוּבוּן:
@142 גִּבָּרַיָּא הֲווֹ בְאַרְעָא בְּיוֹמַיָּא הָאִנּוּן וְאַף בָּתַר כֵּן דִּי יַעֲלוּן בְּנֵי רַבְרְבַיָּא לְוַת בְּנַת אֱנָשָׁא וִילִידָן לְהוֹן אִנוּן גִּבָּרַיָּא דִּמֵעָלְמָא אֱנָשִׁין דִּשְׁמָא:
@143 וַחֲזָא יְיָ אֲרֵי סְגִיאַת בִּישַׁת אֱנָשָׁא בְּאַרְעָא וְכָל יִצְרָא מַחְשְׁבַת לִבֵּהּ לְחוֹד בִּישׁ כָּל יוֹמָא:
@144 וְתַב יְיָ בְּמֵימְרֵהּ אֲרֵי עֲבַד יָת אֱנָשָׁא בְּאַרְעָא וַאֲמַר בְּמֵימְרֵהּ לְמִתְּבַר תָּקְפְּהוֹן כִּרְעוּתֵהּ:
@145 וַאֲמַר יְיָ אֶמְחֵי יָת אֲנָשָׁא דִּי בְרֵאתִי מֵעַל אַפֵּי אַרְעָא מֵאֱנָשָׁא עַד בְּעִירָא עַד רִיחֲשָׁא וְעַד עוֹפָא דִּשְׁמַיָּא אֲרֵי תָבִית בְּמֵימְרִי אֲרֵי עֲבַדְתִּנוּן:
@146 וְנֹחַ אַשְׁכַּח רַחֲמִין קֳדָם יְיָ: פפפ:

@1 **בראשית.** אמר רבי יצחק לא היה צריך להתחיל [את] התורה אלא (שמות יב ב) מהחודש הזה לכם, שהיא מצוה ראשונה שנצטוו [בה] ישראל, ומה טעם פתח בבראשית, משום כח מעשיו הגיד לעמו לתת להם נחלת גוים (תהלים קיא ו) , שאם יאמרו אמות העולם לישראל לסטים אתם, שכבשתם ארצות שבעה גוים, הם אומרים להם כל הארץ של הקדוש ברוך הוא היא, הוא בראה ונתנה לאשר ישר בעיניו, ברצונו נתנה להם וברצונו נטלה מהם ונתנה לנו: **בראשית ברא.** אין המקרא הזה אומר אלא דרשני, כמו שדרשוהו רבותינו זכרונם לברכה בשביל התורה שנקראת (משלי ח כב) ראשית דרכו, ובשביל ישראל שנקראו (ירמיה ב ג) ראשית תבואתו. ואם באת לפרשו כפשוטו כך פרשהו בראשית בריאת שמים וארץ והארץ היתה תהו ובהו וחשך ויאמר אלהים יהי אור. ולא בא המקרא להורות סדר הבריאה לומר שאלו קדמו, שאם בא להורות כך, היה לו לכתוב בראשונה ברא את השמים וגו' , שאין לך ראשית במקרא שאינו דבוק לתבה של אחריו, כמו (שם כו א) בראשית ממלכות יהויקים, (בראשית י י) ראשית ממלכתו, (דברים יח ד) ראשית דגנך, אף כאן אתה אומר בראשית ברא אלהים וגו' , כמו בראשית ברא. ודומה לו (הושע א ב) תחלת דבר ה' בהושע, כלומר תחלת דבורו של הקדוש ברוך הוא בהושע, ויאמר ה' אל הושע וגו' . ואם תאמר להורות בא שאלו תחלה נבראו, ופירושו בראשית הכל ברא אלו, ויש לך מקראות שמקצרים לשונם וממעטים תבה אחת, כמו (איוב ג י) כי לא סגר דלתי בטני, ולא פירש מי הסוגר, וכמו (ישעיה ח ד) ישא את חיל דמשק, ולא פירש מי ישאנו, וכמו (עמוס ו יב) אם יחרוש בבקרים, ולא פרש אם יחרוש אדם בבקרים, וכמו (ישעיה מו י) מגיד מראשית אחרית, ולא פרש מגיד מראשית דבר אחרית דבר. אם כן תמה על עצמך, שהרי המים קדמו, שהרי כתיב ורוח אלהים מרחפת על פני המים, ועדיין לא גלה המקרא בריאת המים מתי היתה, הא למדת שקדמו המים לארץ. ועוד שהשמים מאש ומים נבראו, על כרחך לא למד המקרא סדר המוקדמים והמאוחרים כלום: **ברא אלהים.** ולא אמר ברא ה', שבתחלה עלה במחשבה לבראתו במדת הדין, ראה שאין העולם מתקים, הקדים מדת רחמים ושתפה למדת הדין, היינו דכתיב (להלן ב ד) ביום עשות ה' אלהים ארץ ושמים:
@2 **תהו ובהו.** תהו לשון תמה ושממון שאדם תוהא ומשתומם על בהו שבה: **תהו.** אישטורדישו''ן בלע''ז [מבוכה]: **בהו.** לשון רקות וצדו: **על פני תהום.** על פני המים שעל הארץ. **ורוח אלהים מרחפת.** כסא הכבוד עומד באויר ומרחף על פני המים ברוח פיו של הקדוש ברוך הוא ובמאמרו, כיונה המרחפת על הקן אקוביטי''ר בלע''ז [לכסות]:
@4 **וירא אלהים את האור כי טוב ויבדל.** אף בזה אנו צריכים לדברי אגדה ראהו שאינו כדאי להשתמש בו רשעים והבדילו לצדיקים לעתיד לבא. ולפי פשוטו כך פרשהו ראהו כי טוב ואין נאה לו ולחשך שיהיו משתמשין בערבוביא, וקבע לזה תחומו ביום ולזה תחומו בלילה:
@5 **יום אחד.** לפי סדר [לשון] הפרשה היה לו לכתוב יום ראשון, כמו שכתב בשאר הימים שני, שלישי, רביעי. למה כתב אחד, לפי שהיה הקדוש ברוך הוא יחיד בעולמו שלא נבראו המלאכים עד יום שני, כך מפורש בבראשית רבה (ג ח) :
@6 **יהי רקיע.** יחזק הרקיע. שאף על פי שנבראו שמים ביום ראשון, עדיין לחים היו, וקרשו בשני מגערת הקדוש ברוך הוא באמרו יהי רקיע, וזהו שכתוב (איוב כו יא) עמודי שמים ירופפו כל יום ראשון. ובשני יתמהו מגערתו, כאדם שמשתומם ועומד מגערת המאיים עליו: **בתוך המים.** באמצע המים, שיש הפרש בין מים העליונים לרקיע כמו בין הרקיע למים שעל הארץ, הא למדת שהם תלוים במאמרו של מלך:
@7 **ויעש אלהים את הרקיע.** תקנו על עמדו והיא עשיתו, כמו (דברים כא יב) ועשתה את צפרניה: מעל לרקיע. על הרקיע לא נאמר אלא **מעל לרקיע.** לפי שהן תלויים באויר. ומפני מה לא נאמר כי טוב ביום שני, לפי שלא נגמרה מלאכת המים עד יום שלישי, והרי התחיל בה בשני, ודבר שלא נגמר אינו במלואו ובטובו, ובשלישי שנגמרה מלאכת המים והתחיל מלאכה אחרת וגמרה, כפל בו כי טוב שני פעמים, אחד לגמר מלאכת השני ואחד לגמר מלאכת היום:
@8 **ויקרא אלהים לרקיע שמים.** שא מים, שם מים, אש ומים, שערבן זה בזה ועשה מהם שמים:
@9 **יקוו המים.** [שהיו] שטוחין על פני כל הארץ והקום באוקינוס, הוא הים הגדול שבכל הימים:
@10 **קרא ימים.** והלא ים אחד הוא, אלא אינו דומה טעם דג העולה [מן הים] בעכו לטעם דג העולה [מן הים] באספמיא:
@11 **תדשא הארץ דשא עשב.** לא דשא לשון עשב ולא עשב לשון דשא, ולא היה לשון המקרא לומר תעשיב הארץ, שמיני דשאים מחלקין, כל אחד לעצמו נקרא עשב פלוני, ואין לשון למדבר לומר דשא פלוני, שלשון דשא הוא לבישת הארץ כשהיא מתמלאת בדשאים: **תדשא הארץ.** תתמלא ותתכסה לבוש עשבים. בלשון לעז נקרא דשא אירבידי''ץ [מכלול העשבים] כלן בערבוביא, וכל שורש לעצמו נקרא עשב: **מזריע זרע.** שיגדל בו זרעו לזרוע ממנו במקום אחר: **עץ פרי.** שיהא טעם העץ כטעם הפרי, והיא לא עשתה כן, אלא (פסוק יב) ותוצא הארץ עץ עשה פרי, ולא העץ פרי, לפיכך כשנתקלל אדם על עונו נפקדה גם היא על עונה ונתקללה: **אשר זרעו בו.** הן גרעני כל פרי, שמהן האילן צומח כשנוטעין אותן:
@12 **ותוצא הארץ** וגו' **.** אף על פי שלא נאמר למינהו בדשאין בציווייהן, שמעו שנצטוו האילנות על כך, ונשאו קל וחמר בעצמן, כמפורש באגדה בשחיטת חלין (חולין ס.) :
@14 **יהי מארת** וגו' **.** מיום ראשון נבראו, וברביעי צוה עליהם להתלות ברקיע, וכן כל תולדות שמים וארץ נבראו מיום ראשון, וכל אחד ואחד נקבע ביום שנגזר עליו, הוא שכתוב (פסוק א) את השמים, לרבות תולדותיהם, ואת הארץ, לרבות תולדותיה: **יהי מארת.** חסר וי''ו כתיב, על שהוא יום מארה ליפול אסכרה בתינוקות, הוא ששנינו ברביעי היו מתענים על אסכרה שלא תפל בתינוקות: **להבדיל בין היום ובין הלילה.** משנגנז האור הראשון, אבל בשבעת ימי בראשית שמשו האור והחשך הראשונים יחד בין ביום ובין בלילה: **והיו לאתת.** כשהמאורות לוקין סימן רע הוא לעולם, שנאמר (ירמיה י ב) מאותות השמים אל תחתו, בעשותכם רצון הקדוש ברוך הוא אין אתם צריכין לדאג מן הפרענות: **ולמועדים.** על שם העתיד, שעתידים ישראל להצטוות על המועדות, והם נמנים למולד הלבנה: **ולימים.** שמוש החמה חצי יום ושמוש הלבנה חציו, הרי יום שלם: **ושנים.** לסוף שלש מאות ששים וחמשה ימים יגמרו מהלכם בשנים עשר מזלות המשרתים אותם והיא שנה. (וחוזרים ומתחילים פעם שניה לסבב בגלגל כמהלכן הראשון) :
@15 **והיו למאורות.** עוד זאת ישמשו שיאירו לעולם:
@16 **המארת הגדלים** וגו' **.** שוים נבראו, ונתמעטה הלבנה על שקטרגה ואמרה אי אפשר לשני מלכים שישתמשו בכתר אחד: **ואת הכוכבים.** על ידי שמיעט את הלבנה, הרבה צבאיה להפיס דעתה:
@20 **נפש חיה.** שיש בה חיות: **שרץ.** כל דבר חי שאינו גבוה מן הארץ קרוי שרץ, בעוף כגון זבובים, בשקצים כגון נמלים וחפושין ותולעים, ובבריות כגון חולד ועכבר וחומט וכיוצא בהם, וכל הדגים:
@21 **התנינם.** דגים גדולים שבים. ובדברי אגדה הוא לויתן ובן זוגו שבראם זכר ונקבה והרג את הנקבה ומלחה לצדיקים לעתיד לבא, שאם יפרו וירבו לא יתקים העולם בפניהם: **נפש החיה.** שיש בה חיות:
@22 **ויברך אתם.** לפי שמחסרים אותן וצדין מהם ואוכלין אותם הצרכו לברכה. ואף החיות הוצרכו לברכה, אלא מפני הנחש שעתיד לקללה, לכך לא ברכן, שלא יהא הוא בכלל: **פרו.** לשון פרי, כלומר עשו פירות: **ורבו.** אם לא אמר אלא פרו היה אחד מוליד אחד ולא יותר, ובא ורבו שאחד מוליד הרבה:
@24 **תוצא הארץ.** הוא שפרשתי (פסוק יד) שהכל נברא מיום ראשון ולא הצרכו אלא להוציאם: **נפש חיה.** שיש בה חיות: **ורמש.** הם שרצים שהם נמוכים ורומשים על הארץ, נראים כאלו נגררים, שאין הלוכן נכר. כל לשון רמש ושרץ בלשוננו קונמובר''יש בלע''ז [רוחשים]:
@25 **ויעש.** תקנם בצביונם ובקומתן:
@26 **נעשה אדם.** ענותנותו של הקדוש ברוך הוא למדנו מכאן, לפי שהאדם בדמות המלאכים ויתקנאו בו לפיכך נמלך בהם, וכשהוא דן את המלכים הוא נמלך בפמליא שלו, שכן מצינו באחאב שאמר לו מיכה (מלכים א' כב יט) ראיתי את ה' ישב על כסאו וכל צבא השמים עמד עליו מימינו ומשמאלו, וכי יש ימין ושמאל לפניו, אלא אלו מימינים לזכות ואלו משמאילין לחובה. וכן (דניאל ד יד) בגזרת עירין פתגמא ומאמר קדישין שאלתא, אף כאן בפמליא שלו נמלך ונטל רשות, אמר להם יש בעליונים כדמותי, אם אין בתחתונים כדמותי, הרי יש קנאה במעשה בראשית: **נעשה אדם.** אף על פי שלא סייעוהו ביצירתו ויש מקום למינים לרדות, לא נמנע הכתוב מללמד דרך ארץ ומדת ענוה שיהא הגדול נמלך ונוטל רשות מן הקטן. ואם כתב אעשה אדם לא למדנו שיהא מדבר עם בית דינו אלא עם עצמו, ותשובת המינים כתב בצדו ויברא אלהים את האדם, ולא כתב ויבראו: **בצלמנו.** בדפוס שלנו: **כדמותנו.** להבין ולהשכיל: **וירדו בדגת הים.** יש בלשון הזה לשון רדוי ולשון ירידה, זכה רודה בחיות ובבהמות, לא זכה נעשה ירוד לפניהם והחיה מושלת בו:
@27 **ויברא אלהים את האדם בצלמו.** בדפוס העשוי לו, שהכל נברא במאמר והוא נברא בידים, שנאמר (תהלים קלט ה) ותשת עלי כפכה, נעשה בחותם כמטבע העשויה על ידי רושם שקורין קוי''ן בלע''ז [מטבע] וכן הוא אומר (איוב לח יד) תתהפך כחמר חותם: **בצלם אלהים ברא אתו.** פרש לך שאותו צלם המתקן לו צלם דיוקן יוצרו הוא: **זכר ונקבה ברא אתם.** ולהלן הוא אומר (בראשית ב כא) ויקח אחת מצלעתיו וגו' , מדרש אגדה שבראו שני פרצופין בבריאה ראשונה ואחר כך חלקו. ופשוטו של מקרא, כאן הודיעך שנבראו שניהם בששי ולא פרש לך כיצד בריתן ופרש לך במקום אחר:
@28 **וכבשה.** חסר וי''ו, ללמדך שהזכר כובש את הנקבה שלא תהא יצאנית, ועוד ללמדך שהאיש שדרכו לכבוש מצוה על פריה ורביה ולא האשה:
@29 **לכם יהיה לאכלה. ולכל חית הארץ.** השוה להם הכתוב בהמות וחיות למאכל, ולא הרשה לאדם ולאשתו להמית בריה ולאכל בשר, אך כל ירק עשב יאכלו יחד כלם, וכשבאו בני נח התיר להם בשר, שנאמר (להלן ט ג) כל רמש אשר הוא חי וגו' כירק עשב שהתרתי לאדם הראשון, נתתי לכם את כל:
@31 **יום הששי.** הוסיף ה' בששי בגמר מעשה בראשית, לומר שהתנה עמהם על מנת שיקבלו עליהם ישראל חמשה חומשי תורה. דבר אחר יום הששי כלם תלוים ועומדים עד יום הששי, הוא ששי בסיון המוכן למתן תורה:
@33 **ויכל אלהים ביום השביעי.** רבי שמעון אומר בשר ודם שאינו יודע עתיו ורגעיו צריך להוסיף מחול על הקדש, הקדוש ברוך הוא שיודע עתיו ורגעיו נכנס בו כחוט השערה ונראה כאלו כלה בו ביום. דבר אחר מה היה העולם חסר, מנוחה, באת שבת באת מנוחה, כלתה ונגמרה המלאכה:
@34 **ויברך ויקדש.** ברכו במן שכל ימות השבת היה יורד להם עמר לגלגלת ובששי לחם משנה, וקדשו במן שלא ירד בו מן כלל והמקרא כתוב על שם העתיד: **אשר ברא אלהים לעשות.** המלאכה שהיתה ראויה לעשות בשבת כפל ועשאה בששי, כמו שמפורש בבראשית רבה (יא י) :
@35 **אלה.** האמורים למעלה: **תולדות השמים והארץ בהבראם ביום עשות ה'.** למדך שכלם נבראו ביום ראשון. דבר אחר בהבראם, בה' בראם שנאמר (ישעיה כו ד) ביה ה' צור עולמים בשתי אותיות הללו של שם יצר שני עולמים, ולמדך כאן שהעולם הזה נברא בה''א (רמז כמו שה''א פתוחה למטה, כך העולם פתוח לשבים בתשובה. ועולם הבא נברא ביו''ד לומר שצדיקים שבאותו זמן מועטים כמו י' שהיא קטנה באותיות) . רמז שירדו הרשעים למטה לראות שחת כה''א זאת שסתומה מכל צדדים ופתוחה למטה לרדת דרך שם:
@36 **טרם יהיה בארץ.** כל טרם שבמקרא לשון עד לא הוא, ואינו לשון קודם, ואינו נפעל לומר הטרים כאשר יאמר הקדים, וזה מוכיח, ועוד אחר (שמות ט ל) כי טרם תיראון, עדין לא תיראון. ואף זה תפרש עדיין לא היה בארץ כשנגמרה בריאת העולם בששי קודם שנברא אדם: **וכל עשב השדה טרם יצמח.** עדיין לא צמח, ובשלישי שכתוב ותוצא הארץ, על פתח הקרקע עמדו עד יום ששי: **כי לא המטיר.** ומה טעם לא המטיר, לפי שאדם אין לעבוד את האדמה ואין מכיר בטובתם של גשמים, וכשבא אדם וידע שהם צרך לעולם התפלל עליהם וירדו, וצמחו האילנות והדשאים: **ה' אלהים.** ה' הוא שמו, אלהים שהוא שופט ושליט על כל, וכן פרוש זה בכל מקום לפי פשוטו, ה' שהוא אלהים:
@37 **ואד יעלה.** לענין בריאתו של אדם, העלה את התהום והשקה העננים לשרות העפר ונברא אדם, כגבל זה שנותן מים ואחר כך לש את העיסה, אף כאן והשקה ואחר כך וייצר:
@38 **וייצר.** שתי יצירות, יצירה לעולם הזה ויצירה לתחית המתים, אבל בבהמה שאינה עומדת לדין לא נכתב ביצירה שני יודי''ן: **עפר מן האדמה.** צבר עפרו מכל האדמה מארבע רוחות, שכל מקום שימות שם תהא קולטתו לקבורה. דבר אחר נטל עפרו ממקום שנאמר בו (שמות כ כא) מזבח אדמה תעשה לי, אמר הלואי תהיה לו כפרה ויוכל לעמוד: **ויפח באפיו.** עשאו מן התחתונים ומן העליונים, גוף מן התחתונים ונשמה מן העליונים, לפי שביום ראשון נבראו שמים וארץ. בשני ברא רקיע לעליונים. בשלישי תראה היבשה לתחתונים. ברביעי ברא מאורות לעליונים. בחמישי ישרצו המים לתחתונים, הוזקק הששי לבראות בו בעליונים ובתחתונים, ואם לאו יש קנאה במעשה בראשית, שיהיו אלו רבים על אלו בבריאת יום אחד: **לנפש חיה.** אף בהמה וחיה נקראו נפש חיה, אך זו של אדם חיה שבכלן, שנתוסף בו דעה ודבור:
@39 **מקדם.** במזרחו של עדן נטע את הגן. ואם תאמר הרי כבר כתב (לעיל א כז) ויברא אלהים את האדם וגו' . ראיתי בברייתא של ר' אלעזר בנו של ר' יוסי הגלילי משלושים ושתים מדות שהתורה נדרשת, וזו אחת מהן כלל שלאחריו מעשה הוא פרטו של ראשון. ויברא את האדם זהו כלל, סתם בריאתו מהיכן וסתם מעשיו, חזר ופירש וייצר ה' אלהים וגו' , ויצמח לו גן עדן, ויניחהו בגן עדן, ויפל עליו תרדמה, השומע סבור שהוא מעשה אחר, ואינו אלא פרטו של ראשון. וכן אצל הבהמה חזר וכתב ויצר ה' אלהים מן האדמה כל חית השדה (ב יט) , כדי לפרש ויבא אל האדם לקרות שם, וללמד על העופות שנבראו מן הרקק:
@40 **ויצמח.** לענין הגן הכתוב מדבר: **בתוך הגן.** באמצע:
@42 **פישון.** הוא נילוס נהר מצרים ועל שם שמימיו מתברכין ועולין ומשקין את הארץ נקרא פישון, כמו ופשו פרשיו. דבר אחר פישון שהוא מגדל פשתן שנאמר על מצרים (ישעיה יט ט) ובשו עובדי פשתים:
@44 **גיחון.** שהיה הולך והומה והמייתו גדולה מאד, כמו (שמות כא כח) כי יגח, שמנגח והולך והומה:
@45 **חדקל.** שמימיו חדין וקלין: **פרת.** שמימיו פרין ורבין ומברין את האדם. כוש ואשור. עדיין לא היו, וכתב המקרא על שם העתיד: **קדמת אשור.** למזרחה של אשור: **הוא פרת.** החשוב על כלם, הנזכר על שם ארץ ישראל:
@46 **ויקח.** לקחו בדברים נאים ופתהו ליכנס:
@49 **לא טוב היות** וגו' **.** שלא יאמרו שתי רשויות הן הקדוש ברוך הוא יחיד בעליונים ואין לו זוג, וזה יחיד בתחתונים ואין לו זוג: **עזר כנגדו.** זכה עזר, לא זכה כנגדו להלחם:
@50 **ויצר** וגו' **מן האדמה.** היא יצירה היא עשייה האמורה למעלה (לעיל א כה) ויעש אלהים את חית הארץ וגו' , אלא בא ופירש שהעופות מן הרקק נבראו, לפי שאמר למעלה מן המים נבראו וכאן אמר מן הארץ נבראו. ועוד למדך כאן שבשעת יצירתן מיד בו ביום הביאם אל האדם לקרות להם שם. ובדברי אגדה יצירה זו לשון רידוי וכבוש, כמו (דברים כ יט) כי תצור אל עיר, שכבשן תחת ידו של אדם: **וכל אשר יקרא לו האדם נפש חיה** וגו' **.** סרסהו ופרשהו כל נפש חיה אשר יקרא לו האדם שם הוא שמו לעולם:
@51 , כא **ולאדם לא מצא עזר ויפל ה' אלהים תרדמה.** כשהביאן הביאן לפניו כל מין ומין זכר ונקבה, אמר לכלם יש בן זוג ולי אין בן זוג, מיד ויפל: **מצלעותיו.** מסטריו, כמו (שמות כו כ) ולצלע המשכן, זהו שאמרו שני פרצופים נבראו: **ויסגר.** מקום החתך: **וישן ויקח.** שלא יראה חתיכת הבשר שממנו נבראת ותתבזה עליו:
@53 **ויבן.** כבנין, רחבה מלמטה וקצרה מלמעלה לקבל הולד, כאוצר של חטים שהוא רחב מלמטה וקצר מלמעלה, שלא יכביד משאו על קירותיו: **ויבן** וגו' **את הצלע** וגו' **לאשה.** להיות אשה, כמו (שופטים ח כז) ויעש אותו גדעון לאפוד, להיות אפוד:
@54 **זאת הפעם.** מלמד שבא אדם על כל בהמה וחיה ולא נתקררה דעתו בהם עד שבא על חוה: **לזאת יקרא אשה כי מאיש** וגו' **.** לשון נופל על לשון, מכאן שנברא העולם בלשון הקדש:
@55 **על כן יעזב איש.** רוח הקדש אומרת כן, לאסור על בני נח את העריות: **לבשר אחד.** הולד נוצר על ידי שניהם, ושם נעשה בשרם אחד:
@56 **ולא יתבוששו.** שלא היו יודעים דרך צניעות להבחין בין טוב לרע, ואף על פי שנתנה בו דעה לקרות שמות, לא נתן בו יצר הרע עד אכלו מן העץ ונכנס בו יצר הרע וידע מה בין טוב לרע:
@57 **והנחש היה ערום.** מה ענין זה לכאן היה לו לסמוך (פסוק כא) ויעש לאדם ולאשתו כתנות עור וילבישם. אלא למדך מאיזו עלה קפץ הנחש עליהם, ראה אותם ערומים ועוסקים בתשמיש לעין כל ונתאוה לה: **ערום מכל.** לפי ערמתו וגדלתו היתה מפלתו, ערום מכל, ארור מכל: **אף כי אמר** וגו' **.** שמא אמר לכם לא תאכלו מכל וגו' . ואף על פי שראה אותם אוכלים משאר פרות, הרבה עליה דברים כדי שתשיבנו ויבא לדבר באותו העץ:
@59 **ולא תגעו בו.** הוסיפה על הצווי, לפיכך באה לידי גרעון, הוא שנאמר (משלי ל ו) אל תוסף על דבריו:
@60 **לא מות תמתון.** דחפה עד שנגעה בו, אמר לה כשם שאין מיתה בנגיעה כך אין מיתה באכילה:
@61 **כי יודע.** כל אמן שונא את בני אמנותו, מן העץ אכל וברא את העולם: **והייתם כאלהים.** יוצרי עולמות:
@62 **ותרא האשה.** ראתה דבריו של נחש והנאו לה והאמינתו: **כי טוב העץ.** להיות כאלהים: **וכי תאוה הוא לעינים.** כמו שאמר לה ונפקחו עיניכם: **ונחמד להשכיל.** כמו שאמר לה יודעי טוב ורע: **ותתן גם לאישה עמה.** שלא תמות היא ויחיה הוא, וישא אשה אחרת: **גם.** לרבות כל בהמה וחיה:
@63 **ותפקחנה עיני שניהם.** לענין החכמה דבר הכתוב ולא לענין ראיה ממש, וסוף המקרא מוכיח: **וידעו כי עירמם הם.** אף הסומא יודע כשהוא ערום, אלא מהו וידעו כי עירומים הם, מצוה אחת היתה בידם ונתערטלו המנה: **עלה תאנה.** הוא העץ שאכלו ממנו, בדבר שנתקלקלו בו נתקנו, אבל שאר העצים מנעום מלטול עליהם. ומפני מה לא נתפרסם העץ, שאין הקדוש ברוך הוא חפץ להונות בריה, שלא יכלימוהו ויאמרו זהו שלקה העולם על ידו. מדרש רבי תנחומא (וירא יד) :
@64 **וישמעו.** יש מדרשי אגדה רבים וכבר סדרום רבותינו על מכונם בבראשית רבה (יט ו) ובשאר מדרשות ואני לא באתי אלא לפשוטו של מקרא ולאגדה המישבת דברי המקרא דבר דבור על אפניו. ומשמעו, שמעו את קול הקדוש ברוך הוא שהיה מתהלך בגן: **לרוח היום.** לאותו רוח שהשמש באה משם וזו היא מערבית, שלפנות ערב חמה במערב, והם סרחו בעשירית:
@65 **איכה.** יודע היה היכן הוא, אלא לכנס עמו בדברים, שלא יהא נבהל להשיב אם יענישהו פתאום. וכן בקין (בראשית ד ט) אמר לו אי הבל אחיך, וכן בבלעם (במדבר כב ט) מי האנשים האלה עמך, לכנס עמהם בדברים, וכן בחזקיה בשלוחי (אויל) מרודך בלאדן (ישעיה לט א) :
@67 **מי הגיד לך.** מאין לך לדעת מה בשת יש בעומד ערום: **המן העץ.** בתמיהה:
@68 **אשר נתת עמדי.** כאן כפר בטובה:
@69 **השיאני.** הטעני כמו (דה''י ב' לב טו) אל ישיא אתכם חזקיהו:
@70 **כי עשית זאת.** מכאן שאין מהפכים בזכותו של מסית, שאלו שאלו למה עשית זאת, היה לו להשיב דברי הרב ודברי התלמיד דברי מי שומעין: **מכל הבהמה ומכל חית השדה.** אם מבהמה נתקלל מחיה לא כל שכן, העמידו רבותינו מדרש זה במסכת בכורות (דף ח א) ללמד שימי עבורו של נחש שבע שנים: **על גחונך תלך.** רגלים היו לו ונקצצו טו **ואיבה אשית.** אתה לא נתכונת אלא שימות אדם כשיאכל הוא תחלה ותשא את חוה, ולא באת לדבר אל חוה תחלה אלא לפי שהנשים קלות להתפתות ויודעות לפתות את בעליהן, לפיכך ואיבה אשית: **ישופך.** יכתתך, כמו (דברים ט כא) ואכת אתו, ותרגומו ושפית יתיה: **ואתה תשופנו עקב.** לא יהא לך קומה ותשכנו בעקבו, ואף משם תמיתנו. ולשון תשופנו כמו (ישעיה מ כד) נשף בהם, כשהנחש בא לנשוך הוא נושף כמין שריקה, ולפי שהלשון נופל על הלשון כתב לשון נשיפה בשניהם:
@72 **עצבונך.** זה צער גדול בנים: **והרנך.** זה צער העבור: **בעצב תלדי בנים.** זה צער הלידה: **ואל אישך תשוקתך.** לתשמיש ואף על פי כן אין לך מצח לתבעו בפה אלא הוא ימשול בך, הכל ממנו ולא ממך: **תשוקתך.** תאותך, כמו (ישעיה כט ח) ונפשו שוקקה:
@73 **ארורה האדמה בעבורך.** מעלה לך דברים ארורים כגון זבובים ופרעושים ונמלים, משל ליוצא לתרבות רעה והבריות מקללות שדים שינק מהם:
@74 **וקוץ ודרדר תצמיח לך.** הארץ כשתזרענה מיני זרעים תצמיח קוץ ודרדר קונדס ועכביות, והן נאכלים על ידי תקון: **ואכלת את עשב השדה.** ומה קללה היא זו, והלא בברכה נאמר לו (לעיל א כט) הנה נתתי לכם את כל עשב זורע זרע וגו' . אלא מה אמור כאן בראש הענין (פסוק יז) ארורה האדמה בעבורך בעצבון תאכלנה, ואחר העצבון וקוץ ודרדר תצמיח לך, כשתזרענה קטניות או ירקות גנה היא תצמיח לך קוצים ודרדרים ושאר עשבי שדה, ועל כרחך תאכלם:
@75 **בזעת אפיך.** לאחר שתטרח בו הרבה:
@76 **ויקרא האדם.** חזר הכתוב לענינו הראשון ויקרא האדם שמות, ולא הפסיק אלא ללמדך שעל ידי קריאת שמות נזדוגה לו חוה, כמו שכתוב (לעיל ב כ) ולאדם לא מצא עזר כנגדו, לפיכך ויפל תרדמה, ועל ידי שכתב (שם פסוק כה) ויהיו שניהם ערומים, סמך לו פרשת הנחש, להודיעך שמתוך שראה ערותה וראה אותם עסוקים בתשמיש נתאוה לה ובא עליהם במחשבה ובמרמה: **חוה.** נופל על לשון חיה, שמחיה את ולדותיה, כאשר תאמר מה הוה לאדם, (קהלת ב כב) בלשון היה:
@77 **כתנות עור.** יש דברי אגדה אומרים חלקים כצפורן היו מדובקים על עורן. ויש אומרים דבר הבא מן העור, כגון צמר הארנבים שהוא רך וחם ועשה להם כתנות ממנו:
@78 **היה כאחד ממנו.** הרי הוא יחיד בתחתונים כמו שאני יחיד בעליונים, ומה היא יחידותו, לדעת טוב ורע ומה שאין כן בבהמה ובחיה: **ועתה פן ישלח ידו.** ומשיחיה לעולם הרי הוא קרוב להטעות הבריות אחריו ולומר אף הוא אלוה. ויש מדרשי אגדה, אבל אין מישבין על פשוטו:
@80 **מקדם לגן עדן.** במזרחו של גן עדן, חוץ לגן: **את הכרובים.** מלאכי חבלה: **החרב המתהפכת.** ולה להט לאים עליו מלכנס עוד לגן. תרגום של להט שנן, והוא כמו שלף שננא, [להב]. ומדרש אגדה יש, ואני איני בא אלא לפשוטו:
@81 **והאדם ידע.** כבר קודם הענין של מעלה, קודם שחטא ונטרד מגן עדן, וכן ההריון והלידה, שאם כתב וידע אדם נשמע שלאחר שנטרד היו לו בנים: **קין.** על שם קניתי איש: **את ה'.** כמו עם ה', כשברא אותי ואת אישי הוא לבדו בראנו, אבל בזה שותפים אנו עמו: **את קין' את אחיו את הבל.** שלש אתים ריבוים הם, מלמד שתאומה נלדה עם קין, ועם הבל נלדו שתים, לכך נאמר ותוסף:
@82 **רעה צאן.** לפי שנתקללה האדמה, פרש לו מעבודתה:
@83 **מפרי האדמה.** מן הגרוע, ויש אגדה שאומרת זרע פשתן היה:
@84 **וישע.** ויפן, וכן (פסוק ה) לא שעה אל מנחתו, לא פנה, וכן (שמות ה ט) ואל ישעו, אל יפנו. וכן (איוב יד ו) שעה מעליו, פנה מעליו: **וישע.** ירדה אש וליחכה מנחתו:
@87 **הלא אם תיטיב.** כתרגומו פרושו: **לפתח חטאת רבץ.** לפתח קברך חטאך שמור: **ואליך תשוקתו.** של חטאת, הוא יצר הרע, תמיד שוקק ומתאוה להכשילך: **ואתה תמשל בו.** אם תרצה תתגבר עליו:
@88 **ויאמר קין אל הבל.** נכנס עמו בדברי ריב ומצה להתגולל עליו להרגו, ויש בזה מדרשי אגדה אך זה ישובו של מקרא:
@89 **אי הבל אחיך.** להכנס עמו בדברי נחת, אולי ישוב ויאמר אני הרגתיו וחטאתי לך: **לא ידעתי.** נעשה כגונב דעת העליונה: **השומר אחי.** לשון תמה הוא, וכן כל ה, א הנקודה בחטף פתח:
@90 **דמי אחיך.** דמו ודם זרעיותיו. דבר אחר שעשה בו פצעים הרבה שלא היה יודע מהיכן נפשו יוצאה:
@91 **ארור אתה מן האדמה.** יותר ממה שנתקללה היא כבר בעונה, וגם בזו הוסיפה לחטוא: **אשר פצתה את פיה לקחת את דמי אחיך** וגו' **.** והנני מוסיף לה קללה לא תסף תת כחה:
@92 **נע ונד.** אין לך רשות לדור במקום אחד:
@93 **גדול עוני מנשא.** בתמיהה, אתה טוען עליונים ותחתונים, ועוני אי אפשר לטעון:
@95 **לכן כל הרג קין.** זה אחד מן המקראות שקצרו דבריהם ורמזו ולא פרשו. לכן כל הרג קין, לשון גערה, כה יעשה לו, כך וכך ענשו, ולא פרש ענשו: **שבעתים יקם.** איני רוצה להנקם מקין עכשיו, לסוף שבעה דורות אני נוקם נקמתי ממנו שיעמוד למך מבני בניו ויהרגהו. וסוף המקרא שאמר שבעתים יוקם, והיא נקמת הבל מקין, הא למדנו שתחלת מקרא לשון גערה היא, שלא תהא בריה מזיקתו. וכיוצא בו (שמואל ב' ה ח) ויאמר דוד כל מכה יבוסי ויגע בצנור ולא פרש מה יעשה לו, אבל דבר הכתוב ברמז כל מכה יבוסי ויגע בצנור, ויקרב אל השער ויכבשנו, ואת העורים וגו' , וגם אותם יכה על אשר אמרו העור והפסח לא יבא דוד אל תוך הבית, המכה את אלו אני אעשנו ראש ושר, כאן קצר דבריו ובדברי הימים (א יא ו) פרש יהיה לראש ולשר: **וישם ה' לקין אות.** חקק לו אות משמו במצחו (כל מוצאי יהרגני הבהמות והחיות, אבל בני אדם עדיין לא היו שיירא מהם רק אביו ואמו, ומהם לא היה ירא שיהרגוהו. אלא אמר עד עכשיו היה פחדתי על כל החיות כמו שנאמר ומוראכם וגו', ועכשיו בשביל עון זה לא ייראו ממני החיות ויהרגוני, מיד וישם ה' לקין אות, החזיר מוראו על הכל) :
@96 **ויצא קין.** יצא בהכנעה כגונב דעת העליונה: **בארץ נוד.** בארץ שכל הגולים נדים שם: **קדמת עדן.** שם גלה אביו כשגורש מגן עדן, שנאמר (לעיל ג כד) וישכן מקדם לגן עדן, את שמירת דרך מבוא הגן, שיש ללמוד שהיה אדם שם. ומצינו רוח מזרחית קולטת בכל מקום את הרוצחים, שנאמר (דברים ד מא) אז יבדיל משה וגו' מזרחה שמש. דבר אחר בארץ נוד, כל מקום [שהיה הולך] היתה הארץ מזדעזעה תחתיו והבריות אומרות סורו מעליו, זהו שהרג את אחיו:
@97 **ויהי.** קין בנה עיר ויקרא שם העיר לזכר בנו חנוך:
@98 **ועירד ילד.** יש מקום שהוא אומר בזכר הוליד ויש מקום שהוא אומר ילד, שהלידה משמשת שתי לשונות, לידת האשה ניישטר''א בלע''ז [ללדת], וזריעת תולדות האיש איניינדרי''ר בלע''ז [להוליד] כשהוא אומר הוליד בלשון הפעיל מדבר בלידת האשה, פלוני הוליד את אשתו בן או בת, וכשהוא אומר ילד מדבר בזריעת האיש:
@99 **ויקח לו למך.** לא היה לו לפרש כל זה, אלא ללמדנו מסוף הענין שקים הקדוש ברוך הוא הבטחתו שאמר שבעתים יקם קין, עמד למך לאחר שהוליד בנים ועשה דור שביעי והרג את קין, זהו שאמר (פסוק כג) כי איש הרגתי לפצעי וגו' : **שתי נשים.** כך היה דרכן של דור המבול, אחת לפריה ורביה ואחת לתשמיש, זו שהיא לתשמיש משקה כוס של עקרין כדי שתעקר ומקשטת ככלה ומאכילה מעדנים, וחברתה נזופה ואבלה כאלמנה, וזהו שפרש איוב (איוב כד כא) רעה עקרה לא תלד ואלמנה לא ייטיב, כמו שמפורש באגדת חלק: **עדה.** היא של פריה ורביה, ועל שם שמגונה עליו ומוסרת מאצלו. עדה תרגום של סורה: **צלה.** היא של תשמיש על שם שיושבת תמיד בצלו, דברי אגדה הם בבראשית רבה (כג ב) :
@100 **אבי ישב אהל ומקנה.** הוא היה הראשון לרועי בהמות במדברות, ויושב אהלים חדש כאן וחדש כאן בשביל מרעה צאנו, וכשכלה המרעה במקום הזה הולך ותוקע אהלו במקום אחר. ומדרש אגדה בונה בתים לעבודה זרה, כמה דאת אמר (יחזקאל ח ג) סמל הקנאה המקנה, וכן (פסוק כא) אחיו תופש כנור ועוגב לזמר לעבודה זרה:
@102 **תובל קין.** תבל אמנתו של קין. תובל לשון תבלין, תבל והתקין אמנתו של קין לעשות כלי זין לרוצחים: **לטש כל חרש נחשת וברזל.** מחדד אמנות נחשת וברזל, כמו (איוב טז ט) ילטוש עיניו לי. חרש אינו לשון פעל אלא לשון פועל שהרי נקוד קמץ קטן. וטעמו למטה, כלומר מחדד ומצחצח כל כלי אמנות נחשת וברזל: **נעמה.** היא אשתו של נח:
@103 **שמען קולי.** שהיו פורשות ממנו מתשמיש לפי שהרג את קין ואת תובל קין בנו, שהיה למך סומא ותובל קין מושכו, וראה את קין ונדמה לו כחיה ואמר לאביו למשוך בקשת, והרגו. וכיון שידע שהוא קין זקנו, הכה כף אל כף וספק את בנו ביניהם והרגו, והיו נשיו פורשות ממנו והוא מפיסן: **שמען קולי.** להשמע לי (לתשמיש) , וכי איש אשר הרגתיו לפצעי הוא נהרג, וכי אני פצעתיו מזיד שיהא הפצע קרוי על שמי, וילד אשר הרגתי לחבורתי נהרג, כלומר על ידי חבורתי, בתמיהה, והלא שוגג אני ולא מזיד, לא זהו פצעי ולא זהו חבורתי: פצע, מכת חרב או חץ נברידור''א בלע''ז [פצע]:
@104 **כי שבעתים יוקם קין.** קין שהרג מזיד נתלה לו עד שבעה דורות, אני שהרגתי שוגג לא כל שכן שיתלה לי שביעיות הרבה: **שבעים ושבעה.** לשון רבוי שביעיות אחז לו. כך דרש רבי תנחומא (אות יא) . ומדרש בראשית רבה (כג ד) לא הרג למך כלום ונשיו פורשות ממנו משקימו פריה ורביה, לפי שנגזרה גזרה לכלות זרעו של קין לאחר שבעה דורות, אמרו מה אנו יולדות לבהלה, למחר המבול בא ושוטף את הכל. והוא אומר להן וכי איש הרגתי לפצעי, וכי אני הרגתי את הבל שהיה איש בקומה וילד בשנים, שיהא זרעי כלה באותו עון, ומה קין שהרג נתלה לו שבעה דורות, אני שלא הרגתי לא כל שכן שיתלו לי שביעיות הרבה. וזהו קל וחומר של שטות, אם כן אין הקדוש ברוך הוא גובה את חובו ומקים את דברו:
@105 **וידע אדם** וגו' **.** בא לו למך אצל אדם הראשון וקבל על נשיו, אמר להן וכי עליכם לדקדק על גזרתו של מקום, אתם עשו מצותכם והוא יעשה את שלו. אמרו לו קשוט עצמך תחלה, והלא פרשת מאשתך זה מאה ושלשים שנה משנקנסה מיתה על ידך, מיד וידע אדם עוד וגו' . מהו עוד, ללמדך שנתוספה לו תאוה על תאותו:
@106 **אז הוחל.** (לשון חלין) לקרא את שמות האדם ואת שמות העצבים בשמו של הקדוש ברוך הוא לעשותן עבודה זרה ולקרותן אלהות:
@107 **זה ספר תולדת אדם.** זו היא ספירת תולדות אדם, ומדרשי אגדה יש רבים: **ביום ברא** וגו' **.** מגיד שביום שנברא הוליד:
@109 **שלשים ומאת שנה.** עד כאן פרש מן האשה:
@130 **ויתהלך חנוך.** צדיק היה וקל בדעתו לשוב להרשיע, לפיכך מיהר הקדוש ברוך הוא וסלקו והמיתו קודם זמנו [וזהו ששנה הכתוב במיתתו לכתוב ואיננו בעולם למלאות שנותיו: **כי לקח אתו.** לפני זמנו] כמו (יחזקאל כד טז) הנני לקח ממך את מחמד עיניך:
@134 **ויולד בן.** שממנו נבנה העולם:
@135 **זה ינחמנו.** ינח ממנו את עצבון ידינו, עד שלא בא נח לא היה להם כלי מחרשה והוא הכין להם, והיתה הארץ מוציאה קוצים ודרדרים כשזורעים חטים, מקללתו של אדם הראשון, ובימי נח נחה, וזהו ינחמנו, ינח ממנו. ואם לא תפרשהו כך, אין טעם הלשון נופל על השם, ואתה צריך לקרות שמו מנחם:
@138 **בן חמש מאות שנה.** אמר רבי יודן מה טעם כל הדורות הולידו למאה שנה וזה לחמש מאות, אמר הקדוש ברוך הוא אם רשעים הם יאבדו במים ורע לצדיק זה, ואם צדיקים הם אטריח עליו לעשות תבות הרבה, כבש את מעינו ולא הוליד עד שהיה בן חמש מאות שנה, כדי שלא יהא יפת הגדול שבבניו ראוי לעונשין לפני המבול דכתיב (ישעיה סה כ) כי הנער בן מאה שנה ימות, וראוי לענש לעתיד, וכן לפני מתן תורה: **את שם את חם ואת יפת.** והלא יפת הוא הגדול, אלא בתחלה אתה דורש את שם שהוא צדיק, ונלד כשהוא מהול, ושאברהם יצא ממנו וכו' :
@140 **בני האלהים.** בני השרים והשופטים. (דבר אחר בני האלהים הם השרים ההולכים בשליחותו של מקום, אף הם היו מתערבים בהם) . כל אלהים שבמקרא לשון מרות, וזה יוכיח (שמות ד טז) ואתה תהיה לו לאלהים, (שם ז א) ראה נתתיך אלהים: **כי טבת הנה.** אמר רבי יודן טבת כתיב, כשהיו מטיבין אותה מקשטת לכנס לחפה, היה גדול נכנס ובועלה תחלה: **מכל אשר בחרו.** אף בעולת בעל, אף הזכר והבהמה:
@141 **לא ידון רוחי באדם.** לא יתרעם ויריב רוחי עלי בשביל האדם: **לעלם.** לאורך ימים, הנה רוחי נדון בקרבי אם להשחית ואם לרחם, לא יהיה מדון זה ברוחי לעולם, כלומר לאורך ימים: **בשגם הוא בשר.** כמו בשגם, כלומר בשביל שגם זאת בו שהוא בשר, ואף על פי כן אינו נכנע לפני, ומה אם יהיה אש או דבר קשה, כיוצא בו (שופטים ה ז) עד שקמתי דבורה, כמו שקמתי. וכן (שם ו יז) שאתה מדבר עמי, כמו שאתה, אף בשגם כמו בשגם: **והיו ימיו** וגו' **.** עד מאה ועשרים שנה אאריך להם אפי ואם לא ישובו אביא עליהם מבול. ואם תאמר משנלד יפת עד המבול אינו אלא מאה שנה, אין מקדם ומאחר בתורה, כבר היתה הגזרה גזורה עשרים שנה קודם שהוליד נח תולדות, וכן מצינו בסדר עולם (פרק כח) . יש מדרשי אגדה רבים בלא ידון, אבל זה הוא צחצוח פשוטו:
@142 **הנפלים.** על שם שנפלו והפילו את העולם, ובלשון עברית לשון ענקים הוא: **בימים ההם.** בימי דור אנוש ובני קין: **וגם אחרי כן.** אף על פי שראו באבדן של דור אנוש שעלה אוקיינוס והציף שליש העולם, לא נכנע דור המבול ללמוד מהם: **אשר יבאו.** היו יולדות ענקים כמותם: **הגבורים.** למרוד במקום: **אנשי השם.** אותן שנקבו בשמות עירד, מחויאל, מתושאל, שנקראו על שם אבדן שנמוחו והותשו. דבר אחר אנשי שממון, ששממו את העולם:
@144 **וינחם ה' כי עשה.** נחמה היתה לפניו שבראו בתחתונים, שאלו היה מן העליונים היה ממרידן: **ויתעצב.** האדם: **אל לבו.** של מקום, עלה במחשבתו של מקום להעציבו, זהו תרגום אנקלוס. דבר אחר וינחם, נהפכה מחשבתו של מקום ממדת רחמים למדת הדין, עלה במחשבה לפניו מה לעשות באדם שעשה בארץ, וכן כל לשון נחום שבמקרא לשון נמלך מה לעשות (במדבר כג ט) ובן אדם ויתנחם, (דברים לב לו) ועל עבדיו יתנחם, (שמות לב יד) וינחם ה' על הרעה, (שמואל א' טו יא) נחמתי כי המלכתי, כלם לשון מחשבה אחרת הם: **ויתעצב אל לבו.** נתאבל על אבדן מעשה ידיו, כמו (ש''ב יט ג) נעצב המלך על בנו. וזו כתבתי לתשובת המינים, גוי אחד שאל את רבי יהושע בן קרחה, אמר לו אין אתם מודים שהקדוש ברוך הוא רואה את הנלד, אמר לו הן. אמר לו והא כתיב ויתעצב אל לבו, אמר לו נלד לך בן זכר מימיך, אמר לו הן. אמר לו ומה עשית, אמר לו שמחתי ושמחתי את הכל. אמר לו ולא היית יודע שסופו למות, אמר לו בשעת חדותא חדותא, בשעת אבלא אבלא. אמר לו כך מעשה הקדוש ברוך הוא, אף על פי שגלוי לפניו שסופן לחטוא ולאבדן לא נמנע מלבראן בשביל הצדיקים העתידים לעמוד מהם:
@145 **ויאמר ה' אמחה את האדם.** הוא עפר ואביא עליו מים ואמחה אותו, לכך נאמר לשון מחוי: **מאדם עד בהמה.** אף הם השחיתו דרכם. דבר אחר הכל נברא בשביל אדם, וכיון שהוא כלה מה צורך באלו: **כי נחמתי כי עשיתם.** חשבתי מה לעשות להם על אשר עש י ת י ם:

@1 **א) בעזר** יוצר אורה. אבאר פירוש התורה. ליחד שמו הנורא. אשר עשאני מראשית. ויעצני וקראני ראשית. לעסוק בנועם ראשית. אתחיל לבאר ספר בראשית:
@1 **נפתחו** השמים ואראה מראות אלהים בורא קצות הארץ ואתבונן במה שהורשיתי להתבונן בפתח דברי קדוש, והעירותי ממזרחה של תורה **אומרו בראשית** ששיעור התיבה היא סמוכה כמו שתאמר ראשית דבר וכאן חסר הנסמך לה, ומי כאלהינו יודע דבר הלוא ממנו מוצא דבר:
@1 **ב)** אומרו בתחילת סדר הבריאה **השמים**, ורז''ל פירשו התיבה שהיא מורכבת מב' דברים אש ומים, ומעתה הרי זה ח''ו נותן יד לפושעים לומר כי זו היא התחלת הבריאה אבל המים והאש לא בראם ח''ו הבורא אחר שהשמיענו הכתוב עצמו שתחילת הבריאה היא שמים ואם המים נבראו היה לו להקדים בריאתם, וחז''ל (חגיגה) נשמרו מב' הערות ופירשו ששיעור הכתוב הוא על זה הדרך **בראשית** בריאת שמים וארץ היתה **הארץ תוהו** וגו' לא שתחילת הבריאה היתה שמים וארץ, אבל דבריהם ז''ל לא הספיקו להסיר הטעות, כי לדבריהם למה לא הודיע הכתוב אחר כך בריאת מים ואש ועפר ורוח, והגם שאמר הכתוב (ט') יקוו המים וגו' ותראה היבשה, אינו בנשמע שנבראת ויותר צודק המשמעות שמצויה היתה אלא שגזר עליה להתגלות כשיקוו המים:
@1 **ג)** יש לדקדק בכתוב אומרו **את השמים ואת הארץ** מה בא לרבות בב' אתין אלו:
@1 **אכן** כוונת הכתוב היא על זה הדרך וקודם אעירה שחר המוצג אצלינו מגדולת הבורא מה גדלו מעשיו, כי האדון ב''ה יוכל דבר דיבור בלתי מושג בנבראים כאומרם ז''ל (מכילתא יתרו) בפירוש הכתוב (שמות כ' א') וידבר אלהים את כל הדברים וגו' וזה לשונם דברים שאין הפה יכול לדבר והוא שאמר כל עשרת הדברות בדבור אחד ולא קדם דיבור לחברו:
@1 **ובזה** נבא אל הביאור והוא כי האדון יתעלה שמו כל מה שברא בעולם שהם המקורות וכל אשר ישנו במציאות ושמים וארץ הכל כאשר לכל בראו ה' בדיבור אחד, וזה הוא אומרו **בראשית ברא אלהים את השמים ואת הארץ** דקדק לומר שני אתין לרבות כל הנמצא בעולם ולהיות שהנבראים הם רבים כי מלבד העשרה דברים הניכרים ונראים לעין כל כמו שמנאום חז''ל (חגיגה יב.) וז''ל עשרה דברים נבראו ביום ראשון שמים וארץ אור חשך תהו ובהו וגו' מים רוח ע''כ. מלבד אלו יש עוד בריאות אחרים נעלמים ונבלעים בכוחות היסודות, יש מהם ניכרים באמצעות ההתכה, יש מהם באמצעות ההרכבה, יש מהם בהשתנות הזמנים, יש מהם בכח ההיולי ורבו מלספור, אשר לזה כללם הבורא בב' פרטים גדולים ועצומים בשמים ובארץ, והם הם הב' ריבוים שריבה באומרו **את השמים ואת הארץ** ובמאמר א' ברא הכל יתעלה שמו. ותמצא שאמרו ז''ל (ר''ה לב.) בראשית מאמר הוא כי בו השלימו עשרה מאמרות שבהם נברא העולם, הראשון שבכולן בו נברא הכל אלא שלא היה מסודר והי' כל הבריאות בנמצא אבל חסרו הסדר וסדרן הקב''ה דבר יום ביומו. ביום ראשון הכין והבדיל האור מן החשך וקנה החשך מקומו והאור מקומו, וביום ב' וכו':
@1 **והעד** הנאמן לפירושינו זה מה שאמר הכתוב (ב' ג') **כי בו שבת מכל מלאכתו אשר ברא אלהים לעשות** שאין משמעות לכתוב ובמה שפירשנו יבא כמין חומר **כי בו שבת מכל מלאכתו אשר ברא** ביום הבריאה **לעשות** פי' לתקן בששת ימים כאומרו (תשא לא יז) כי ששת ימים עשה ה' וגו' פירוש תקן, כי הבריאה ביום ראשון במאמר אחד נבראת אלא שהיה הכל חסר תיקון. **למה** הדבר דומה למי שרצה לבנות פלטרין וקודם מכין אבנים ועצים ועפר וצרכי הבנין במושלם ואחר כך יבנה בית, כן הבורא ב''ה ברא כל צורכי העולם בדיבור אחד והכינו והיה הכל מונח גדוש בערבוביא ואחר כך התחיל לסדר דבר דבור על אופניו ועשה פעלו יתעלה שמו:
@1 **ותמצא** שכשרצה לברוא השמים אמר (פסוק ו') **יהי רקיע בתוך המים** פירוש קבע לו מקום אבל הוא כבר נברא במאמר ראשון, וכן הארץ (פסוק ט') ותראה היבשה:
@1 **והאש** שלא הזכיר ה' תיקונו כל עיקר, הוי יודע כי האש לא גילה ה' מקורה כגילוי השמים והארץ והמים להיותה מקור חזק ויש ממנו כליון לעולם אם היה בנמצא כמים וארץ ואין העולם יכול להתקיים, לזה הניחו הקב''ה במקומו שנברא במאמר ראשון מובלע ברעפים עד שהוצרך אדם לו והקיש ברעפים והוציא מהם אש שיעור המספיק לו כאומרם ז''ל (ב''ר י''א) שעל כן אנו מברכים במוצאי שבת בורא מאורי האש. גם בזה גילה ה' אופן הערבוב שהיו מעורבבין המקורות והיסודות בשעת בריאתם קודם שהכינם ה' כל אחד על משמרתו, כי אם לא היה דבר זה במציאות לא היתה דעת אנוש סובלת ידיעה איך יהיו מעורבים יחד מקורות ומה גם עפר ואש:
@1 **והן** אמת שהיה יכול הבורא לכלול במאמר הראשון גם את הסדר, אלא לסיבות הרבה עשה כן ואחד מהם גילו אותה רז''ל באומרם (אבות פ''ה) והלא במאמר אחד יכול להבראות אלא ליפרע וכו'. וליתן שכר טוב לצדיקים וכו' ואל יקשה בעיניך אומרם ז''ל (שם) בעשרה מאמרות נברא העולם לשון בריאה, כי סוף כל סוף כל זמן שהיה חסר התיקון כאילו אין כאן בריאה, המשל אם הארץ לא היתה נגלית אין מקום לנבראים וכמו כן שאר הבריאות שהיו מעורבבים כמו האור והחשך אם כן כל שלא נתקן כאלו לא נברא לזה יתיחם גם כן להם הבריאה:
@1 **ואל** יקשה בעיניך למה כתבה התורה עיקר הבריאה בדרך זה ולא כתבה בפירוש ברא ה' המים והעפר והאש והרוח שבזה לא יהיה איש נבוב ילבב:
@1 **דע** כי התורה תודיע ותשמיע כל נסתר וחפץ ה' להודיע כח מעשיו לעמו והודיענו סדר הבריאה ואופנה וכי הוא האל הגבור הנאזר בגבורה ברא בדיבור אחד כל יש וכל הווה וחפץ ה' להודיע לידידיו כח מעשיו ולא ימנע טוב זה בשביל השוטים הטועים:
@1 **ועוד** יש טעם אחר שיחייב לדבר כסדר האמור והוא שאם היה אומר הכתוב כסדר החפצים בו הסכלים והוא שיאמר כי ברא ארץ וברא מים וכו' היה בנשמע כי בראם כל אחד בפני עצמו ואחר האמת לא כן הוא, והלא ידעת כי לא יחפוץ ה' בדובר שקרים ולא יכון לנגד עיניו ואיך יתחיל ראש דבריו ח''ו בדברים שלא כן הוא, לזה דבר אמת אופן הבריאה כי ישרים דרכי ה' וצדיקים ילכו בם להודות ולגדל לבורא ב''ה ויאמרו לאלהים מה נורא מעשיך:
@1 **ודקדק** לומר **בראשית** ולא אמר בראשונה כח מעשיו הגיד לעמו, והוא כי לפי מה שהקדמנו כי הכל ברא בדיבור אחד דרך שם נשכיל כי מי שידבר כמה דברים בדיבור אחד גם בדיבור לא יצטרך להקדים אות לחברתה, ומעתה כשאמר ה' תיבת שמים לא קדמה שי''ן למ''ם ולא מ''ם ראשונה למ''ם אחרונה וגם אותיות כל דבר ודבר לא קדמה התחלת התיבה לסופה וגם בכל אות ואות אין לה קדם תחלתה לסופה:
@1 **ואחרי** הודיע אלהים אותנו את כל זאת אלה הם הדברים אשר הודיענו ה' בתיבת **בראשית** פירוש הכל הוא ראשית כי לא היתה בבריאה חלק מאוחר אלא הכל הוא ראשית והבן:
@1 **וטעם** האדון אשר בחר לברוא בדרך זה מלבד הטעם שאמרנו שרצה להודיע חלק מגבורותיו יתברך, עוד תמצא כי כשידבר יתברך בגבורות שהיא בחינה המתיחסת לשם אלהים מן השם הוא להיות הדברים נדברים כסדר זה, ותמצא שרמזו ז''ל (מכות כד.) בנועם דבריהם וזה לשונם אנכי ולא יהיה לך מפי הגבורה שמענום ע''כ, נתכוונו לומר במתק לשונם הדברים הנאמרים מבחינה זו שהוא אלהים המתיחסת לגבורה תדבר כדברים האלה הרבה דברים יחד, ולאו דוקא אנכי ולא יהיה אמר בדיבור אחד אלא כל העשרה הדברים כאמור בדבריהם במקום אחר (מכילתא יתרו) אלא המושג אצלינו הוא ב' מהם, ועיין מה שכתבנו בפרשת יתרו (כ' א'), והנה בריאת מעשה בראשית נברא בשם אלהים דכתיב ברא אלהים לסיבות הרבה לזה דיבר כדרכו יתברך דברים עצומים ונוראים כמו שכתבנו:
@1 **ב)** ובדרך דרש יתבאר תיבת **בראשית** על דרך מה שאמר הכתוב (תהלים ל''ג) בדבר ה' שמים נעשו וברוח פיו כל צבאם, ויש לך לדעת כי יתעלה שם אלהינו לא ברא המלאכים עד יום ב' כדי שלא יטעו הטועים כי היו מסייעים אותו במעשה בראשית, ולדבריהם ז''ל (ב''ר א') יש לנו להעיר איך יתכן לומר שהמלאכים נבראים מאוחרים הלא לפי מה שאמר הכתוב וברוח פיו כל צבאם כי צבא השמים נבראו מרוח שיצא מפי עליון כביכול אם כן בהכרח לפי המורגש המלאכים יבראו קודם שמים וארץ כי הרוח יקדים לצאת קודם שיצא הדיבור וכיון שהשמים והארץ נבראו מהדיבור הרי כבר קדם הרוח שממנו יצאו המלאכים, לזה אמר הכתוב **בראשית ברא** וגו' פירוש כי ה' הקדים המאוחר שהוא הדיבור לרוח היפך הידוע אצלנו בטבע הדיבור וברא שמים תחלה והפך הסדר ועשה ראשית דיבור לרוח, לטעם האמור בדבריהם ז''ל (שם) והוא שלא יאמרו שהיו המלאכים עוזרים ומותחים עמו שמים וכו', ומודיענו הכתוב כי האדון ב''ה לא יוקח אליו שיעור מהנבראים שהנבראים אינם יכולין להפך הסדר המוטבע בהם בעת הבריאה מה שאין כן הבורא ב''ה יכול הוא לדבר בדרך אשר יחפוץ, ולזה תמצא שדייק הכתוב באומרו בדבר ה' שמים נעשו שהקדים בריאת שמים שנבראו מהדיבור ואחר כך אמר וברוח פיו כל צבאם:
@1 **ומעתה** שיעור פירוש תיבת **בראשית** הוא על זה הדרך כי להיות שיש בדיבור ב' דברים הרוח והדיבור עצמו וכל אחד ברא ממנו ה' בריאה חדשה ואין אני יודע מי קדם משניהם אם הרוח אם הדיבור לזה אמר כי ראשית היה מעשה שמים וארץ, וממוצא דבר אתה יודע כי הדיבור היה ראשית לרוח שיצא מפי עליון:
@1 **ג)** עוד יש לנו להבין שינוי שבין ב' הכתובים, בפסוק זה לא אמר אלא שם **אלהים** וכתוב אחד הוא אומר (ב' ד') ביום עשות **ה' אלהים** ארץ ושמים שהזכיר ב' שמות. ועוד כי כאן הקדים שמים לארץ ושם הקדים ארץ לשמים:
@1 **ונראה** כי ב' קושיות אלו כל אחת מתרצת חברתה, והוא על דרך מה שפירשו ז''ל (סוטה לא) בב' מקראות הכתובים בתשלום שכר הצדיקים כתוב אחד אומר (שמות כ') ועושה חסד לאלפים וכתוב אחד אומר (דבדים ז') לאוהביו ולשומרי מצותיו לאלף דור. ואמרו ז''ל כי מה שאמר הכתוב לאלפים לאוהביו בלבד ואינו חוזר גם לשומרי מצותיו שהם העושים מיראה כי אותם בפסוק אחר הוזכר שהם אלף דור, גם פסוק שאמר לאוהביו ולשומרי מצותיו לאלף דור אינו חוזר אומרו לאלף דור אלא לשומרי מצותיו הנסמכת לה ולא לתיבת אוהביו הקודמת כי אותם הנה שכרם אתם בפסוק אחר שהוא לאלפים:
@1 **גם** אנחנו נפרש ב' מקראות הללו על זה הדרך **בראשית ברא אלהים את השמים** שם זה של אלקים פירוש מדה זו של הדין בלא שתוף שם הרחמים זה הוא דוקא למה שנוגע להשמים ואינו חוזר לאומרו ואת הארץ כי הארץ בראה בשיתוף שם הרחמים ועל כתוב אחר סומך, והוא אומרו ביום עשות ה' אלהים ארץ כי אין עולם בני אדם יכול להתקיים בדין גמור בלא שתוף רחמים לצד שהם מחומר כידוע, ואומרו ושמים אינה נמשכת עם הארץ בבחינה זו של השיתוף, ואופן מעשיה הלא הם כתובים בפרשת בראשית, ובזה נתיישבו ב' הדקדוקים כמין חומד, וענין ידיעת מי קדם, הנה כתבנו למעלה שכל הבריאה יחד נבראת בגבורתו יתברך, ולא יקשה לך מה משפט יערוך ה' לבני אלים יושבי שמים שיוצדק לומר עליהם שם אלהים הלא תמצא שאמרו ז''ל (חגיגה טו.) במעשה מט''ט שדנוהו לפני אלישע ומחיוהו שתין פולסי דנורא, וגם אליהו וכו' (ב''מ פה:) וכמה משפטים לשרי מעלה, והגם שאין להם יצר, עם כל זה ימצא בהם הטעות, כי לפעמים לא יכוונו אל האמת וישגו, וצא ולמד ממעשה המלאך מט''ט ואליהו כי שגגו וכן יקר מקרה ויענישם ה' אפילו על השוגג מה שאין שופט במשפט זה ליושבי ארץ, ובזה יתאמת מה שפירשנו ונכון:
@1 **והגם** כי מצינו לרז''ל (ב''ר א') שהרגישו בב' הדקדוקים שבכתובים ותרצו כי טעם שבפסוק א' הקדים שמים ובאחד הקדים ארץ כי נתכוין לומר ששניהם יצאו כאחד, וטעם שבמקום אחד אמר אלהים ובמקום אחד שיתף שם הרחמים אמרו (ב''ר י''ב) כי מתחלה עלה על דעתו לברוא בשם אלהים וראה שאין העולם יכול להתקיים שיתף וכו':
@1 **דע** כי רשות לנו נתונה לפרש משמעות הכתובים בנתיבות העיון ויישוב הדעת הגם שקדמונו ראשונים ויישבו באופן אחר כי ע' פנים לתורה ואין אנו מוזהרים שלא לנטות מדברי הראשונים אלא בפירושים שישתנה הדין לפיהן, ולזה תמצא שהאמוראים אין כח בהם לחלוק על התנאים במשפטי ה' אבל ביישוב הכתובים ובמשמעותן מצינו להם בכמה מקומות שיפרשו באופן אחר:
@1 **שוב** הצצתי בשכליות העיון הכתובים כי יסבלו דברינו גם דברי קדמונינו ע''ה, וקודם נשכיל לדעת איך יוצדק בהאדון ברוך הוא ראש וסוף במחשבתו שבתחילה חשב בדין, וחזר לשתף, כי האדון ברוך הוא לא יבצר ממנו מזימה במעט זמן ובפחות מהרף עין ידע הכל ויכוון אל האמת בהשקפה ראשונה כביכול ברוך הוא וברוך שמו:
@1 **אכן** דע כי כוונת שיתוף הרחמים תסבול ב' ענינים, הא' כי ה' ירחם לפעמים למי שיחפוץ לרחם מבלי הביאו במשפט כי זו היא מדת הרחמים למחול ולסלוח, ושם אלקים גם כן למי שלא ירצה למחול יביאהו במשפט וכפי זה יש לך אדם שלא יבא במשפט. ודרך ב' הוא כי לעולם אין ה' מוותר לשום אדם בעולם וכל העולם יעמדו למשפט אין נמלט, ויש לך לדעת אומרם ז''ל (ב''ק נ.) וזה לשונם כל האומר הקב''ה וותרן יוותרו בני מעיו אלא במשפט יעמיד ארץ ואין אדם נמלט מהדין, וכפי זה הנה בררנו לנו דרך הב', ומעתה אופן הבריאה לפי דבריהם ז''ל הוא על זה הדרך בתחילה ברא במדת אלהים שהוא יחוס המשפט וכך הוא התכלית שעמד הכל בדין אלא שראה שאותו הדין לא יוכל העולם עמוד בו שיתף עמו מדת הרחמים פירוש לא שחזר בו ממחשבה ראשונה ח''ו אלא שיעשה המשפט בדרך רחמים כמו שתאמר שלא ליפרע מהאדם עונשו כאחת, גם שלא ליפרע ממנו תיכף ומיד בלא הארכת זמן, ולעולם אין לאדם אלא מה שיגיע אליו במשפט, והוא אומרם ז''ל (ירושלמי שקלים פ''ה) מאריך אפיה וגבי דיליה:
@1 **נמצאת** אומר שלא חזר בו ממחשבתו כי לא מצינו שקדם במחשבת ה' שלא להתנהג במשפט בסדר זה שיהיה נפרע ברחמים. ולפי זה בהכרח שיאמר הכתוב כסדר האמור שאם היה אומר בראשית ברא ה' אלהים היתה הסברא נותנת כי יש משפט ואין משפט גם כן לצד הרחמים כי לא החליט ה' משפט לבדו ומאומרו ברא אלקים לבד הרי החליט כי אין דבר בלא משפט, והגם שאמר הכתוב אחר כך ה' אלהים תתפרש על אמיתתה כמו שפירשנוה שהמשפט על כל פנים יהיה אלא שיהיה הפרעון בדרך רחמנות. וסמך עלי' הכתוב שנכריח לפרש על זה האופן להיות דבר ידוע מוחזק בידינו כי ידיעת ה' לא תתהפך כביכול:
@1 **ואחר** שפי' כוונת רז''ל גם אחר דבריהם יש מושב לדברינו, כי מדה זו של השיתוף שהכין ה' ליושבי תבל להאריך אפו ולגבות מעט מעט בניכוי לא יתנהג ה' כן אלא עמנו ולא עם העליונים יושבי שמים אלא תכף ומיד ישלם למתחייב חיובו כאחת, גם לא יועיל להם החרטה והוידוי והתשובה ולא טענת השגגה, וצא ולמד ממעשה הובא בש''ס (חגיגה טו.) בד' שנכנסו לפרדם שהענישו המלאך היושב ברשות המלך יתעלה שמו ב''ה על אשר לא עמד מפני אלישע כדי שלא יטעה במחשבתו וזאת למלאך שגגה גם לא הוזהר עליה וכן לא ישפוט השופט לעמו ישראל כידוע ממשפטי תורתו שתתעלה:
@1 **ד)** עוד רמז בהקדמת שמים לארץ להראות כי לא כמדת הקב''ה מדת בשר ודם, מדת בשר ודם בונה הבית ואחר כך העליה על גביו, אבל הקב''ה הקדים העליה ואחר כך הבית להראות כי השמים תלויים ועומדים הם במאמרו יתברך:
@1 **ה)** ודרך רמז רז''ל דרשו (ב''ר א') תיבת בראשית שיכוין ב''ה לומר בשביל תורה שנקראת ראשית ופירוש בי''ת של בראשית היא בי''ת הסיבה, ומעתה מי שזכה בתורה זכה בכל העולם ומי שלא זכה בתורה אין לו ליהנות מן העולם עד מדרך כף רגל זולת אם ישמש הכשר עמליה. וגם אמרו (ויק''ר ל''ו) בשביל ישראל שנקראו ראשית דכתיב ראשית תבואתה, ואין מאמרם זה מכחיש הראשון כי טעם עצמו שנקראו ישראל ראשית הוא לצד קבלתם התורה ובזה נבדלו לשם ולתהלה מהעמים, וגם אמרו (ב''ר י''ב) בשביל אברהם ובשביל יעקב (ויק''ד ל''ו) והכל הולך לטעם הראשון עקב אשר שמע אברהם וגו'. גם אמרו (שבת לו:) בשביל יראה שנקראת ראשית דכתיב (תהלים קיא) ראשית חכמה יראת ה', כי הוא זה גם כן יסוד התורה כי אם אין חכמה אין יראה ואם אין יראת ה' אין תורה כי הוא אוצר נחמד לתורה:
@1 **ו)** עוד תתפרש **בראשית** על דרך אומרו (משלי ח') ואהיה אצלו אמון ודרשו ז''ל (ב''ר א') אל תקרי אמון אלא אומן, והוא עצמו שרמז הכתוב תחילת דבר ה' והודיע בריאת עולם הודיע במה בראה ואמר בתורה בראה כי היא האומן. (אין זה סותר לפירוש ראשון כי התורה הכינה עולם להתהלך במישרים), ולפי זה גדלה מעלת בעליה שזוכים בכל ולזה יהיה הדין להם שיקראו בונים, והוא אומרם ז''ל (שבת קיד.) תלמידי חכמים נקראים בונים כי מה שבפיהם ובלבבם הוא הבונה, והוא אומרו (ירמי' לג) אם לא בריתי וגו' חוקות שמים וארץ לא שמתי:
@1 **ז)** עוד תתפרש בי''ת של בראשית על דרך אוז''ל (הקדמת תקו''ז ה:) כי ב' אופני יראת ה' הם, האחת היא יראת העונש, והב' היא יראת הרוממות, וזו יראה פנימית ומעולה מהא', והוא שרמז באות בי''ת ראשית כי ב' יראות הכין ה' לקיום העולם, ורמז אופן שניהם, הא' רמזה בתיבת **אלהים** כי היא יראת הדין בקומו למשפט, והב' רמזה באומרו **את השמים ואת הארץ**, והוא על דרך אומרו (תהלים ח') כי אראה שמיך וגו', ואמרו ז''ל (זהר ח''א א:) כי יראת הרוממות תכנס בלב משכיל בהביטו בהתבוננות במעשה שמים וארץ מה גדלו מעשי ה' תתלהב הנפש וירא מגדולתו יתברך שמו:
@1 **או** ירמוז ב' אופני היראה אחת באומרו **השמים** כאן רמז יראת הרוממות על דרך אומרו כי אראה שמיך וגו', ויראה ב' **ואת הארץ** שהיא יראת העונש ויחסה לארץ לשלול כי אינה לצד הרוממות אלא לצד אימתו מילדי העולם על דרך אומרו (איוב כ') וארץ מתקוממה לו:
@1 **ח)** עוד ירמוז **בראשית** על דרך אומרו (ישעי' ל''ג) יראת ה' היא אוצרו, הכונה היא כי מי שיש בו יראת ה' היא אוצר לתקות הלבבות שהוא דביקות אורו יתברך בנפש אדם כאומרו (דברים ד) ואתם הדבקים וגו', וכל מי שיש בו יראת שמים הוא משכן השכינה כאומרו (תהלים ע''ח) אהל שכן באדם. והוא שרמז בתיבת בראשית על זה הדרך בי''ת פירוש בית מושב אלהים היא היראה הרמוזה בתיבת ראשית, ברא ה' והכין פעלו:
@1 **ט)** עוד תתפרש **בראשית** על דרך אומרם ז''ל (ויק''ר ל''ה) הספר והסייף ירדו כרוכים וכו', והוא אומרו **בראשית ברא אלהים** פירוש עם ראשית שהיא התורה ברא אלהים פירוש הדין שהוא רמז הסייף:
@1 **י)** עוד תתפרש על דרך מה שאמר הכתוב (מלכים א' י''ח) ה' הוא האלהים, והכוונה היא שהגם ששם אלהים יתייחס אל הדין אף על פי כן רחמים הוא, וכל שמותיו של הקב''ה. לטובה יכוונו יחד להטיב ולהתחסד אלא דלצד מעשה האחרונים יצא הדין ליסר למי שראוי ליסר וזולת זה גם שם אלקים מדתו להטיב, והוא אומרו **בראשית ברא אלהים** כי שם אלהים הטיב וברא עולם לחון ולרחם ולהטיב לשוכני שמים וארץ ואין לך רחמים גדולים מזה, והוא שאמר הכתוב (בראשית כז כח) ויתן לך האלהים הרי שגם שם אלהים יטיב לטובים בתורת מתנת חנם אלא שעושי רשעה יסובבו לעשות להם אלהים מוסר, ולעתיד לבא המקווה כן יהיה ה' אחד ושמו אחד:
@1 **יא)** עוד יתפרש תיבת **בראשית** על דרך אומרם ז''ל (הקדמת זוהר ב') כי בשעת בריאת העולם נכנסו האותיות לפני הבורא נכנסה ת' ואמרה לפניו רבונו של עולם רצונך לברוא בי העולם וכו' וכולם השיבם ה' כי אינו חפץ לטעם האמור בדבריהם לכל אחת ואחת עד שנכנסה בי''ת וקבלה וברא בה העולם דכתיב בראשית, אל''ף שתקה אמר לה הקב''ה אל''ף למה את שותקת וכו' אמר לה את תהי' ראש לכל האותיות וכו' ע''כ, הנה מדברי ה' יראה כי אל''ף יש לה מעלה מאות בי''ת ומעתה אם היו האותיות עולות לפניו ביושר היתה האל''ף זוכה לבראות בה העולם, ולהיות כי יאמר האומר ולמה לא עלתה האל''ף ראשונה והניחה עד לבסוף, דע כי אמרו ז''ל (הקדמת תיקוני זהר) כי האותיות כשהם בדרך ישר על זה הדרך אל''ף בי''ת גימ''ל וכו' הם רומזים למדת רחמים, וכשהם למפרע על זה הדרך תי''ו שי''ן רי''ש וכו' הם מורים על מדת הדין, וזה לך האות חדש תשרי שהאותיות למפרע תי''ו שי''ן רי''ש הוא זמן הדין הגדול אלא שהשם לצד רחמיו שיתף אות אחת משם הרחמים והיא יו''ד לרחם הדין, (הקדמת ת''ז ט''ז) ואחרי הודיע אותנו את זה נפרש הכתוב על זה הדרך בי''ת ראשית תדע טעם לקדימת בי''ת לאל''ף, להיות שהבריאה היתה במדת אלהים וכיון שכן עלו האותיות למפרע כמשפט ובזה קדמה בי''ת לאל''ף וקנתה מקומה:
@1 **יב)** עוד ירצה באומרו **בראשית** על דרך אומרם ז''ל (הקדמת זהר) כי אלף עולמות נעלמים ברא ה' וקורין אותם ז''ל (ז''ח בראשית ב') עלמין דכיסופין, והם הרמוזים בפסוק (שה''ש ח') האלף לך שלמה, ומעתה התחיל הכתוב בבי''ת כי האל''ף כבר קנתה מקומה שבה ברא אלף עולמות כשמה של אל''ף, והתחיל בבי''ת לבראות העולם הזה להיות שישנו גם כן בחשבון הבריאה שהם ב' שמים וארץ, ולזה גם כן לא אמר בראשונה שתבין שזה הוא תחילה ולא כן הוא שכבר ברא עולמות החמדה אלא בפרט זה של שמים וארץ הוא שאומר ראשיתו:
@1 **יג)** עוד ירמוז בתיבת **בראשית** על דרך אומרם ז''ל (מדרש שמואל אבות פ''ו) כי ה' ברא ד' עולמות ויחסו להם שמות אצילות בריאה יצירה עשיה, ורמזום בפסוק (ישעי' מ''ג) כל הנקרא בשמי ולכבודי בראתיו יצרתיו אף עשיתיו, והוא שרמז כאן באומרו **בראשית** הוא עולם הכבוד שהוא האצילות והוא יקרא ראשית לכל, ברא הוא עולם הבריאה, אלהים רמז לעולם היצירה כי יש שם דינים, את השמים ואת הארץ הוא עולם העשיה כי הוא זה שמים וארץ כאמור בדבריהם הנעימים:
@1 **יד)** עוד ירמוז על דרך אומרם ז''ל (פסחים נ''ר) כי גן עדן וגהינם נבראו קודם שנברא העולם שהם שכר ועונש על התורה והמצות, והוא שרמז באומרו **ב' ראשית** כי ב' דברים ברא ה' מיוחדים בשביל היראה שהם שכר ועונש גיהנם וגן עדן (חגיגה ט''ו) זכה וירא מה' נוטל חלקו וחלק חברו בגן עדן לא זכה נוטל חלקו וחלק חברו בגהינם ואולי כי רמז כי שניהם נוצרו יחד ולשניהם יקרא ראשית כי אם קדמה אחת לחברתה לא יתיחם ראשית אלא לאחד הא למדת כי בדיבור אחד נבראו יחד:
@1 **טו)** עוד ירמוז כי להיות שיש ב' עולמות עולם הזה ועולם הבא והאדם על ידי התעסקו בתורה ובמעשים טובים ישיג הטוב והחיים, כאן הודיענו הכתוב כי לא ישלם לצדיקים שכר התורה והמצות בעולם הזה עד אשר יכין להם אוצר הטוב שהיא העיקר לחלק הנשמה ואחר כך אם יותיר מטיבין לו גם בעולם הזה, כי יבחר ה' תחילה להכין לאדם גמול עולם העליון שהוא הנצחי, והוא שרמז באומרו **בראשית ברא אלהים את השמים** שהם עולם הנשמות ואחר כך **ואת הארץ** שהוא עולם השפל אם העדיף בטובו, הא למדת שאין מטיבין לצדיקים בעולם הזה עד אחר שיזכו בנחלתם לאור באור החיים:
@1 **טז)** עוד ירמוז על פי מה שנחלקו רז''ל (ר''ה י:) אחד אמר בתשרי נברא העולם ואחד אמר בניסן נברא העולם, ונראה לי כי אלו ואלו דברי אלהים חיים, כי יש לך לדעת שאמרו ז''ל (ב''ר פ''א) שבתחילה חשב ה' לבראות העולם ואחר כך הוציא ה' מחשבתו לפועל. וכפי זה נוכל לומר כי בניסן חשב ובתשרי יצא לפועל או להפך, ולשניהם יתיחם לשון בריאה בין מה שעלה במחשבתו יתברך בריאה תקרא בין כשיצתה לפועל, ובזה יתקיימו דברי רבותינו יחד, והוא שרמז בבי''ת של תיבת **בראשית** כי ב' ראשית היו אחת למחשבה ואחת למעשה אלא שאין אנו יודעים אם בניסן חשב ובתשרי פעל או להפך:
@1 **יז)** עוד ירצה על דרך אומרם ז''ל (ברכות ו:) כל מי שיש בו יראת שמים דבריו נשמעין, והטעם כי הירא דבר ה' ידבר מתוך קימת נפשו וכיון שכן תכיר נפש השומעת ותקבל תוכחת מוסר, ואם הדברים יצאו מהגוף אין שייכות לנפש לשמוע, כמו שרמזו ז''ל במה שאמר הכתוב (דברים ו') והיו הדברים וגו' על לבבך אז ושננתם לבניך הם התלמידים, והוא אומרו **בראשית** שהיא היראה כאומרם ז''ל **ברא ה' את השמים** פירוש שיהיה ירא שמים אז ישמע קולו וילמד אדם דעת, והוא אומרו **ואת הארץ**:
@1 **יח)** עוד ירצה להיות שציוה ה' הרבה יראות בעולם, יראה מאביו ואמו דכתיב (ויקרא יט) איש אמו ואביו תיראו, גם מהמלך ומהחכמים גם לירא מהבריות לבל יחשדוהו, ויאמר האומר שתהיה שוה מצות היראה בכל מקומות שישנה ויצא מזה שלפעמים יזלזל ח''ו במצות ה' לכבוד המלך או לכבוד אביו וכדומה, לזה רמז כאן בתחילת דברי ה' כי קודם כל דבר יקדים לירא את השמים ואחר כך ואת הארץ שהם פרטים המחוייב לחוש להם, והוא שאמר הכתוב (במדבר ל''ב) והייתם נקיים מה' תחלה ואחר כך ומישראל, ומעתה אין מקום לקיים שום מצות מורא של הזולת אלא אם לא יעבור על שום מצוה ממצות ה':
@1 **יט)** עוד ירמוז כי באמצעות התורה ברא ה' ב' הדרגות באדם, או ישוה במדרגה לשמים, והוא על דרך אומרו (תהלים פ''ב) אני אמרתי אלהים אתם, או אם לא יקיימה תרד מדרגתו למטה לארץ, והוא אומר **בראשית** פירוש באמצעות ראשית ברא ה' ב' הכנות אלו את וכו':
@1 **כ)** עוד תרמוז הפרשה כולה על בריאת האדם כי הוא עיקר תכלית הבריאה, על זה הדרך **בראשית** כשברא ה' את האדם בראו ממקור הרוחניות הרמוז בתיבת השמים וממקור הגשמיות הרמוז בתיבת הארץ, ותמצא שרמזו רז''ל (סנהדרין צ''א:) במה שאמר הכתוב יקרא אל השמים מעל שהוא הרוח ואל הארץ הוא הגוף הבנוי מהארץ, ורצונו יתברך בזה הוא שעל ידי מעשה האדם יתעצם להפוך החומר שהוא הגוף עד שיהיה נחשב צורה, והנה תמצא (שבת קנב:) שהצדיקים אינם חוזרים עפר, להיות כי זככו החומר שלהם עד שנעשה רוחני, כמו שכתב הר''י עראמה ז''ל וזה לשונו והתעצמות השלמים להפך החומר לצורה עכ''ל, ולזה אמרו ז''ל (ברכות יח.) שהצדיקים במיתתן נקראים חיים כי חלק הגשם נעשה רוחני המתייחם אל החיים, והרשעים בחייהם קרויים מתים לצד שגם הרוחניות שבהם נתגשם ונעשה ארץ המתיחס אל הדומם שהוא מת:
@1 **וב'** מדות אלו רמזם באומרו **את השמים ואת הארץ** על זה הדרך אם זכו הרי הם מסמיכים חלק הגשם שבהם הרמוז אל הארץ מחברים אותו ונעשה חומוניא אחת עם השמים, ואם לא זכו הרי הם מהפכים חלק הרוחניות שבהם לבחינת הארץ ונעשה הצורה חומר, והוא אומרו **ואת הארץ**. ואומרו **והארץ היתה תהו ובהו** כאן רמז מה שהיה בעונות שנתגבר צד החומר שהיא הארץ ונתרוקן מהרוחניות כמו שתרגם צדיא ורקניא, וחשך שהוא יצר הרע הנקרא בדברי קדשם (זהר ח''א ס''ג.) דמחשיך אנפי דברייתא, **על פני תהום** וקרא להגוף תהום להיותו כתהום בולע תמיד, ומצד היצר שהוא החשך **ורוח אלהים** הנתנת בו **מרחפת על פני המים** כי לא מצאה הרוח מנוח לכף רגלה כי היצר גירשה והורמה ממקום הנחתה וישכון שם החשך שהוא יצר הרע ונשארת הנפש מרחפת על פני המים הם מים הזדונים שהם כוחות של הטומאה:
@1 **ובראותו** הקב''ה כן **ויאמר אלהים יהי אור** שולח אל האדם עזר נגד יצרו וזה יהיה בהגיעו לי''ד שנה יופיע עליו ממעון קדשו רוח אלהין קדישין נשמה קדושה וטהורה, או ירמוז אל התורה כי היא האור הנערב ולה יקרא אור דכתיב (משלי ו') ותורה אור, והמכוון אחד, כי בחינת הנשמות הקדושות הם בחינת אור התורה ובעל נפש הוא בעל תורה, והוא אומרו **ויאמר אלהים יהי אור** שהיא הנשמה שאורה רב להיותה חצובה מתחת כסא כבודו יתברך חלק אלוה ממעל שולחה ה' להאיר אל האדם לבל יטבע בטיט היצה''ר, או גם כן למה שאמרנו שהיא התורה המאירה לנפש אדם ואז **ויהי אור**, **וירא ה' את האור** אשר נתן באדם **כי טוב** שבאמצעותו ילך האדם בדרך הטוב והישר:
@1 **ולא** תחשוב כי בהיות הנשמה באדם או על ידי עסק התורה בזה הוא שקט מתחבולות היצר המחטיאו ופנה והלך לו, שאם כן אין כאן לא שכר ולא עונש לזה אמר כי עדיין החשך בעולם, אלא שעל ידי זה מסתייע האדם להעריך מלחמה עמו ולהבדילו מעליו לבל הפילו במועצותיו ויכיר בחינת עשות רע כי רע הוא, וזה הוא אומרו **ויבדל אלהים בין האור** שהיא הנשמה ובין החשך שהוא היצר הרע, וזה שאמר הכתוב (קהלת י') לב חכם לימינו שהוא מקום האור מקום הנשמה, ולב כסיל לשמאלו שהוא מקום היצר הרע, וקרא לאור יום ולחשך קרא לילה, ולזה התפלל דוד (בתהלים צ''א) שיצילהו מפחד בלילות:
@1 **ואומרו ויהי וגו' יום אחד** כי אי אפשר שיוכר אורה של הנשמה אלא מחשכו של היצר הרע שאם לא כן לא ישתנו ממלאכי השרת ואין כאן לא שכר ולא עונש, ולזה אמר יום אחד:
@1 **ויכוין** עוד לומר **יום אחד** על דרך אומרם ז''ל (ע''ז ל''ה:) בפסוק (שה''ש א') על כן עלמות אהבוך על מות פירוש אפילו מלאך רע עונה בעל כרחו אמן. ולזה אמר **ויהי ערב ויהי בוקר יום אחד** פירוש מדת ערב ומדת בקר כלם בהסכמה אחת לטובת הצדיק:
@1 **או** ירמוז שעל ידי סיוע הנשמה יהיה הערב עת שיעריב שמשו ללכת לעולם העליון כעת בקר עת בואו לעולם שתחזור הנשמה מאירה כיום בואה, והוא על דרך אומרם ז''ל (שבת קנ''ב:) והרוח תשוב אל האלהים אשר נתנה, וזה לשונם תנה לו כמו שנתנה לך, ובזה ישוה יום בואו כיום לכתו כאחד:
@1 **כא)** עוד יכוין הכתוב להודיע כי בתחילת הבריאה הכין ה' ועשה פעולתו שוה שמים וארץ שהגם שהשמים הם העליונים אף על פי כן גם הארץ היתה בגדר הטהרה, וצא ולמד מעלתה וזכותה כי ממנה נברא אדם עפר מן האדמה ותוארו כמלאך ה', ותמצא כי ה' בחר לשכון בארץ עם הנבראים והכין בית למנוחתו כביכול, ודבר פשוט הוא כי מושב אלהים שלם הוא וקדוש יאמר לו, ותמצא כי קודם שחטא אדם היה ה' מצוי בתחתונים כבעליונים, והוא אומרו **בראשית ברא אלהים את השמים ואת הארץ** בגדר אחד בנקיות וטהרה, והוא מאמר הנביא (ישעי' סו) כה אמר ה' השמים כסאי והארץ הדום רגלי, ואמרו ז''ל (חגיגה יד.) שהוא שרפרף, הא למדת שהיא בגדר ראוית מושב אלהים, אלא שעל ידי מעשה התחתונים **והארץ היתהתוהו ובוהו** ונתגשמה והוחשך אורה לצד מעשה הרשעים, **ויאמר אלהים יהי אור** שהיא התורה אז חזרה הארץ לקדמותה להאיר אורה ושכן ה' בארץ עם עמו ונחלתו, והוא אומרו **ויהי אור**:
@1 **כב)** עוד יתבאר הכתוב על זה הדרך כי דבר ידוע כי מצינו להקב''ה שבחר לשכון בערפל, וחבב לשכון בתוכנו. ועוד לו שמצינו (תענית ה.) כביכול שנשבע שלא יכנס לירושלים של מעלה עד שיכנס לירושלים של מטה הרי זה מגיד שחביבה לו של מטה יותר משל מעלה, גם כשנשכיל בטעם בריאת כל העולם נדע כי העיקר הם התחתונים שהם עמו ונחלתו:
@1 **ולפי** זה יכוין הכתוב לומר סדר הבריאה לא זו אף זו. בדרך חיבה, **בראשית ברא אלהים את השמים**, ועוד ברא בריאה יותר חביבה אצלו ומעולה יותר והיא **את הארץ** שהשמים אדרבה תלויים בה וכל זה באמצעות בני ישראל עם קדושו כי בהם תלוי קיום העולמות גם העליונים כידוע לבקיאים בחדרי החכמה האמיתית:
@1 **ולדרך** זה יתבאר אומרו **והארץ היתה תהו** כאן רמז בעונות לגליות ישראל שהיא סיבת מניעת דירתו יתברך בארץ. גלות האחד הוא גלות מצרים אשר נשארו בו ת' ושלשים כמנין תה''ו ת' ואחד עשר ובהו חשבונו י''ט הרי ת''ל, ומשמעות **ובהו** גם כן ירמוז לגלות שלאחריו שהוא גלות בבל נקרא גלות בבל בהו כי תרגום בהו ריקניא וכתיב בירמיה סימן נ''א על גלות בבל אכלני הממני נבוכדנאצר מלך בבל הציגני כלי ריק, ואומרו **וחשך על פני תהום** ירמוז על הגלות המר אשר אנו בו שקועים בתהום אשר אין לו סוף זה לנו אלף ותרע''א שנה, ולא די אורך הגלות אלא חשך שירמוז לב' דברים, הא' לשיעבוד העמים וכובד עול המסים עד כי חשך משחור תארם זה רודה וזה מרדה אשרי מי שלא ראה ובפרט במערב שלנו, והב' הוא על היצר הרע אשר החשיך העולם, ובעונותינו רבו פריצי עמו ישראל והותר להם נבלות הפה ושבועת שוא ולשון הרע וגזל ומונעם מלעשות תשובה לשוב שבותם, ולא יאמר אדם בראותו כל כך ירידת ישראל כל אורך הזמן כי חם ושלום אבדה תקוה מבנים, לא כן הוא אלא **ויאמר אלקים יהי אור** הוא אור הגאולה העתידה המופלא, ואומרו **ויהי אור** על דרך אומרם בתיקוני הזוהר (תיקון כ''א) ויהי רז שאור בגימטריא רז, הכוונה שגזר ה' יתעלה שמו שאור זה של מלך המשיח לא יתגלה בעולם ויהיה סוד טמון אצלו כאומרם (שם) ללבי גליתי מלבא לפומא לא גלי, ואומרו **וירא אלהים את האור כי טוב** חוזר על האור מצד עצמו כי טוב הוא אשרי עין ראתה, וחוזר גם על מה שרמז שיעשהו בסוד נסתר כי טוב שכן צריך להיות כאומרם ז''ל (יומא ט) מכמה טעמים, ואומרו **רוח אלהים** וגו' אמרו במדרש (ב''ר פ''ב) זה רוחו של משיח, מרחפת על פני המים אין מים אלא תורה על דרך אומרם בזוהר (בהשמטות לחלק א' י''ג) שלא יגאלו ישראל אלא בזכות התורה שנמשלה למים:
@1 **והנה** ידוע הוא כי בעונותינו הרבים הרבה נצוצות של קדושה הוטבעו בתוך הקליפות וגם הרבה ערב רב נשתקעו בתוך הקדושה כאומרם בספר תיקוני הזוהר הקדוש (תיקון ס''ו) ומעורבים רע בטוב וטוב ברע לזה צריך כביכול להבדיל הטוב מהרע והאור מהחשך אשר נתערבו, והנה ידוע כי הקליפה חיותה היא יניקתה מהקדושה דוקא וזולת זה אין לה חיות, ולכן אז בהבדילו ה' את האור שהיא הקדושה ונשאר הרע מובדל ואין לו מקום חיות לינק ממנו ממילא יבטל, וזה הוא אומרו (זכרי' י''ג) ואת רוח הטומאה אעביר מן הארץ כי ידמה לקציצת האילן ממקום יניקתו ושורשו אשר יונק ממנו שיבש ולא יצלח עוד ולא ישאר כי אם האור הטוב, וזה הוא שאמר **ויקרא אלהים לאור יום** פירוש ויקרא לשון יקר וגדולה, כי אין מעלת הקדושה נכרת אלא בהפיל הקליפה הנקראת חשך, והודיע הכתוב כי ביום ההוא הידוע לפניו במרום יקרא ה' לאור ביקר וגדולה, וזה יהיה ביום יודע לה' שיהיה בו ה' אחד, ואומרו **ולחשך קרא לילה** לשון מקרה הוא בלתי טהור, ולזה לא סמך הכתוב על תיבת ויקרא שאמר בתחילה כי אין יקר וכבוד עוד לחשך אלא מקרהו יהיה דוקא בלילה והוא סוד אומרו (תצא כ''ג) מקרה לילה, אבל כשיעבור הלילה שהוא זמן הגלות כמו שאמר הכתוב (ישעי' כ''א) משא דומה וגו' שומר מה מלילה כי הגלות דומה ללילה, ואז בעלות השחר אין עוד חושך ולא לילה אלא ויהי ערב ויהי בוקר יום אחד כי בחינת הרע נסתלקה ואינה ולילה כיום יאיר והיה אור הלבנה כאור החמה, והוא אומרו **יום אחד**, והוא שרמז הכתוב באומרו (זכרי' י''ד) ביום ההוא יהיה ה' אחד ושמו אחד:
@6 **ויאמר אלהים יהי רקיע וגו'**. פירוש הרקיע שברא ה' ביום אחד כמו שפירשתי בפסוק בראשית שהכל נברא יחד בדיבור אחד אלא שלא נתקנה מלאכת כל דבר ודבר על אופנה, עתה אמר אלהים שיקנה מקומו בתוך המים, ויהיה משמש דבר זה להבדיל בין מים למים ועיין בפסוק שאחר זה:
@7 **ויעש אלהים את הרקיע**. מקרא זה לא היה צריך לאומרו אחר שכבר אמר פסוק שלפני זה ויאמר אלהים וגו' בו היה לו לגמור אומר ויהי כן. ועוד רואני כי לא יוצדק לומר ויהי כן אחר אומרו ויעש אלהים אלא אחר אמירת ויאמר אלהים ישמיענו כי הוא אמר ותהי:
@7 **ונראה** לומר כי שלשה מלאכות נעשו ברקיע. הא' היא בריאת הוית גולמו במציאות, וזה הוא שנברא ביום ראשון במאמר הראשון:
@7 **והב'** שאמר אליו ה' שיעשה רקיע פירוש שימתח ויעשה וילון, ושיער ה' לו שיעור המיתוח הוא כדי שיספיק להבדיל בין מים למים, והוא האמור בפסוק שלפני זה:
@7 **והג'** להיות שהשמים כדוריים הם ומשופעים, כי אין לנו לומר שמשונית רקיע זו מכל השמים, ובדיבור שאמר יהי רקיע לא אמר אלא שימתח אבל סדר תיקונו אם יהיה נמתח כוילון בהשוואה או משופע לקצותיו או מוטה לאחד מצדדי ד' רוחות העולם אין זה נשמע במאמר ה' שאמר יהי רקיע, לזה חזר ואמר **ויעש** פירוש תקן סדר הערכתו כסדר תיקוני שמים שהם כקערה הפוכה לצד מטה ואחוריה למעלה לטעמים ידועים לבורא עולם, וחזר לומר **ויבדל** וגו', להיות כי סדר המעשה אשר הכינו הבורא הוא הפכיות למאמר הסמוך שיבדיל בין וכו' שאין כלי בסדר זה מונע בין ב' מימות אלו, לזה אמר שהגם שעשאו כסדר זה אף על פי כן ויבדל בין וגו':
@7 **ועל** ב' פרטים אלו אמר הכתוב **ויעש** שקבעו בסדר שישר בעיניו, ושעשה בו המצאה שיוכל שאת גם בסדר זה:
@7 **ודקדק** לומר **אשר מעל** וגו', לומר שהגם שהוא עשוי כסדר זה הבדיל בין מים שעליו מה שאין מציאות זה יכולה להיות בעולם, ואחר כל זה אמר **ויהי כן**, חוזר למה שכתוב בפסוק א' וב', כי כשאמר לו להיות נרקע כן היה, וכשאמר לו להיות מבדיל הגם שאין הערכתו כפי הטבע להבדיל בסדר זה כנזכר ויהי כן. או אפשר שטעם שעכב לומר **ויהי כן** אחר פסוק ויעש, שלא רצה לומר ויהי כן עד שהשלים המעשה בכל תנאי הבריאה:
@7 **ואחר** שכתבתי זה מצאתי כי מקרא מלא דבר הכתוב מעיד על פירושינו, דכתיב (ישעי' מב) כה אמר וגו' בורא השמים ונוטיהם, הרי שזכר ב' דברים הבריאה לבד והנטיה לבד, והוא שפירשתי במעשה א' וב', כי ביום ראשון היתה הבריאה, וביום שני היתה הנטייה, ובכלל הנטייה ואופנה הם ב' דברים שרמזנו:
@7 **וראיתי** מאמר רבותינו ז''ל בב''ר (פ''ד) וזה לשונם ויעש אלהים את הרקיע זה אחד מהמקראות שהרעיש בן זומא את העולם והלא במאמר אחד בדבר ה' שמים נעשו ע''כ, ולפי דרכינו והארץ שקטה מרעשה, ואולי כי מה שהרעיש העולם בן זומא היה קודם שיישב המקראות אבל אחר יישוב המקראות נחה שקטה הארץ:
@7 **או** יאמר על זה הדרך לפי מה שפירשתי בפסוק ויאמר אלהים יקוו וגו' כי ב' מימות הם א' זכר וא' נקבה, לפי זה לצד שהיו המימות כולם מעורבים כדרך שהיה האור והחושך מעורבים זעיר שם זעיר שם כאומרם ז''ל (ב''ר פ''ג) והבדיל ה' בין האור וגו', כמו כן מים העליונים פירוש המעולים והם הזכרים היו מעורבים עם מים התחתונים במדרגה, והן עתה אמר ה' שהרקיע יבדיל ב' הבדלות, הא' שיברר זה מזה כפי מה שהטביע הקב''ה בו שיברר זה מזה, והב' שיהיו מובדלים תמיד באמצעותו שהוא יפסיק בין שניהם, וכפי זה אומרו **יהי רקיע בתוך המים** כאן נתכוין אל הבירור המברר בין ב' המימות, והוא שאמר **בתוך המים** לפי שהיו כל המימות מעורבים, ואחר כך עשה ה' הכנה לרקיע שיהיה מוכן להפסיק בין שניהם תמיד וזו היא הבדלה ב', ועל שניהם אמר הכתוב ויהי כן:
@8 **ויקרא וגו'**. כאן הודיע כי אלו הם האמורים בפסוק בראשית וגו', ומה שקראם בפסוק ראשון בשם שמים פירוש בריאה אחת שעתיד לקרותה שמים, ולעולם לא קרא ה' לו שם זה עד יום ב':
@8 **ולדברי** רבותינו שאמרו (שם פ''ד) פירוש שמים הוא שא מים, יכוין הכתוב על זה הדרך **ויקרא ה' לרקיע** ואמר לו שא מים כדי שיהיה אויר למקום הנבראים כדי שיהיו הנבראים בין שמים לארץ, וזולת זה אין מקום ליושבי תבל עד שקרא לרקיע שישא המים שהיו מונחים עליו, ואמר למים התחתונים שיקוו למקום אחד ביום ג' ונתראית היבשה בזה הנה מקום ליושבי תבל. ואין סתירה לזה מדברי רבותינו שאמרו מים העליונים בנם עומדים, שהגם שהשמים הם נושאים אותם, עם כל זה לסדר תכונת השמים וסדורם הרגישו כי בנס עומדים כמו שכתבנו בפסוק ויעש:
@9 **ויאמר אלהים יקוו**. צריך לדעת מים אלו אם הם מים התהומיים, ובאומרו יקוו המים אל מקום אחד הנה לא נשארו מימות אחרים עוד, וזה הפך מה שאמר הכתוב (יתרו כ') ואשר במים מתחת לארץ, ואם הם מים אחרים לבד התהום, צריך לדעת במה היו מובדלים ממימי התהום לייחד הדיבור להם לבדם. גם לא ראינו שייחד הדיבור לומר מים פלוני יקוו אלא סתם יקוו המים כל מימות הנמצאים בעולם במשמע. עוד למה תלה ראיית היבשה בקויאת המים. עוד צריך לדקדק תיבת ותראה שהיה לו לומר ותהיה היבשה:
@9 **ובמה** שפרשתי בפסוק בראשית שבמאמר ראשון נברא הכל אלא היה מעורבב עד שהכין ה' סדר כל אחד דבר יום ביומו, וכפי זה מדברי ה' במאמר זה אנו יודעים כי היבשה היתה שטוחה תוך המים לרוחב העולם ומים למעלה ומים למטה לה ואותם המים שלמעלה ליבשה חלקם הרקיע ונשא חציים בכנפיו, כאומרו **יהי רקיע בתוך** וסתם תוך אמצע במשמע, וחצי הנשאר היה מכסה ליבשה ולאותם מים אמר ה' **יקוו אל מקום אחד** שהוא מי אוקיינוס **ותראה היבשה** במקום שהיתה בו בעת בריאתה כי שם קנתה מקומה אלא שהיתה מכוסה וגזר עליה שתראה. ואולי שיכנס במשמעות תראה לפי שלא היתה גלויה במראה היבשות והיה גוונה כגוון המים ואין היכר בין גבולה לגבול המים, וגם יכנס במשמעות תראה לפי שהיתה ראויה למה שראוי להיות מהיבשות לצורכי העולם. עוד ירצה באומרו **ותראה** להיות שכל עוד שהמים מטה ומעלה לארץ אין הארץ מתקיימת בטבעה כי המים יהפכו טבעה, וצא ולמד מה שכתב רמב''ם בריש הלכות דעות (הל' יסודי התורה פ''ד ה''ה) כי המים יהפכו יסוד העפר למים, לזה אמר יקוו המים וגו' ובזה תראה היבשה, ופירוש תעמוד ביסודה להפעיל סיבת בריאתה, ולעולם כבר קדמה בריאתה במאמר א' ביום א' כמו שנתבאר למעלה, גם נמצינו אומרים כי לא כל מימות העולם נקוו לים אוקינוס ויש תהומות למטה לארץ, ואפשר שהמים שנקוו אין הפרש ביניהם לתהום שמתחת לארץ ועל אותו חלק שאין בו ארץ אמרו ז''ל (חגיגה יב.) שאמר ה' לארץ די שלא תתפשט מסוף לסוף ונשארו המים מחוברים למים התחתונים:
@9 **אחר** שכתבתי כל הכתוב בא לידי מדרש מפרקי רבי אליעזר (פ''ה) וזה לשונו בשלישי היתה הארץ מישור כבקעה והמים מכסים על פני כל הארץ וכשיצא הדבר מפי הקב''ה יקוו המים וגו' הרים וגבעות נתפרדו על פני כל הארץ עלה תוכה של ארץ ונתגלגלו ונקוו המים וכו' ע''כ. הרי דכשאמר הקב''ה יקוו המים כבר היתה הארץ במציאות והם דברינו. הגם שלפי דברי המאמר נראה שמפרש **ותראה היבשה** פירוש שתהיה היבשה חול גבול לים, כשיראה המים ליבשה יקנו מקומם, על דרך אומרו (ירמי' ה') אשר שמתי חול גבול לים, ועשה מוראו של היבשה על הים, ופירוש **ותראה** מלשון יראה, והוא אומרו האותי לא תיראו וגו' אשר שמתי חול גבול לים, וזה משונה מפירושינו, זה דרך דרש, ודרכינו דרך פשט והכתוב יכוון לכל:
@9 **ורמב''ן** ז''ל פירש אומרו **ותראה היבשה** שהיה העפר מעורב עם המים וגזר ה' שיבדלו זה מזה ותסמך בחינת העפר ותהיה היבשה ע''כ. ופירושו ז''ל צריך ערב, גם אין פשט הכתוב מגיד זה, גם לפי דבריו ז''ל לא היה צריך להקוות המים אל מקום אחד אלא שיאמר ליבשה שתראה בסדר האמור בדברי הרב שיתברר העפר מן המים ויצוף למעלה וישארו המים במקומם, ועוד מהכתוב משמע שכל המים הנמצאים מתחת לרקיע שהיו סמוכים לארץ נקוו למקום אחד ולא כן משמע לפי פירוש הרב, ועוד אין לשון ותראה מדוקדק לדרכו ז''ל. והנכון בעיני הוא כמו שפירשתי שהארץ היתה תוך המים שטוחה ומים למעלה ומים למטה ממנה ועל מים שלמעלה לארץ גזר הגוזר שהרקיע יתמצע בתוכם וישא בכנפיו מים העליונים והחלק הנשאר מתחת לרקיע לא ישאר תחת כל הרקיע בהשוואה אלא יקוו במקום אחד, והוא אומרו **יקוו המים מתחת השמים אל מקום אחד** ובזה **תראה היבשה** כפשטה:
@9 **ונראה** לומר כי כל בחינות המים שעל הארץ בין העליונים ממעל לרקיע בין שנקוו למקום אחד הם בבחינת מים זכרים, ולזה תמצא שהולדת הזרעים תהיה ממימי אוקיינוס שהם מים הנקוים, כאומרם ז''ל (תענית ט:) שממימי אוקיינוס הם הגשמים ואחר שימטיר ה' מהם עולים מהתהום כנגדם, והוא אומרם ז''ל (שם כ''ה:) אין טיפה יורדת מלמעלה שאין טיפים עולים כנגדה מלמטה, ואין הזרעים צומחים לא מן הנמטרים ולא מהתהומיים כי זכר לבד או נקבה לבד לא ילדו. והא לך דבריהם ז''ל שאמרו (פדר''א פכ''ג) שב' מימות הם אחד זכר ואחד נקבה, וזה לשונם והמים גברו מאוד כשנתחברו המים זכרים עם מים נקבות גברו ביותר:
@10 **ויקרא אלהים ליבשה ארץ**. והיא המוזכרת בפסוק ראשון בראשית וגו', ואומרו תיבת **ויקרא** תתפרש בב' אופנים או לשון קריאת שם או לשון צעקה צעק עליה לבל תתפשט עוד כאומרם ז''ל (חגיגה י''ב.) שאמר לעולמו די, וכיון ששמעה ולא נתפשטה עוד קראה ארץ כאמרם ז''ל (ב''ר פ''ה) שעל שם שנתרצית נקראת ארץ. ואומרו **קרא ימים** לא זה הוא התהום האמור בפסוק ב' כי התהום יאמר על כללות מימות ואשר מתחת לארץ גם מימות הניקוים היה אז בבחינת תהום קודם שניראת הארץ כי היו שוים בתערובת עם מימות אשר הם הן היום תחת לארץ, ואומרו **וירא אלהים כי טוב** חוזר גם על מקוה המים כי בזה יש חיות וקיום העולם כי ממנו גשמים בעולם כאומרם ז''ל (תענית ט:):
@11 **ויאמר אלהים תדשא וגו'**. רז''ל (חולין ס.) אמרו שהגם שלא אמר הבורא למינו אלא לעץ נשאו הדשאים קל וחומר וכו'. וקשה כי לסדר הכתוב הקדים ה' דבריו על הדשאים ואם כן למה נתעכבו מלצאת תכף סמוך ממש למאמר ה' עד שגמר ה' אומר להוציא עץ שממנו נשאו קל וחומר. ולפי מה שפירשתי בפסוק בראשית כי כל מקום שיאמר דבר גבורות בשם אלהים ידבר בדבור אחד כל המאמר אם כן לא היתה הקדמה לדשאים קודם לעץ:
@12 **ותוצא הארץ וגו'**. אחר שאמר הכתוב ויהי כן לא היה צריך לומר כל פסוק זה, אלא הטעם הוא להשמיענו ב' דברים מחודשים אחד בדשאים ואחד בעץ, אחד בדשאים שעשו קל וחומר ויצאו למיניהם. וצריך לדעת לאיזה ענין הודיענו הכתוב שלא יצאו בערבוביא ואולי כי להודיענו בא שאין להרכיב דשאים זה בזה וכדבעי רבינא במסכת חולין דף ס' וזה לשונם הרכיב דשאים זה על גב זה לר' חנינא בר פפא מהו כיון דלא כתיב בהו למינהו וכו' או דלמא כיון דהסכים הקב''ה אידיהו כמאן דכתיב בהן למינהו דמיא תיקו ע''כ. ופירש''י בד''ה לרבי חנינא וזה לשונו דאמר מדעתן יצאו למיניהם ולא נצטוו על כך, ע''כ. משמע מדבריו דהש''ם סובר כי מן הסתם נצטוו על כך והגם שלא הוזכר בפירוש סמוך לדשאים מה שאמר הכתוב למינו לבסוף חוזר על העץ ועל הדשא, והנה לפי דברי ר' חנינא בר פפא דלא אמר ה' למינהו אלא לעץ והדשאים נשאו קל וחומר השמיענו הכתוב במה שחזר לומר ותוצא הארץ שהדשאים נשאו הקל וחומר. ולמאי דסובר הש''ס אם לא היה דברי ר' חנינא בר פפא שאומרו למינו חוזר גם על הדשאים, נראה כי ישמיענו שהדשאים הבינו הדברים על בוריין שמה שאמר למינו גם על הדשאים הוא אומר, וזה לא היה מובן לנו מפסוק ראשון, והגם שאמר בפסוק ראשון ויהי כן אף על פי כן אין מובן אומרו למינו אם חוזר לכל האמור בפסוק, ובא הכתוב הב' והכריע שחוזר אומרו למינהו לכל האמור בכתוב, ומכאן אתה למד שבכל מקום שיאמר ה' כסדר הדברים הנאמרים בענין זה שפירוש דבריו הם כמו שפעלו הדשאים:
@12 **והודיענו** הכ' במפעל הוצאת העץ כי הארץ לא קיימה מאמר הבורא שהוא אמר לה עץ פרי שעץ עצמו יהיה טעמו כטעם פרי והיא הוציאה עץ עושה פרי ולא כן העץ עצמו:
@12 **ואל** זה אביט איך תמרוד הארץ ברוקע הארץ, ומה גם כי אין לה יצר הרע, שלא הוכיחו חכמים (ברכות ס''א) שיש לה יצר הרע כי אם לבהמה מדבעטה וכו' ופירשנוהו במקומו (בס' חפץ ה') כי לצד שהיא צריכה לחוש היצר להזקק עשה הקב''ה לה יצר המחמם אבל הארץ לא מצינו לה שיש לה יצר הרע שיסיתה למרוד מרד לעבור פי ה':
@12 **עוד** יש לחקור זאת כי לא מצינו מוזכר בבריאה שאמר ה' שתוצא הארץ אילני סרק לתשמיש עצים ואנו רואים שגדלה בחינת העצים שהם בעולם אין קץ רבו מאילני פירות. ולזה אפשר לומר כי קודם קללת הארץ אשר אררה ה' היו כל האילנות עושים פירות אלא אחר שקלל האדמה נתמעט כחה ולא היו כל האילנות עושים פירות אלא קוצים ודרדרים:
@12 **אכן** פירושן של דברים הוא כי הארץ דקדקה בחכמת ה' אשר יסד בה דכתיב (משלי ג') בחכמה יסד ארץ דקדקה מאמר ה' לה שתוצא עץ פרי עושה פרי שסובל ב' דרכים, האחד שיהיה העץ טעמו כטעם פריו שאז תהיה הכוונה שיהיה העץ פרי וגם עושה פרי. ומאומרו עושה פרי פירשה דרך אחר שהכוונה הוא על זה הדרך עץ פרי לבד ועושה פרי לבד פירוש עץ שיעשה פרי לבד מהראשון והם ב' מינים. וטעם שלא אמר ועושה פרי בוא''ו שלא להבין שיהיה העץ עצמו פרי ועוד לו שיעשה פרי. גם במשמעות עץ פרי יש בה ב' דרכים, הא' עץ שהוא עצמו פרי, והב' שהוא ראוי לעשות פרי והוא אינו עושה פדי, ונתחכמה האדמה והוציאה ג' מינים הנשמעים בדברי ה' לרוב זריזותה, הא' הם אילנות שעושים פירות ואין טעם עצם כטעם פרים, והב' שעושים פירות וטעם עצו כטעם פריו והוא עץ הדעת טוב ורע שאמרו ז''ל (ב''ר פט''ו) שהיה טעם עצו כטעם פריו, והג' הוא עץ שהוא דומה לעץ פרי והם אילני סרק והרי היא נזדרזה לעשות כל הנשמע, והוא שאמר הכתוב **ותוצא הארץ דשא** וגו' **ועץ עושה פרי**, דקדק לומר **ועץ** בתוספת וא''ו ללא צורך, כמו שכן דבר הכתוב בסמוך בדברי ה' שלא הוצרך לומר ועץ בתוספת ו' נתכוון הכתוב לומר מלבד שאר עצים שהוציאה הוציאה עוד עץ עושה פרי, וכאן ריבה עץ פרי שאמרו ז''ל שעץ הדעת היה טעם עצו כטעם פריו. ואפשר דכלל גם כן עצים שאינם עושים פרי שישנם בעולם לכשנאמר שהיו קודם קללת האדמה, וטעם שקלל ה' האדמה למאן דאמר על אשר שינתה אפרש במקומו בסיעתא דשמיא:
@14 **ויאמר אלהים יהי מאורות**. טעם אומרו **יהי** לשון יחיד על ב', בזה רמז כי א' מהם הוא המאיר ביום ולזה אמר לשון רבים, ובאמצעות שדבר ה' בדרך זה הוא שהיה מה שהיה בתכלית הדבר שנתמעטה הירח כאומרם ז''ל (חולין ס:) כי אם היה ה' אומר פתח דבריו יהיו מאורות בהכרח היה הדבר עומד כן כי דבר אלהינו יקום לעולם:
@14 **עוד** נראה בהעיר עוד, אומרו **להבדיל בין היום ובין הלילה** אם המאורות שוים הם ואחד ישמש ביום ואחד ישמש בלילה במה יוכר לילה מיום כיון שלילה כיום יאיר:
@14 **אכן** ירצה הכתוב, להיות שקדם ביום ראשון וברא האור ותמצא שאמר בפרשה ראשונה ה' פעמים אור ורמזו ז''ל (תיקונים ה) כי ה' אורות נבראו והבדילם ה' לנחלתו לעתיד לבא לצדיקים, והן עתה ביום רביעי האציל מהאורות חלק המספיק לעולם ותלאו ברקיע השמים, והוא אומרו **יהי מאורות** פירוש יהי חלק אחד מאורות הנבראים ביום ראשון והתנה שלא יהיו קבועים אלא שיסובבו כדי שבאמצעות הסיבוב יוכר יום ולילה, וזה עשה לסימן הכרת הימים המקודשים כאומרו **לאותות ולמועדים** וגו', וכשנאצל המאור נאצלו ב' חלקים ושניהם לשמש מדת יום נבראו. ולזה תמצא (חולין ס:) שטענה הירח אי אפשר לב' מלכים להשתמש בכתר אחד פירוש בזמן אחד וכך הובא בדברי רבותינו, שאם גבולו של ירח היה בלילה ושל שמש ביום אין כתר אחד לשניהם אלא כל אחד גבולו בפני עצמו. וכן תמצא שאמר והיו למאורות ברקיע השמים להאיר על הארץ בלא קביעות זמן:
@15 **והיו למאורות וגו'**. משמעות הכתוב יגיד כי צוה ה' שיהיה אור המאורות בוקע בשמים ועוד לו שיאיר בארץ, פירוש שיאירו המאורות בכל הקף השמים וגם יגיע אורם עד למטה לארץ. עוד ירצה כי הכינם ה' שיאירו תוקף אורן ברקיע ומהאור המתפשט ברקיע תאיר ארץ כי אין כח בארץ לסבול תוקף אור המאורות והוא שדקדק לומר **למאורות ברקיע השמים** פירוש כי שם יאירו, ואומרו **להאיר על הארץ** פירוש כי מאור הבהיר בשחקים תאיר ארץ. ולדבריהם ז''ל (חגיגה יב:) כי המאורות ברקיע ב' אין מאור המאורות בוקע אלא בשמים והשמים ב' הם מאירים לארץ. ומה שאמרו ז''ל (יומא כח:) יומא דעיבא כוליה שמשא, אינו מכחיש דברינו כי על כל פנים מקום השמש הגם שמתפשט תוקף השמש לצדדין יש הבדל בין מקום קביעות השמש שיש בו תוקף יותר מצדדיו ויומא דעיבא חוזר פעם ב' ומתפשט תוקף השמש הנשאר מכוון כנגד הארץ שיעור שתוכל לסבול חוזר ומתפשט בגובה השמים באמצעות העננים והיינו כוליה שמשא:
@16 **ויעש אלהים וגו'**. טעם שלא הספיק במה שאמר כבר ויהי כן על כל האמור. כי מעשה זה הוא מעשה חדש שאחר שנתמעטה הירח כאמור בדבריהם תיקן ה' וקבע מעשה חדש שקבע ממשלה לירח בלילה כי ביום אין לה ממשלה לפני אור השמש וליוה לה הכוכבים ואין בזה הפכיות למה שאמר ה' בתחלת דבריו, כי כבר רמז אחרית דבר מראשיתו כמו שדייקתי באומרו יהי. והגם שפירשנו אותה באופן אחר סובלת היא ב' הפירושים:
@17 **ויתן אותם**. לא הספיק לומר ויהי כן. כי רצה להודיענו כי ה' נתן בתורת מתנת חנם דבר זה להאיר לעולם כאומרם ז''ל במדרש (ב''ר פ''ו) יעוין שם. והכוונה בזה שהודיעם כי אינם מאירים לעולם לצד שראוים לאור דאם כן כל זמן שיראו המאורות כי יושבי תבל משחיתים דרכם יאספו נגהם. גם באמצעות איזו סיבה יחפצו לאסוף נגהם כמו שאמרו במדרש (פתיחתא לאיכה רבתי) שאמר משה רבינו עליו השלום לשמש בחורבן הבית למה לא חשכת אורך כשנכנם אויב לבית המקדש וכו', לזה אמר ה' כי הם נתונים להאיר על הארץ ומעתה אינם ברשות עצמן ומוכרחים הם במעשיהם להאיר ואין סיבה מונעת. ובזה האירו עינינו למה חזר פעם ב' הכתוב לומר **ולמשול ביום** הלא כבר אמר המאור הגדול לממשלת היום וגו'. ורז''ל (ב''ר פ''ו) דרשו שהכתוב רומז אל הצדיקים יעש''ד. אבל לפי הפשט אין צורך לחזור ולומר, ולדרכינו הוצרך לחזור ולומר מטעם אומרו ויתן כי נתונים נתונים המה מעתה הנה אינם ברשות עצמן וחיוב אחרים עליהם, לזה חזר ואמר כי ממשלתם במקומה עומדת אלא דוקא לבחינה זו להאיר דוקא אין בידם לשנות אבל בשאר הממשלות שישנם ביום ובלילה המיוחדים להם הן הנה המושלים:
@17 **וטעם** שחזר לומר עוד **ולהבדיל** כאן צוה להם שלא יכנסו זה לגדר של זה וכל אחד מצווה על גבולו לבל יעבור שבזה יהיה ניכר יום מלילה:
@20 **ויאמר אלהים ישרצו וגו'**. פירוש שיתהוו מהמים בריות ודבר זה אינו בתמידות אלא בשעת מאמר הבריאה ואותם הבריות ששרצו המים עמדו לעולם כמין הבהמי אשר הוציאה הארץ שלא הוציאה אלא בשעת המאמר ועמדו לעולם כמצות ה' להם שישרצו ויפרו וירבו. ואומרו **שרץ נפש חיה** הם הדגים. ואמר לשון שרץ להפריש בינו ובין המעופף כי זה אין לו כח אלא בסמוך ממש לארץ והמעופף יעופף על הארץ ואינו צריך להסמך ועוד לו שיגביה עד לשמים כאומרו על פני רקיע וזולת מאמר זה לא היו העופות מגביהים עד לשמים:
@20 **ואומרו רקיע השמים** פירוש רקיע הנקרא שמים. ואין להקשות לדבריהם ז''ל שאמרו (ב''ר פ''ו) וזה לשונם היכן חמה ולבנה ברקיע ב' שנאמר ויתן אותם אלהים ברקיע השמים מקרא מלא הוא ואנשי כנסת הגדולה פירשוה (נחמיה ט) אתה עשית את השמים ושמי השמים וכל צבאם היכן הם צבאם ברקיע ב' ע''כ. לדבריהם ז''ל מה יענו בפסוק זה ועוף יעופף על פני רקיע השמים:
@20 **ונראה** כי על פי הנקודות ישתנה כתוב זה מקרא דויתן אותם וגו' כי כאן כתב קמ''ץ תחת רי''ש של רקיע ושם כתב שב''א תחת הרי''ש של רקיע והנה כשאמר רקיע בשב''א יגיד שהוא סמוך פירוש רקיע של שמים וכשיאמר רקיע בקמ''ץ אינו סמוך לשמים ופירוש הוא רקיע והוא הנקרא שמים ובזה לא קשה והבן:
@21 **ויברא אלהים וגו'**. פירוש הוסיף ה' כח בב' פרטי הבריאה שנבראו מן המים, ומה שחזר לומר ואת כל נפש החיה וגו' ולא הספיקו המים להוציאם מה שלא מצינו שעשתה האדמה בהוצאת הדשאים והעשבים שהספיקה אמרת ה' לה. דע כי אין המצמיח ולא הבורא בורא יותר ממה שיש בכח תולדתו כי איך יתן אדם מה שאין בו, והגה המים והעפר הם מחוסרי רוח החיונית ומנין להם רוח לתת בברואיהם. והגם כי הארץ והמים יש בהם חיוניות דק עד מאד, הגם שיתנו ממנו לא יתנו יותר ממה שבהם וזה לא יספיק לדגים ולעופות, אשר על כן לא הספיק כחם והוצרך ה' לברוא להם רוח החיונית והוא אומרו **ויברא** וגו' **את כל נפש** וגו'. והגם שבצוותו למים אמר ישרצו שרץ נפש חיה, פירוש שרץ שתהיה בו הכנה לקבל נפש חיה, כי יש לך לדעת כי החיוני ירצה הכנה והוא אמצעי בינו לבין החומר וזה ישנו בכח המים לעשותו כמו שאמרנו שיש בכחם כח רוחני דק, ובתנינים הגדולים עשה ה' שינוי בבריאתם כמו שאמרנו, ולא אמר בדרך כלל ויברא נפש התנינים ואת כל נפש וגו' בזה גילה הכתוב כי משונים הם מכל מה שבים שמלבד שהוליד בהם נפש גם בכח בריאתם עצמה ברא ה' בהם כח נוסף אשר אין כח בים לעשותו כמו שאמרנו, וזה הוא הדג המופלא לויתן זה, וכבר דבריו מפורשים בדבריהם ז''ל (ב''ב עד:). וטעם שלא אמר בבריאה זו ויהי כן, אין לו מקום כי לא יצטרך לומר ויהי כן אלא כשלא יוזכר אלא אמרות ה' לבד תגיד התורה ויהי כן כי אמר ותהי מה שאין כן כשאומר ויברא יש בכללו אמירה יש בכללו הויה:
@22 **ויברך** טעם שהוצרך ה' לברך שרץ המים מה שלא עשה כן בנבראים היוצאים מן הארץ. ועוד לו שגם בתולדות המים עצמם הטיל קנאה שלא בירך שרץ העוף. נראה כי הדבר צריך להיות כן מטעם הכרחי לפי מה שפירשנו כי מה שצוה ה' למים שישרצו אינו אלא לפי שעה ולא לאחרי כן ולקיום המין צוה ה' שיפרו וירבו שאם לא כן הרי מינם כלה, ולהיות שכפי טבע הנבראים אשר ברא ה' כח המוליד היא יסוד האש כי טבע הקור אדרבה יפסיד כח ההולדה. וצא ולמד מחכמת הטבע גם מדבריהם ז''ל (שבת קנו:) שאמר ה' לאברהם מאי דעתיך דקאי צדק וכו' דכתיב (ישעי' מא) צדק יקראהו לרגלו יעש''ד, וכפי זה הדגים אין להם מציאות כפי טבע הקבוע בנבראים להוליד, אשר על כן חזר ה' במאמרו הנכבד וברכם לאמר פירוש כוונת הברכה שברכם הוא לומר שיוכלו להוליד ולא ימנעם קרירות המים ולא יצטרכו לצאת חוץ למים להתחמם בארץ כדרך התרנגולים (ביצה ז) דספני מארעא אלא תוך המים יעשו פרי והוא אומרו **ומלאו את המים בימים** וקשה למה הוצרך לומר בימים ולא הספיק באומרו ומלאו את המים אלא הכוונה היא שבתוך הימים שם ישרצו וזו היא ברכת המברך ברוך הוא. וגמר אומר **והעוף ירב בארץ** כי הוא ירב כדרך כל הארץ ונכון:
@24 **ויאמר אלהים וגו'**. גם זה לא היה אלא לפי שעה כדרך שפירשנו בבריאת שרץ המים. וטעם שלא הוצרך לומר להם שיפרו הלא הטביע בהם ההולדה והם מעצמם ילדו אלא שצוה להם שלא יתערבו מין בשאינו מינו והוא אומרו **למינה** וגו':
@25 **ויעש אלהים**. פירוש בריאת נפש החיונית על דרך שפירשנו בשרץ המים. ורש''י פירש באופן אחר ואלו ואלו דברי אלהים חיים:
@26 **ויאמר אלהים נעשה אדם וגו'**. הכוונה בזה כי לא ברא ה' את האדם כבריאת שרץ המים ושרץ הארץ אשר אמר למים והשריצו ואמר לארץ והוציאה אלא הוא הבורא אמר שהוא יעשה האדם. ואמר **נעשה** כי הוא מקור הענוה לזה דבר בלשון רבים כי כן ידבר יחיד העניו, ולא חש לתת מקום לטעות, כי הקדים לומר ויאמר אלהים שם יחיד ה' הוא האלהים הוא בכבודו ובעצמו כביכול גבל עפרו והפיח בו רוח חיים. עוד ירצה באומרו **נעשה** בלשון רבים כי מדותיו של הקב''ה רבים הם י''ג מדות רחמים ושם אלהים שהוא מדת הדין הסכימו יחד לברוא אדם, ואומרו **בצלמנו כדמותנו** אפשר שיכוין לומר שיהיה בו צד הרחמים וצד הדין להפעיל בהם דרכי הדין ודרכי הרחמים לאשר יכונו והבן. והוא סוד אומרו (ב' ז') וייצר ה' אלהים וגו'. ואומרו **וירדו** יסכים לפירושינו להיות שהבריאה היא בהדמות לבורא בבחינות הרחמים והדין בדין הוא שיהיה מושל בנבראים כי יש בו בחינת הרחמים לראוי ולצריך אליו ולהמית למתחייב בדין. והשליטו בכל, והגם שלא הזכיר שליטה במים רמוז באומר בדגת הים הרי הזכיר הים בנשלטים. ובדרך רמז רמז באומרו לשון ירידה על דרך מה שהודיענו ז''ל (ספר הגלגולים) כי באמצעות מעשי האדם ירד במדרגתו מבחינת אדם לבחינת דגים ולבחינת עופות ולבחינת בהמה ולבחינת שרצים כפי ערך החטא ישפל אדם מבחינת מעלתו עד אשר ירד מטה מטה רחמנא ליצלן והוא שרמז כאן בשעת הבריאה חלקי ירידות ההדרגות שבהם יקבל עונשו וגם שבאמצעותם יחזור לשורשו. והקדים לומר ירידת נפש אדם למדריגת הדגים כי ירידה המיועדת לנפשות הרמות כי יחטאו היא שתרד נפשם להתגלגל בדגים ולזה יחם הכתוב להם במקומם אסיפה כי אין להם להצטער בצער שחיטת חרב אלא אסיפתם מתרת אותם (חולין כז:). ואחר כך אמר ירידה הפחותה ממנה והוא גלגול הנפש בעוף וזה יצטרך צער יתר על הדגים, וצוה ה' ב''ה בו חצי שחיטה כאותה ששנינו רוב א' בעוף. ואחר כך אמר ירידה בבהמה שהיא בחינה גרועה יותר וצערו מרובה כאותה ששנינו (שם) רוב שנים בבהמה. ואחר כך אמר ירידה שהיא בדומם וצומח והוא אומרו **ובכל הארץ** תיבת הארץ תגיד על הדומם ותיבת בכל רמז בה הצומח וכל אלו הם ירידות הנפשות אשר ישנם בתקות התיקון לשוב לקדמותם כי מהדומם יעלה לצומח ומהצומח יכנס בבעל חי בלתי מדבר ומבעל חי בלתי מדבר יעלה לבעל חי מדבר, וישנו עוד בירידה פחותה והוא כליון שאין אחריו תקוה והיא ירידה לבחינת שקצים ורמשים זה אבדה תקותו והם בחינות הרשעים הממירין דתם פושעי ישראל אשר הפליאו עשות:
@27 **ויברא אלהים את האדם בצלמו**. פירוש בצלמו הניכר באדם, והכונה שברא גולמו וגם צלמו ואחר כך אמר **בצלם אלהים** בזה הודיענו הצלם שבראו בו כי הוא צלם אלהים. עוד ירצה לומר כי ברא האדם בב' צלמים הראשון צלם הניכר בכל אדם ואפילו בבני אדם הרקים מהקדושה אשר לא מבני ישראל המה ועליהם אמר **בצלמו** פירוש של הנברא, והב' הם בחינת המאושרים עם ישראל נחלת שדי כנגד אלו אמר **בצלם אלהים** בראו הרי זה בא ללמדנו כי יש בנבראים ב' צלמים צלם הניכר וצלם אלהים רוחני נעלם והבן:
@28 **ויברך אותם**. פירוש שלא יכרת מין האנושי, **ויאמר** וגו' צוה אליו לפרות ולרבות, שהגם שבירך אותם שיהיה מין האנושי קיים לא מפני זה יתרשלו מלפרות ולרבות. וראיתי דעות נפסדות בנבראים מבני עמינו דכשיש ג' או ד' אחים א' או ב' מהן משתדלים בפריה ורביה ואומ' כי הוא זה קיום המין. גם באדם א' כשיקיים מינו תבא לו הסברא שלא ישתדל עוד לפרות ולרבות. לזה אמר ה' תחלת דבר ה' מצות ה' ברה אמר **פרו ורבו** ולא עשה גבול למצוה והגם שבירך אותם שלא יכרת מין האדם מן העולם. וגמר אומר **ומלאו את הארץ**. ואומרו **וכבשוה** סמוך לומלאו לומר כי באמצעות שימלאו הארץ בזה תהיה נכבשה לפניהם כי מקום החרב אין אדם שולט בו כי לצד שוממותו הוא מתמלא נגדיים לאדם. עוד ירצה באומר **ויברך אותם** שיהיה בהם כח המוליד ואחר כך צוה אותם על הדבר:
@29 **ויאמר אלהים הנה נתתי לכם וגו'**. שיעור הכתוב הוא על זה הדרך להיות שכבר אמר ומלאו את הארץ וכבשוה ורדו וגו' בזה עשה את האדם אדון ושליט בכל הבריאה ועתה בא לומר תועלת הנתינה שהוא לאכלה ובזה הרשה אותם לאכול מהצמחים, וממוצא דבר אתה יודע כי מה שנתן להם דגת הים ועוף השמים והבהמה אינו אלא למשול בהם לא לאכול מהם כי פרט על אחד מהנמשלים שהוא לאכילה ולא כולם:
@29 **ואת כל העץ אשר בו פרי עץ**. כאן שלל עץ הדעת כי אינו בגדר זה עושה פרי לבד אלא שהוא עצמו פרי ושיעור הכתוב הוא על זה הדרך **ואת כל העץ** ולא כל העץ בכלל אלא אותו אשר בו פרי עץ ולא אותו שהוא עצמו פרי שהוא עץ הדעת שנצטווה עליו אחר כך בפירוש. או יאמר דאפילו עץ הדעת בכלל והגם שמצינו שנצטוה עליו, כבר אמרו ז''ל (ב''ר פכ''א) שאם היה ממתין עד ערב שבת היה מקדש על היין ע''כ, ומתוך דבריהם אתה למד כי לא נאסר איסור עולם:
@30 **ולכל חית הארץ וגו'**. סמך הכתוב חית הארץ עם האמורים בסמוך לכם יהיה לאכלה וגו' שנראה שנותן מאכל אדם לבהמה בהשואה וגמר אומר **לאכלה** פעם שנית סמוך לירק עשב שנראה שאכילת בהמה ועוף אינו אלא מעשב השדה. הכוונה היא כי לא ברא ה' לבהמה חיה ועוף אלא דוקא ירק עשב, ושמא תאמר אם אין ירק עשב נמצאת החיה מתה תלמוד לומר לכם לאכלה ולכל חית הארץ וגו'. נמצינו אומרים כי האדם יחיה מפירות הארץ ומפרי העץ והחיה והעוף מהעשבים והירקות, ואם אין מחיה מאלו הרי מחייתה ממאכל אדם. ויש לרמוז זה באומרו (עקב יא) ונתתי עשב בשדך לבהמתך ובזה ואכלת ושבעת אבל זולת זה תחסר השביעה כי תאכלנו החיה והעוף כי מזונותם מזונותיך:
@31 **וירא אלהים וגו'**. פירוש באמצעות בריאת האדם נראה מעשהו בכללותו כי טוב הוא, כי אם אין אדם מה תועלת בכל התיקון ובכל הבריאה וצמחי האדמה, כי אין הבחנת טובה ניכרת אלא באמצעות האדם, כי אליו יוכר ויובחן הטוב ויודה למטיב. ואומרו תיבת **והנה** מה שלא דקדק לומר בימים שאמר בהם כי טוב להיות כי האדם מצינו לו שקלקל מעשיו ועשה מעשה הרע, לזה דקדק לומר **והנה** כי מה שהיה אז לצד מעשה ה' טוב היה מאוד ואחר כך הוא האדם בקש חשבונות רבות לצד היות הבחירה בידו להרע או להטיב ושלל הטוב והיוה במעשיו בחינת הרע אבל לצד מעשה ה' לא ברא אלא לצד הטוב. עוד ירצה באומרו **וירא אלהים** וגו' כאן רמז כי בשעת בריאת האדם הביט ה' בצדיקים (ב''ר ג') והוא אומרו **וירא** וגו' **והנה טוב** שהם הצדיקים. והגם שהביט ברשעים גם להם הכין ועשה תיקון לבריאתם והוא אומרו **מאד** ואמרו ז''ל (ב''ר פ''ט) מאוד זה מלאך המות שבאמצעותו נתקנים הנבראים הנוטים מדרך השכל. ולזה כנגד בחינת הצדיקים אמר **והנה טוב** פירוש הנה הנם בחינת טוב מבלי צורך מות. וכנגד בחינת המטים עקלקלותם ישנם גם הם בבחינת טוב באמצעות מאוד:
@31 **עוד** ירמוז כאן טעם הבריאה, למה שידענו כי עיקר הכל הוא האדם ובשבילו ואליו ברא ה' כל ברואיו, ומעתה תבא השאלה לאדם למה, לזה אמר **והנה טוב מאוד** פירוש שהגם שבחינת נשמת האדם הוא מבחינת הטוב עכ''ז בראו ה' לעלות במעלות הטוב יותר ממה שהוא והוא אומרו **מאד** על ידי מעשה האדם מתעלית נשמתו ממדרגה למדרגה אשרי אנוש יעשה זאת:
@32 **ויכלו השמים וגו'**. מקרא זה לא ידענו מה בא ללמדנו, ונראה כי יכוין לומר על דרך אומרם ז''ל (ב''ר פס''ח) הקב''ה מקומו של עולם. גם מצינו כי הוא מלא עולם כאמור (ישעי' ו) מלא כל הארץ כבודו ומעתה אורו יתברך נמצא בהקף העולם ובפנימיותו. וצריך לתת לב לדעת טעם הדבר למה עשה ה' ככה. ומקובלני מפי זקני תורה כי טעם שעשה ה' העולם כדורי הוא כדי שיעמוד ויתקיים בהשוואת כחי חלקיו. ופירושן של דברים הוא יש לך לדעת שאין תשוקה בעולם עריבה וחביבה ונחמדת ונאהבת ונתאבת ומקוות לנבראים ובפרט לחלקי הרוחני המכיר ויודע בחינת אור האלהות כהדבקות באורו יתברך ואליו יכספו כל נפש חיונית המגעת להכיר קצת מנועם אורו יתברך תצא נפשם לחזות בנועם ה'. ולך לדעת כי כל אשר ברא ה' בעולמו יצר בו ה' בחינת ההשכלה וההבחנה כפי בחינתו בעלי חיים מדברים ובלתי מדברים וצומח ודומם יש לכל אחד כח מההשכלה להכיר יוצרו כפי השגתו. ובזה תשכיל לדעת העמדת העולם באיזה דבר הוא תלוי ועומד מבלי התנועעות כי ה' גילה סודו אל יראיו ובאמצעות ההערות הנאמרים הושג המורגש. והוא כי באמצעות אורו הנערב והמקווה אשר יסובב כדוריות העולם בהשוואה וכל חלק וחלק מהסובב של העולם יתעצם בכח אש התשוקה הבוערת בו להתקרב לבחינת כללות נצר המקווה ולהיות כי כל בחינת סיבוב העולם תשוה בו שיעור התשוקה בין מצד מה שממנו כי אין תאות חלק אחד רבה על חברו שבאמצעות זה יתרבה התעצמות החלק ההוא ויחלש שכנגדו בין מצד מה שאליו הוא האור הנעים כי אינו קרוב לחלק מהסובב יותר מחברו שבזה יגדל חלק מהעולם בכח התעצמותו יותר מחלק אחר אלא הכל בהשואה וכל חוט השערה מכל חלקי הסובב של העולם יתעצם להתקרב ומושך לצד הפונה אליו ובאמצעות התעצמות הנמשך מכל סביבות כדוריות העולם נמצא העולם עומד וקיים וכל חלק מעמיד את חבירו באמצעות האמור ונמצא כל העולם תקוע ביתדות ומסמרי חשק הבורא לצד כלות ונטות רוחניות שבו להתקרב להנערב יתעלה שמו. ובזה אתה משיג טעם שברא ה' העולם כדורי והבן. ובזה גם כן מצינו טעם למה העולם נרקע ונתקע בלי התנועעות כי ההתנועעות תתהוה לצד הגברת והחלשת חלק מחלקי המעמיד מה שאין כן במציאות זה אי אפשר להתנועע בשום אופן:
@32 **ואפשר** כי לזה רמזו ז''ל בנועם אמריהם (חגיגה יב:) וזה לשונם דקיימי ולא ידעו על מה קיימי ע''כ, הכוונה כי אם היו הנבראים מבחינים הבחנה זו וידעו רום מעלת חיבת הקודש ותשוקת הנבראים לנעלם הנערב ויראו כמה הוא עוצם התקוה והתעצמות דומם זה שהוא העולם אשר מתעצם להתקרב ליהנות מאור המקווה ולא נהג רפיון בשום חלק מסובב העולם ישאו קל וחומר מזה כמה צריך האדם לעשות כי בו נתרבית ההבחנה וההשכלה. גם יש לך לדעת כי להיות שכל הנבראים במלא עולם כל אשר רוח החיוני בו אמרו ז''ל (ילקוט תהלים קנ) כי אין כל נפש מתישבת במקומה כי אם לצד שישנו לנכסף ומקווה מלא עולם הזה לא תגעל הנפש את הבשר ולטעם זה האיר ה' עולמו מכבודו וכבודו מלא עולם ונמצא העולם בתוך תוך בוראו ואור הבורא בתוך כל העולם וסובב עולמו ובזה עמד ונתקיים העולם באמצעות התשוקה למצוי, והוא אומרו **ויכלו השמים והארץ וכל צבאם** פירוש ויכלו על דרך אומרו (תהלים פד) נכספה וגם כלתה ובאמצעות זה נשלמה ונתקיימה הבריאה. וטעם שהוציא הכתוב הענין בלשון זה ויכלו לרמוז כי הוא תשוקה גדולה עד כלות החלק אל הכל והוא בחינה גדולה מבחינה החשק והתשוקה, והוא שרמז דוד באומרו נכספה וגם כלתה הרי זה מגיד כי בחינה זה גדולה מבחינה שלפניה ובאמצעות בחינה זו והתעצמותה העולם קיים. וזה הוא סוד קריאתו חי העולמים והבן והוא סוד באור פני מלך חיים:
@33 **ויכל אלהים** וגו'. פשט הכתוב הוא שבא ללמדנו שלא תחשוב שעשה מלאכה אחרת אחר כך ולא הוזכרה בתורה לזה אמר **ויכל אלהים** פירוש כלה מה שעלה בדעתו יתברך לעשות. וכאן שלל גם כן שלא עשה מלאכה אחר השבת בששה ימים אחרים והבן. אלא שיש לתת לב לאומרו **אשר עשה** שלא היה צריך לומר אלא ויכל אלהים וגו' מלאכתו. עוד יש להעיר אומרו **ביום השביעי** משמע כי ביום השביעי עשה מלאכה וכלה אותה ואינו כן כי ביום הששי הוא שכלה. והגם שרז''ל הרגישו לתקן זה ואמרו וזה לשונם (ב''ר פ''י) רבי שמעון אומר בשר ודם אינו יודע וכו' ע''כ, עם כל זה תיבת ביום אינה מדוייקת ולפי דבריהם פי' הוא כאילו ביום. ובאמת כי דבריהם דברי אמת אלא עוד יש לאלוה מילין וכפטיש יפוצץ:
@33 **ונראה** שיכוין הכתוב לומר על דרך אומרם ז''ל (חגיגה יב) כי העולם היה רופף ורועד עד שבאה שבת ונתקיים העולם ונתייסד. והכוונה הוא כי ביום שבת ברא ה' נפש העולם והוא סוד אומרו וביום השביעי שבת וינפש. הגם שחז''ל (ביצה טז) דרשו כיון שיצא שבת וינפש, אין זה אלא דרך דרש שדרשו מאומרו וינפש ולא אמר ונפש דרשו כי נתכוון הכתוב לרמוז כיון שיצא שבת וי שאבדה הנפש אבל משמעות פשט הכתוב אינו יוצא ממנה שנתכוון לומר כיון ששבת פירוש בא שבת וינפש פירוש נשפע שפע החיוני בכל הנבראים כי קודם השבת לא היה נפש לכל הנבראים. וכן מצאנו לרז''ל בספר הקדוש זוהר התורה (תזריע מד.) שנתנו טעם למצות ה' למול ביום השמיני ושלא לקרב קרבן לה' עד יום הח' כי הטעם הוא עד עבור עליו יום השבת ויהיה בעל נפש. והוא שאמר הכתוב **ויכל אלהים** וגו', פירוש שכלה ה' באמצעות יום השביעי מלאכתו וחזר ופירש מה הוא מלאכתו שכלה לא שהיה חסר דבר מעשותו ועליו הוא אומר ויכל אלא הכוונה היא אשר עשה פי' המלאכה שכבר עשה עדיין היתה חסרה דבר המעמיד ובאמצעות יום השביעי בו נגמר הענין. ובזה נתיישב מה שדקדקנו. גם בזה הרווחנו למצוא בתורה בריאת יום השביעי עצמו כדרך שהודיעה אותנו התורה בריאת יום ביומו דכתיב ויהי ערב וגו' הרי זה מגיד הוית הערב והוית הבקר וכאן לא מצינו שהודיע בריאת יום זה, ולדרכנו הרי הוא אמור. ולמה שפירשתי בפסוק ויכלו שהוא לשון תשוקה וחשק יכול להתפרש גם כן אומרו **ויכל אלהים** וגו' על דרך אומרו (איוב יד) למעשה ידיך תכסוף וכתיב (דברים י) רק באבותיך חשק כי האדון חשק וחפץ בעולמו וזה היה באמצעות יום השביעי שנתקיים העולם כדרך שפירשנו חשק ה' ונתרצה בבריותיו ודבר זה הובא בדבריהם (שה''ש ב') ז''ל ועיין בסמוך:
@33 **וישבות ביום השביעי וגומר**. מקרא זה מה בא ללמדנו כי הם הדברים עצמן הנאמרים בסמוך ויכל אלהים:
@33 **ונראה** לומר על דרך מה שאמרו ז''ל (ב''ר פ''ז) כי בריות נבראו ערב שבת עם חשיכה ולא הספיקו לגמור בריאת גופם עד שקדש היום והן הם המזיקים ע''כ. ויש לנו להשכיל זאת איך יוצדק לאמר בערך הבורא יתעלה שמו שלא הספיק לגמור וכו' הלא דבר ידוע לכל כי כהרף עין יכול לברוא עולמות כולם. וצא ולמד מה שכתבנו בתחילת הפרשה ותראה קצת גבורותיו יתעלה שמו:
@33 **אכן** הכונה היא כי רצה ה' להודיע עוצם מעלת יום המכובד כי הלא תדע שישתנה הדבר בין מלאכה שהתחיל בה ואין בה הפסד למלאכה שכבר התחיל בה ותפסד אם לא יגמור אותה. וכאן הודיענו הכתוב כי מלבד שלא התחיל במלאכה אחרת אלא אפילו במלאכה שהתחיל בה כשקדש היום גם כן שבת מלגמור אותה הגם שנפסדה המלאכה שהתחיל בה הפסד שאין אחריו תיקון אף על פי כן לא רצה לעשות עוד. והוא שרמז באומרו **וישבות** אחר שאמר ויכל כי מלבד שכלה ולא הוסיף עוד עשות בריאה אחרת אלא אפילו מה שהיה בידו להשלימו שבת פירוש בטל גמר הדבר שהיה בידו, ולזה אמר **מכל מלאכתו** לומר אפילו מלאכה שכבר התחיל בה והוא אומרו **אשר עשה** והתחיל בה כיון שבא יום השביעי שבת מלהשלימה. וה' עשה כן להראות דבר זה לא לצד מניעת היכולת ח''ו כי פשיטא שבהרף עין בורא כהנה וכהנה רבי רבבות, גם אומר אני כי לטעם זה סדר ה' המלאכות שעשה בסדר הימים דבר יום ביומו כדי שיוכר מעלת השבת כי זולת זה יכול היה ה' לעשות כל המעשה ביום אחד ובזמן מועט:
@34 **ויברך אלהים וגו'**. צריך לדעת מה היא הברכה, ורז''ל (ב''ר פי''א) אמרו ברכו במן וכו', ודבריהם ז''ל אינם אלא רמז בכתוב אבל הפשט לא ידבר על זמן מהזמנים העתידין. והנכון במשמעות הכתוב הוא כי להיות שהעולם הזה צריך הוא לשפע המקיים והוא בחינת האכילה והשתיה וצורכי האדם וכולן מושגים על ידי טורח ויגיעה הגשמית וחולין היא וה' כשרצה לקדש יום השביעי קדם וברכו שלא יחסר בו דבר הגם שאין טובת העולם השפל מושגת מהפרישות והקדושה אלא מעסק חול אף על פי כן ברכו שלא יחסר טוב ועוד לו שהוא יתר על שאר הימים לחם משנה שלש סעודות ותענוגים יתירים וזו היא ברכתו והוא דבר הפך הסדר. ולמה שפירש בזוהר (יתרו פ''ח) כי ביום השבת משתלשל השפע של כל ששת ימי המעשה יכוין על זה אומרו **ויברך** כי בו צוה ה' את הברכה לחיות העולמות:
@34 **כי בו שבת וגו'**. צריך לדעת כוונת הכתוב במאמר זה:
@34 **ונראה** לפרש לפי מה שכתבנו למעלה כי העולם היה חסר הקיום עד שבאתה שבת ועמד העולם. ויש להעיר בזה שאותם ימים קודם שבאה שבת במה היה העולם עומד וכשם שהספיק לחיות באותן ימים בלא נפש השבת היה מתמיד והולך:
@34 **אכן** מצינו כי הקדוש ברוך הוא גילה הדבר במה שאמר (שמות כ) בעשרת הדברות כי ששת ימים עשה ה' את השמים וגו' הרי גילה כי בשעת הבריאה לא ברא ה' כח בעולם זולת לעמוד ששת ימים לטעם הנודע לו גם ידוע ליודעי אמת. ונתחכם ה' וברא יום אחד הוא ידוע לה' ובו ביום חוזר ה' ומשפיע נפש לעולם שיעור המקיים עוד ששת ימים וכן על זה הדרך וזולת זה היום היה העולם חרב בגמר ששת ימים וחוזר לתוהו ובוהו וצריך ה' להכינו פעם ב' ובאמצעות שבת העולם עומד, והוא אומרו **כי בו** פירוש באמצעות יום זה שבת מכל מלאכתו ופירש מה הוא המלאכה היא הבריאה עצמה כי לא מהתיקון שהוא המעשה לבד שבת אלא גם מהבריאה, וכבר כתבתי למעלה שהבריאה היא יש מאין והוא מה שנברא ביום ראשון בדיבור אחד והמעשה הוא התיקון אשר תיקן דבר יום ביומו ובאמצעות יום שבת משפיע בכללות העולמות רוח המקיימת עוד ששת ימים. ולפי פירושינו זה מצאנו נחת רוח במאמר אחד שאמרו ז''ל (שבת קיט:) כל המקדש וכו' ואומר ויכלו וגו' כאילו נעשה שותף להקב''ה במעשה בראשית ע''כ. ודבריהם רחוקים ודחוקים לפי הנראה מי שמע כזאת שיבא אדם וישתתף בדבר שכבר נגמרה מלאכתו אין אחר מעשה כלום ובמה יעשה שותף. עוד מה היא הפעולה הגדולה הזאת שבאמצעותה ישיג השגה זו:
@34 **ועוד** לו יהיה שיהיה מעשה זה גדול עד מאוד מנין להם לומר דבר זה שהוא נעשה שותף ואם לצד הגדלת השכר היה להם להגדיל שכרו לחלק לו ברבים (ישעי' נג) ואורך ימים וגבורה ועושר וכו' ומנין מצאו להאריך לשון לצד עילאה להשתתף עמו במעשה בראשית. ולמה שפירשתי אמת יהגה חכם ודבר ה' בפיהם אמת בטעם צודק כי להיות שהשבת הוא המקיים העולם כל ששת ימים ואחר עבור ששת ימים יבא שבת אחרת ויחייהו ויקיימהו עוד ששת ימים אחרים, ולך לדעת כי מציאות השבת בעולם הוא קיומו שמקיימים אותו כי אם אין מקיימים שבת אין שבת, ותמצא שאמרו ז''ל (שבת קנא:) חלל עליו שבת אחד כדי שישמור שבתות הרבה ואם אין שומר שבת מה זאת עושה. ולזה כל המקדש את השבת וכו' פירוש מקיים ושומר קדושתו באמצעות זה ישנו לשבת ומאמצעותו מתקיים העולם. הראת לדעת כי הוא המקיים העולם ואין לך שותף גדול מזה כדין וכהלכה. ולך לדעת כי מיום ברא אלהים אדם לא חסר העולם דבר המעמיד צדיק יסוד עולם שהוא שומר שבת כי אדם שומר שבת היה ע''ה (ב''ר כב) ואחריו קם שת בנו כי הוא היה צדיק גמור ואחריו כמה צדיקים וכשזה נופל כבר בא השמש שומר שבת מתושלח וכו' נח שם אברהם וכו' ומשם לא פסקה שמירת שבת מישראל ואפילו במצרים היו שומרי שבתות כמאמרם ז''ל (שמו''ר פ''א) ונכון. והגם שכתבנו למעלה בפירוש פסוק ויכלו כי העמדת העולם הוא בחשק הקבלת אור המקיף והישר בנעלמות אין זה מכחיש לדברינו כאן כי זולת השבת אין השגה בעולם להכיר לכסוף ולכלות אל הבורא והבן:
@35 **אלה תולדות וגו'**. כבר רז''ל דרשו (ב''ד פ''א) הכתוב אבל פשוטו של מקרא לא נודע:
@35 **ונראה** כי להיות שקדם והודיע הכתוב כי אמר ה' לנבראים שיעשו גם הם תולדות לשמים לחלוק המים והרבה פרטים כאמור בדבריהם ולארץ אמר גם כן להוציא חיות ולהוציא עצי פירות ועשבים ולמים אמר ישרצו המים וגו' כדי שלא יטעה אדם ויחשוב כי הארץ והשמים מעצמן עשו הפעולה ותוליד המחשבה הלזו תולדות משובשות, לזה בא הכתוב ואמר **אלה תולדות השמים** פירוש תולדות שהוציאו השמים והארץ דבר יום ביומו ככתוב בסדר הימים לא תחשוב כי הם עשו הדברים יש מאין כדרך הבורא יתעלה שמו שברא הכל יש מאין לא כן הוא אלא בהבראם ביום עשות שהוא יום אחד שברא ה' אותם בכח הבריאה שברא ה' בהם ברא שיוציאו מה שגזר עליהם אחר כך כמו שברא באדם כח המוליד בכח אופן הבריאה שהטביע בו הוא היוצר ב''ה הוא הבורא ואין אדם עושה דבר כמו כן השמים והארץ. וטעם שלא הזכיר אלא שמים וארץ ולא הזכיר המים כי הוא כלול בשמים. ושיעור תיבת **בהבראם** כאילו אמר בהם בראם פירוש לתולדות הנזכרים. או תתפרש כשיעור תיבת היליכי (שמות ב) ואמרו ז''ל (שמו''ר פ''א) זה שליכי, וכמו כן יכוין הכתוב אומרו **בהבראם** פירוש באותן האמורים בסמוך כראם ולעולם הוא היוצר הוא הבורא:
@36 **וכל שיח השדה וגו'**. בא להודיע מה שרמז בפסוק ראשון כי הוא הבורא הכל על דרך שפירשתי. ואמר כי הארץ לא הוציאה צמחה עד אשר השקה ה' והוא אומרו **כי לא המטיר** וגו'. גם הודיע כי חית השדה הוא יצירה, כאומרו וייצר ה' וגו' כל חית השדה, אלא שהכין גולם מהאדמה כמו שהכין צורת אדם, והשרצת המים רמזה גם כן באומרו ועוף השמים, וכבר אמרו ז''ל (חולין כז:) כי מהרקק נבראו:
@36 **עוד** יכוין הכתוב לומר בדקדק בכתוב עוד אומר, **ואדם אין**, מה הוא הכונה בהודעה זו. עוד למה חזר לומר **וייצר** וגו' **עפר** וגו' וכבר השמיענו ביום ברא אלהים אדם, ואם בא להשמיענו כי מן העפר בראו למה הוצרך לכפול הודעת הבריאה והיה לו להוסיף שם בהודעת הבריאה ולומר עפר מן האדמה:
@36 **אכן** יתבאר על פי מה שאמרו ז''ל (ב''ר פי''ד) כי אדם הראשון חלתו של עולם ע''כ, מובן מדבריהם כי העולם דין חלה יש בו, ושנו רבותינו בפרק ב' ממסכת חלה וזה לשונם המפריש חלתו קמח וכו' אינה חלה ותנן בפרק ג' גלגל בחיטים וכו' האוכל ממנה חייב מיתה ע''כ. והנה אין מציאות לארץ להוציא ממנה צמחים זולת על ידי השקאת הארץ וזה הוא גלגול בעיסה ומעתה כל צמחי האדמה אסורים קודם שהורמה ממנה חלה שהוא יצירת האדם כי האדמה נתחייבה בחלה וכל זמן שלא הורמה חלתה טבל היא, והוא שאמר הכתוב כאן **וכל שיח השדה טרם יהיה** וגו' **וכל עשב** וגו' **טרם יצמח** כי לא המטיר ביום השלישי לארץ להוציאם אלא הארץ נתעברה מהם במאמרו יתברך אבל לא יצאו והטעם הוא להיות שאדם אין שהוא החלה של הארץ, ואמר התיקון שעשה ה' להוציא הצמחים ואיד יעלה מן הארץ וגלגל את כל עפר העולם כאומרו **והשקה את כל** וגו' **וייצר ה'** וגו' **את האדם עפר** וגו' זו היא הרמת החלה, אחר שנתחייבה כל הארץ בחלה והרים ה' חלה זו הותרה כל הארץ וצמחיה, ואם היה מגלגל במים חלק אחד מהארץ לא היה יוצא מכלל טבל אלא החלק שנתגלגל:
@36 **ויש** לך לדעת כי עפר שממנו נוצר האדם לא עפר של גן עדן אלא של העולם וכמו שדייק הכתוב (ג' כ''ג) לעבוד את האדמה אשר לוקח משם, אבל גן עדן לא הוצרך להרים ממנה חלה ואחר כך יוציא ממנה נטעים כי כולה קודש, ולזה אמר **ויטע ה'** וגו' **גן בעדן מקדם**, פירוש קודם בריאת האדם כאומרם ז''ל (פסחים נד.) והכינה לאדם שהיה עצמו חלה קודש ליהנות מקודש וככהן האוכל בתרומה:
@39 **ויטע ה' וגו'וישם** וגו' **ויצמח** וגו'. טעם שהפסיק בשימת האדם בתוך הודעת נטעי הגן לומר כי בשבילו ברא ה' הגן ולכבודו. וזה הוא שיעור הכתוב **ויטע** וגו' **וישם** פירוש לסיבה זו לשום שם האדם ואחר כך חזר לפרט ענייני הגן ונהרותיו ותועליותיהם וחזר לומר (פסוק טו) **ויקח ה'** וגו' **ויניחהו** וגו' לגלות על מה שפירשנו באומרו וישם שלא נתכוין לומר בה אלא שהאדם היה סיבה לנטע הגן שאם על הודעת הנחת אדם בגן הרי הוא אומר ויקח וגו' ויניחהו. ופסוק ויניחהו לבד לא יספיק להודעה זו שבשביל האדם לו לשמו ברא ה' הגן שאפשר כי ה' בראו לשום בו לאשר ישר בעיניו למשרתיו למלאכיו לרוחות העליונים ובאותו זמן נתרצה שיהיה שם גם האדם ובן יומו נקרא פרוש וגרוש ושלוח ונשאר הגן לשאר ברואיו. לזה הודיע ה' חסדו כי הגן לאדם בראו ועודנו עומד לאדם הידיד לקונו ואין לשום נברא חלק בגן זולת אדם אשר לא פגם דיוקנו וצלמו:
@46 **ויקח וגו'**. לעבדה ולשמרה. משמעות הכתוב יגיד כי הגן צריך לה עובד ושומר והאמת יכחיש זה כי למה יהיה צריך לשומרה אם מהגנבים זה הבאי היא ומה היא העבודה שהיתה צריכה הגן, ואם צריכה עובד אם כן זה לה חמשת אלפים וחמש מאות שנה מי עבדה:
@46 **אכן** יש לך לדעת כי כל הווה אינו אלא דוגמא לרוחניות, וכמו שהאדמה צריכה עבודה והזרעה והגשמה להוציא מזון האדם, גם שמירה מדברים המפסידים והמריעים לצומח, כמו כן גן עדן אשר היא היום אדמת הנפשות לבד כי הגופות נגשמו גם היא צריכה עבודה ושמירה כפי רוחניותה. הגשמה המיוחדת לה היא עסק התורה כמו שאמר הכתוב (דברים לב) יערוף כמטר לקחי תזל כטל אמרתי, והזרעים הם מצות עשה אשר יעשה אותם האדם כרמוז בדברי הנביא (הושע י) זרעו לכם וגומר, והגם שלא נזכר בדברי הנביא אלא הצדקה, לא על פרט הצדקה לבד הוא אומר אלא על כל פרטי הצדקות הוא אומר, וכן הובא בדבריהם ז''ל (מדרש תהלים קיד) שכל מצות שיעשה האדם הקב''ה זורעה וכו', והעבודה היא התעסקות גדול והסתכלות נמרץ בתורה שהוא עיקר מצוותה, והשמירה גם כן לבל יפרוץ גדריה ולבל יפסיד צמחיה, והיא שמירת מצות לא תעשה אשר צריך האדם לשמור לבל עבור עליהם כי הם המפסידים כל דבר טוב. והוא אומרם ז''ל (סוטה כא.) עבירה מכבה מצוה, והגם שאמרו ואין עבירה מכבה תורה, אין כוונתם לומר שמעשה הרע לא יפסיד התורה כל עיקר, אלא לומד שאין כח בעבירה אחת לכבות התורה ולעולם כי ירבה להשחית תשחת תורתו וידעך נרה ותהפך שלייתו על פניו רחמנא ליצלן:
@46 **ומעתה** יוצדק לומר על גן עדן לעבדה ולשמרה. והנה בימים ההם כשהניח ה' האדם בגן עדן היה מביט וצופה בפעולות צדיק לחיים במעשיו מה שהיה פועל בגן עדן, אך אחר אשר נגרש האדם הושלל ממנו ראות הדבר אבל המעשה נפש עמל עמלה לו כי הרוחניות לא ימנענה ההרחקה והפעולה נעשית, אשרי המחכה ויגיע בעולם הזה לאכול מפרי דרכו שהוא מזון הנשמה בגן עדן. שוב בא לידי מאמר חז''ל וז''ל לעבדה אלו מצות עשה ולשמרה אלו מצות לא תעשה, וכוונתם ז''ל על דרך שביארנו:
@47 **ויצו ה' וגו'**. טעם אומרו **לאמר** וכפל **אכול תאכל** וכפל מות וגו', יכוין על חוה שצוהו לאמר המצוה לחוה אכול אתה תאכל בת זוגך מות אתה תמות גם היא אם תעבור, ישנה באזהרה וישנה בעונש:
@47 **ומצאתי** שאמרו ז''ל (ש''ר פכ''ח) וז''ל א''ר תחליפא אמר הקב''ה אם נקדים לאנשים כמו שהקדמתי לאדם הראשון ואחר כך נצטוית חוה ועמדה וקלקלה וכו' ע''כ, דקדק לומר נצטוית ולא אמר צויתי לחוה לרמוז דברינו כי לאדם צוה לאמר לה:
@47 **עוד** ירמוז בכפל **אכול תאכל מות תמות**, לומר כי המתנה נתונה לו ולכל הבאים ממנו שהם כל זרעו עד סוף כל הדורות לאכול מהגן ואם וגו' מות וגו' פי' מות הוא וימותו כל הבאים ממנו עמו, כמו שכן היה שנקנסה מיתה על כל הנבראים עד אשר תאבד זוהמא שנדבקה אז ובלע המות לנצח:
@47 **וטעם** אומרו **ויצו ה' אלהים** ולא הספיק באומרו ויצו ה' או ויצו אלהים, כאן רמז רחמים ודין אם יטיב יקיפהו ברחמים ואם לא משפט למולו:
@49 **ויאמר ה' וגו' לא טוב וגו'**. קשה הלא כבר ביום ברא אלהים אדם זכר ונקבה ברא אותם, עוד קשה אומרו סמוך לו **אעשה לו עזר כנגדו** וגומר **ויצר** וגומר **כל חית השדה**, שנראה שרצה לזווג לו חית השדה וזה פלא לזווג אדם ובהמה, ועוד שיסיר נקבת בהמה או חיה מבן זוגה ולזווגה עם האדם, עליונים למטה ותחתונים למעלה, עוד קשה אומרו **ויפל ה' תרדמה** וגו', וכי לא היה ה' יכול לברוא לו בת זוגו עפר מן האדמה. מלבד מה שהקשינו שמצינו לו שברא לו בת זוגו ביום הבראו וכמו שהעיד הכתוב אחר כן זכר ונקבה בראם וגו' ביום הבראם ורז''ל אמרו דרשות רבות וצריכין פותר אבל פשט הכתוב לא מצאנוהו:
@49 **ונראה** לפי מה שקדם מדברי רז''ל (עירובין יח) כי אדם וחוה דו פרצופין נבראו למאן דאמר פרצוף, ולמאן דאמר זנב, כדאיתא במס' שבת, וכפי זה זאת האשה וזה בניינה כי מתחלה בראה דבוקה עמו ממש למ''ד כסברתו ולמ''ד כסברתו. ובסדר זה ישנם גם כן בהכנת המוליד דהלא תמצא שאמר ה' להם (א' כח) פרו ורבו וגו' קודם הנסירה הא למדת שהכינם ה' להוליד גם בהיותם בסדר זה וזאת האשה אשר נסר ה' ולקחה ממקום דביקתה אשר בראה ביום הבראם. גם דבר ידוע הוא כי כל משכיל וחכם המתחיל להביט אמרי נועם ה' תורת ה' מעת יאורו עיניו ידע גודל הפלגת מדת טובו יתברך אשר הגדיל להתחכם להכין הפלגת הטוב והכנתו, ומעתה יש לנו לחקור זאת סיבת חטא האדם ומה שנתגלגל לו ולכללות הנבראים, ומצאנוה כי היא האשה היתה סיבה לכל הפסד וכליון העולם ששלט בה הנחש ונצח דעתה ולא היה עמה האדם, כנשמע מהכתוב, ואמרו ז''ל (ב''ר פי''ט) כי היה האדם ישן או למ''ד שהיה עובר בעולם וכו' ומצא נחש לחוה בפני עצמה והסיתה. ומעתה יהיה פה ולשון לנבראים לומר יד ה' עשתה זאת במה שנסרה ולא הניח תכלית הבריאה כסדר הראשון ולא היה מקום לנחש להסית האשה בפני עצמה, אשר על כן נתחכם ה' וכתב קודם לקיחת הצלע מהאדם טעם הדבר שכוונת ה' בדבר היתה להטיב להאדם, אלהים חשבה לטובה כמדת אלהינו. וזה הוא שיעור ומשמעות הכתובים, אחר אשר הודיע אותנו בבריאת יום ו' כי ברא האדם זכר ונקבה דו פרצופין או זנב ראה ה' כי לא נכון שיהיה האדם בד אחד, והגם שהיתה לו בת זוג אף על פי כן אחד היה ואינו אלא לבדו. והמשל בזה אם ירצה הוא ללכת לעשות חפציו תלך עמו גם אם תלך האשה לשמש בעלה ילך עמה גם כן ונמצא שהוא בד אחד. ונמלך ה' כי העזר תהיה עזר כנגדו, פירוש בנין נפרד למולו לשמשו ולהכנתו כי לבחינת ההולדה והזיווג כבר הוטבע בסדר הראשון כי מצינו לו שצוה להם פרו ורבו קודם הנסירה. ומעתה אם לזה היתה סיבת קיחת הנקבה מצד האדם ישנו מציאות אחר שיגזור ה' על אחד מהנבראים ויהיה לו לעזר להועיל ותשאר האשה במקום יצירתה. לזה אמר הכתוב (יט) **וייצר** וגו' **כל חית השדה** וגו' **ויבא אל האדם לראות מה יקרא לו**, כי בבחינת קריאת השם תוכר בחינת המזג ובאמצעות ההכרה יוכל לברר מציאות העזר הישנה. והודיע הכתוב כי לא מצא עזר והוכרח לקלוע הנקבה מצדו ולעשותה כנגדו, והכוונה היא לטובת האדם ואם אחר כך יצא מה שיצא והיה זה סיבה להמצאת האשה ביחוד מבלעדי אישה והכישה נחש אין מקום לומר למה עשה ה' ככה כי אלקים חשבה לטובה וישרים דרכי ה' וצדיקים ילכו בם וגו'. וזה הוא שיעור הכתובים להיות שרצה הכתוב להודיע חטא האדם כי הוא זה סיבה לגזרת המות והוא הסובב, והוא מה שאמר הכתוב (כה) ויהיו שניהם וגו' קדם להודיע הכנת הסיבה שהיא לצד היות האשה מופרדת מגוף אדם והוא אומרו **ויקח אחת מצלעותיו** פירוש נסירת האשה מהאדם. ולהיות שתקשה לומר ולמה היתה הכנה זו ' לחטא, ולא היה לו לה' לנסור אותה וקנתה לה מקומה ואז לא היה חטא בעולם, לזה קדם לומר כי היה לצד ההכרח, והוא אומרו **ויאמר** וגו' **לא טוב היות האדם לבדו** וגו', והגם שבקש העזר מהנבראים דכתיב ויבא אל האדם וגו' לא מצא עזר לאדם מהם והוכרח לנסור הנקבה ונחה דעת אדם בה כנגדו ולא טמונה מאחוריו כי בזה תשא עול סובלו לנוח הוא במקומו ואותה ישלח להכין ולעשות צרכיו:
@49 **ולפי** דרכינו יש טעם נכון בחקירה אחת למה ה' נמלך ממחשבתו ראשונה שברא האדם ובת זוגו עמו וחזר ונסרה. כי הכוונה היא להודיע כי מעשה ה' טוב הוא לכל ואלהים חשבה לטובה וברא יחד זכר ונקבה אלא דלצד הנאת האדם לסדר הכנתו הפרידם מכל הנבראים אין נשתוין אליו ואין מציאות לברוא לו אדם אחר להכנתו כי יש טעמים רבים ונכבדים לבלתי עשות ה' ב' אדם כמאמרם ז''ל והבן. נמצאת אומר כי כל סדר האמור בפרשה זו בבקשת העזר ושלילתו והמצאתו אינו אלא לצד עשות הנקבה נפרדת מהזכר כי טוב הב' מהא', אבל לענין הזיוג הכנת פריה ורביה כבר בראו ה' ביום ו' ובראם לפרות ולרבות, ואין מניעה לזה לצד שאין פנים בפנים כי הכינם ה' להרכבה גם בסדר שהיו בה אחור ואחור שיריק הזכר הזרע דרך מקום אשר בו הנוצר. ויש לנו לחקור זאת לאיזה טעם ברא ה' האשה בגוף האדם ממש ולא בראה בריה בפני עצמה מן העפר כמו שברא הזכר. ונראה כי בזה גילה דעתו יתברך כי יש הפרש בין הכנת זיווג האנושי מזיווג הבהמי כי זיווג הבהמי פועל פעולת ההזרעה בכל נקבה אשר תזדמן לפניו, והגם שאמר הכתוב בסוג זה גם כן זכר ונקבה לא שיתחייב כל זכר להכיר נקבתו כל שממינו היא כל אשר יזדמן לפניו ממינו הרי הוא רשאי ואין רישום וייחוד לנקבת זכר בבהמי לומר זו פרתו של שור זה וזו פרתו וגו' מה שאין כן האדם שלא מלבד שמובדל בבחינת המין אלא גם מובדל בפרטי המין כי כל אחד יש לו בת זוגו בפני עצמו, ולזה נתחכם ה' לבנות בת זוגו של האדם מעצמיו לומר כי זו בשר מבשרו. ולזה כשהזהיר על העריות רשם כינוי העריות אל הזכרים כאומרו (ויקרא י''ח) ערות אביך ערות אחי אביך וגו' הרי שהגם שאינו מצווה אלא על הנקבות מייחד הדבר אל הזכרים והבן:
@56 **ויהיו שניהם ערומים וגו'**. טעם הדבר להיותם מקודם מושללים מבחינת הרע וכללותם קודש היו דומות בהם פנים שלמטה כפנים של מעלה, כי בחינת הרע שנדבקה באדם היא אשר תבדיל בחלק שלמטה באדם כי שם קנה הרע מקומו וזה לך האות אות ברית קודש אשר תסובבהו הקליפה בערלה וצוה ה' לכרות אותה הנך רואה כי שם הרגיעה שידה. ותמצא כי כל תאוות הרשעים הנואפים תבער במקום ההוא, וגזר ה' לכסות התיעוב. ותמצא שאסרו חז''ל (נדה יג.) להניח ידו וכו' ואמרו (שבת קח:) יד לאמה תקצץ כי יבעיר אש זרה ותאכלהו אש לא נופח, וזה לא היה קודם לכן. ויש לנו לבחון הדבר ממה שראינו באברהם אבינו עליו השלום שאמר (בראשית כד) לעבד שים נא ידך וגו'. הטעם אמרו רז''ל (זוהר) כי אברהם אבינו עליו השלום לא היה כל כך בהשוואה עם כל הנבראים בבחינה זו כי הרחיק התיעוב והגם שלא הורחק בהחלט והמיתה מוכחת אבל על כל פנים לא היה התיעוב כל כך וברית קודש שבבשרו תמה היתה נקיה היתה. ולדרך זה ידוייק הכתוב על נכון אומרו **ולא יתבוששו** שהיה לו לומר ולא נתביישו, שנתכוון לומר שהגם שהיו ערומים לא יתבוששו פירוש התורה מגדת עליהם שאין להם דבר שיתביישו ממנו והבן. והגיד הכתוב מי גרם בחינת הערוה להבדיל באדם חציו של מטה ואמר והנחש וגו' ומזה נתגלגלו הדברים וכו':
@57 **והנחש היה ערום וגו'**. צריך לדעת לאיזה סיבה הודיענו הכתוב כי הנחש היה ערום:
@57 **עוד** נתתי לבי לתור הערמה אשר הערים בענין ולא ראיתי אלא דבר רשעות וחכמה נפלאת ממנו:
@57 **אכן** יתבאר הענין בהבין כוונת דבריו באומרו **אף כי אמר** וגו' שנראים דבריו כדברי הוללות אשר על כן קדם הכתוב להודיע כי הנחש היה ערום כדי להתבונן באמריו **שבהם** השיג להסית ולהדיח אשה יראת ה':
@57 **והנה** בסדר דבריו נתכוון לומר ג' עניינים ובהם השיג כוונתו. א', בא להודיע אותה ידיעה אחת כי כיון שלא השיגה לאכול מעץ הדעת יהיה הדבר בעיניה כאלו אינה אוכלת מכל עץ הגן, הכוונה בזה כי כולן כאין נגדו והיו כלא היו לגודל מעלתו וחשיבותו וכו', והוא אומרו **אף כי אמר** וגו', פירוש יהיה בעיניך כאלו נצטוית על הכל, נתכוון בזה להגדיל חשקה בו ולהבזות כל תאוותיה בכל עצי הגן. וזו היא המדה אשר מתנהג בה היצר הרע עם הנשמעים לו שיסיר מהם תאוות ההיתר וימאסנו בעיניהם ויגדיל בעיניהם תאוות האיסור עד אין כמוהו. ב', נתכוון סדר פיתוי אחר והוא כי מורה הוראה הוא לה, והוא על דרך אומרם ז''ל (בראשית יח) כי עץ הדעת הוא שנטע ה' תחלה בגן וממנו שתל כל האילנות שבגן, ולזה בא המסית ואמר שהגם שלא אסר ה' אלא עץ הדעת תתחייב לומר שאף כל שאר העצים שבגן אסר כי דן בהם דין הברכה, ותנן בפרק א' ממסכת ערלה הבריכה שנה אחר שנה מונה לה משנה שנפסק ע''כ. והכוונה בזה כי קודם שנפסק הגם שהם מושרשות בארץ אף על פי כן עיקר יניקתם מהאילן והיו כענפי האילן הזקן, וכן פירשו רמב''ם ור''ש. והוא שטען המסית באומרו **אף כי אמר** וגו' פירוש כי אם תקבל עליה לקיים דבר זה צריכה היא להיבדל מהכל לצד שכל עצי הגן עודנם יונקות מעץ הדעת, בטוענו, כי מוברכים הם ועדיין לא נפסקו כי זמן מועט היה מזמן שנטע ה' הגן לעת צוותו עליו. ג', נתכוון באומרו **אף** וגו', להיות, כי חוה לא נצטוית מפי הבורא אלא מפי אדם וכמו שפירשנו במקומו לזה בא המסית ואמר לה הודעה אחת כי מצות ה' עליה היא שלא תאכל מכל עץ הגן כי הוא עד בדבר שכן צוה ה' עליה. וכוונת המסית ב מחשבות לענ ן זה לרעה, הא, תאמין דבריו ותאסור הכל ואז יכנס בטענת מניעת האפשריות ויש לו מבוא להכנם בו להסית. והב' נתכוון כדי שתהיה עדות אדם שצוה לה על עץ הדעת לבד עדות מוכחשת, והיא סברת בית שמאי בפרק ד' ממסכת עדיות, מי שהיו ב' כיתי עדים מעידות אותו אלו מעידות שנדר ב' ואלו מעידות שנדר ה' בית שמאי אומרים נחלקה העדות ואין כאן נזירות ובית הלל אומרים יש בכלל ה' ב', ע''כ. ובסנהדרין (לא.) העמידו מחלוקת בית שמאי ובית הלל בכת אחת, פירוש, א' מהב' אמר ה' ואחד אמר ב' וכו'. ומעתה חשב המסית כיון שלא היו אלא ב', אדם אמר לא אסר אלא עץ הדעת, והמסית אמר הכל אסר, נחלקה העדות. ואחר שכתבתי זה מצאתי מאמר א' בתקוני הזוהר תיקון נ''ט שמסכים לפירושינו, שכתב וזה לשונו, וחויא בישא אעבר הכא על לא תענה ברעך עד שקר דסהיד שקרא שאמר אף כי אמר אלהים וגו' ע''כ. וזו היא מדתו לשקר ולהוליד בלבב אנוש אמונות ודעות כוזבות רחמנא ליצלן, ולפעמים יתכוון להפליג ולהגדיל עבירות בלב אדם וישוב לומר לו כי הוא מהנמנע במושג ואין לך ערום בעולם כזה:
@57 **וטעם** שעשה ה' ככה, להיות שכל מחשבת ה' הוא לצד השגת טוב המופלא והוא תלוי בבחינת עבודה זו לזה הגדיל בחינת ערמתו ויכלתו ולפי הצער שיסבול אדם ויתחכם להנצל ממנו יעלה במעלות:
@57 **ויאמר אל האשה וגו'**. פירוש בציפצוף אשר ידברו בו הבעלי חיים בלתי מדברים, ואז היו מכירים כל ציפצופי וכו' ואפילו שיחת הדומם. כי כל מה שברא ה' יש לו כפי בחינתו דיבור לטעם אשר ישבח את קונו כאומרו (משלי טז) כל פעל ה' למענהו, וצא ולמד מפרקי שירה. ומצאנו לגדולי ישראל שהיו מכירים בכל צפצוף ושיחה כאומרם ז''ל (סוכה כח.) אמרו עליו על רבן יוחנן בן זכאי עליו השלום וכו' ומכל שכן אדם הראשון יציר כפיו יתברך:
@58 **ותאמר האשה וגו'**. נתחכמה להשיב לכל הנשמע מדבריו כפי מה שפירשנו כי ג' טענות נתכוון לומר, והשיבתו, כנגד מה שנשמע בדבריו א' שהכל אסור, או לטענת שכל עצי הגן הם ענפי האילן ההוא מוברכים ועודנם יונקות מעץ הדעת, או לטענת שהוא העד ששמע כי הכל אסר הבורא, אמרה לא כן הוא מכל עץ הגן נאכל כי ה' שאסר עץ הדעת הוא התיר שאר אילנות ומה בכך אם הם מוברכות ממנו, בשלמא אם לא היה ה' מתיר בפירוש כל עצי הגן אז יש מקום לצדד כדבריך מה שאין כן אחר שה' התיר בפירוש כל עצי הגן מה מקום לנו לאסור דבר שהותר מפי הבורא. גם אין לשמוע לעדותו כי עדותו מוכחשת היא אצלה מדברי בעלה, ותועיל הכחשת העדויות לבל תאסור עצי הגן כי עדות מוחלקת היא אבל לא תועיל להכחיש כל העדות להתיר הכל כי בכלל כל שאומר הנחש ישנו לעץ הדעת וכדעת בית הלל:
@58 **וכנגד** מה שנשמע מדבריו בהפלגת שבח האילן, אמרה אדרבה, לצד פחיתותו אסרו הבורא, והוא אומרו **פן תמותון** כי יש בו בחינת מות, והאלהים אמר לנו לא תאכלו וגו' פן תמותון. ולהשכילך במכוון יש לך לדעת כי כל אשר יצוה ה' עמו לא צוה ה' דבר לצד ההורמנא והנקמה אלא הכל לסיבת הרחקת הנזק והקרבת התועלת. והנך רואה כמה נטיעות נטע ה' וכמה עניינים מופלאים ברא בעולם והכל נתנו ליציר כפיו, והם דברי חוה שדנה כי לא מנעה ה' מעץ הדעת אם לא שהוא חלק המזיק, ויפה דנה והוא אומרה מכל עץ הגן נאכל, פירוש, הרי זה מגיד כי חפץ ה' להטיב לצד הרצון, ומזה אתה למד כי מה שמנענו מזה הוא לצד הרחקת הנזק. והוסיפה לומר **ולא תגעו בו** הגם שלא נאמר בדברי ה', חשבה כיון שהמניעה היא לצד שלא תסתכן מעתה כל מה שתוסיף להרחיק מבחינת המזיק כן ראוי לעשות. ואפשר כי האדם כשצוה לה על העץ בסדר זה אמר לה להגרלת ההרחקה כשתדע כי עץ זה הוא סם הממית תפליג בהרחקה:
@58 **עוד** נתכוונה לומר לו יהיה שכדבריו כן הוא כי הוא המשובח מכל עצי הגן כי מה בכך אם האילן משובח הוא מכולן הרי האלהים אמר כי אם נאכל ממנו נתחייב מות ויש לנו לחוש לעצמנו. ואומרה ולא תגעו בו אפשר שחששה לשומן הפירות ובנגיעה יהנה הגוף כאומרם (שבת פ''ו) מנין לסיכה שהיא וכו' והרי היא נהנית ממנו והיא בכלל אכילה כאומרם בש''ס (פסחים כא:) כל מקום שנאמר לא תאכלו וגו' אחד איסור אכילה וכו'. ומכוון הדברים כי הגם שיש בו מעלה רמה כדבריו ואין רומה לו הלא רגליו יורדות מות בזה הוא נשפל מכל עצי הגן:
@58 **ומעתה** לא נשאר מקום לטעון עוד קום אכול, וממה נפשך מניעה זו שמנע ה' אותנו מעץ זה לא תמנע מחלוקה או לצד הרחקה מהנזק או לצד לקבל עלינו גזירת מלך ולשמוע בקולו כי זה מנימוסי המלוכה, ולשני הטעמים יש יראת מות בדבר, ועלינו להתרחק:
@60 **ויאמר הנחש וגו'**. כפל לומר **לא מות תמותון** נתכוון לשלול ב' מיתות שרמזה היא בדבריה בין לצד שהעץ עצמו הוא הממית ויראה לאכול סם המות בין לצד היראה פן יפגענה ה' בדבר אמר לא מות תמותון לא מיתה טבעית לא מיתה שפטיית. ומעתה חלה הקושיא אם כן למה יצו ה' שלא לאכול וכמו שפירשתי בדברי חוה. לזה בא ונתן טעם חדש ושת בשמים פיו כי טעם שמנעם הוא לבל ישוו אליו כי ביום אכלכם וגו' יהיו כאלהים. והנה הרשע מצא מקום לומר כדברים האלה להיות שהוא קדם לבריאת אדם וחוה מצא מקום לומר שיודע דבר שלא ידעו הבאים אחריו. גם להיותו מושלל מכניסת גן עדן מצא מקום לומר שלא ניתן רשות ליכנס לגן אלא להם שאינם יודעים סוד הדבר ואסר להם העץ לא כן הוא לצד היותו יודע סוד הענין לא נתנו ה' ליכנס שם. ומעתה לפי הדברים ההם אחר שיאכלו אין פחד אלהים כי יהיו כמותו ולא ישלוט בהם להמיתם, ובזה נעץ ציפורן עבודה זרה. והלא לך לדעת כי עבודה זרה דנים בה גם על המחשבה (קידושין מ):
@60 **עוד** ירצה באומרו **לא מות תמותון**, לפי דבריהם ז''ל (ב''ר פי''ט) שדחפה והוכיח שלא מתה בנגיעה, לזה כפל הרשע לומר כשם שלא מתה בנגיעה שאמרה, גם לא תמות באכילה. והנה הוכחה זו ישנה לא' מהב' טעמים שאמרה האשה כמו שפירשתי למעלה שהמיחוש הוא שהעץ מצד עצמו ממית ישנה להבחנה זו שאם העץ ממית בנגיעה הרי נגעה ולא מתה, אבל למה שנתכונה לומר גם כן כי יראה היא מאלהים המצווה אותה פן יפגענה אין הוכחה ממה שלא מתה בנגיעה כי עדיין ישנה בעונש אשר גזר עליה, וחוזרים אנו לטעם שפירשנו למעלה:
@60 **ואם** תאמר למה יברא ה' בריה רעה כזו לתקלה, דע כי בריה זו כל מה שהפליא ה' בגודל בחינתה כן גודל בחינת השגת הנפש בעולם העליון כי לפי התעצמות הצריך לאדם לנצחון כן יטול שכרו כמאמרם ז''ל (אבות פ''ה) לפום צערא אגרא ואם היה מגביל שיעור כח המסית בשיעור מועט אין מקום לרוצה להשיג השגה גדולה להשיגה כי אין השגה זולת אמצעות נצחון המסית. וצא ולמד מהאמור בספר זוה''ק (תרומה קסג.) במשל בן מלך אשר ציוהו אביו לבל קרוב להזונה ואת הזונה צוה להסיתו לבחון בן יכבד אב יעוין שם. ומעתה הפליא ה' להתחסד עם אוהביו להכין להם דבר שבאמצעותו ישיגו עלות במעלות חיים הנצחיים, אשרי העם שככה לו:
@62 **ותרא האשה כי טוב וגו'**. קשה איך יוצדק להכיר הרגשת המאכל על ידי ראיה. עוד קשה למה הקדים הרגשת הפה להרגשת העין הלא העין תרגיש בראות קודם שתבחין חוש הטועם, ואם כן קודם שאכלה קדם ידיעת תאוה לעינים ומהראוי להקדים לומר כי תאוה לעינים. עוד מנין ידעה שישנו בהשכל. ואם על הצדקת דברי נחש הוא אומר לא היה לו לומר ותרא האשה על דבר שלא ראתה. עוד למה האריך לומר ב' תיבות נותרות תיבת **הוא** ותיבת **העץ** שניה בכתוב. עוד למה אמר תיבת העץ בחלוקה ג' ולא בחלוקה ב':
@62 **אכן** הכתוב יגיד אופן מצודתה של האשה ואיך נתרצית לשמוע למסית. והנה תמצא בסדר דבריה הראשונים אל הנחש דקדקה לומר ומפרי העץ אשר בתוך הגן, הרי זה מגדת דעתה וידיעתה כי לא נאסר לה אלא הפרי עצמו אבל העץ של האילן וענפיו ועליו לא נאסרו. וסברא זו נוכל לומר בה שנולדה לה מא' משני דרכים. או שהאדם בצוותו צוה לה בנוסח זה, או שהגם שאמר סתם עץ הדעת וגו' חשבה בדעתה כי לא יצו האל אלא על הפרי כי העץ אין בו ממש ולא תבא עליו המצוה. וכבר הקדמנו מאמרי קדמונינו (ב''ר פט''ו) כי כל עצי הגן לא היה טעם בעץ זולת עץ הדעת שהיה טעם עצו וטעם פריו שוה. וכאן מודיענו הכתוב כי בדבר המסית לחוה בחנה חוה ושלחה ידה ואכלה מהעץ לא מהפרי, כי חושבת שאין איסור בדבר לאחד משני הטעמים שכתבנו, ולא חששה לנגיעה כי לא נאסרה הנגיעה אלא בפרי עצמו ולא באילן. או אפשר ששללה בדעתה איסור הנגיעה לפי דבריהם ז''ל (שם פי''ט) שאמרו שדחפה ונגעה ולא מתה החליטה איסור הנגיעה כיון שלא בא בפירוש בדברי ה'. **ותרא האשה כי טוב העץ** פירוש גוף האילן וענפיו ראתה בהם מדה משונה מכל אילני השדה זו הבחנה ראשונה. ולהיות שטעמה שינוי בעץ נתנה דעתה להסתכל במראית הפרי מה שלא הסתכלה מקודם כשהחליטה בדעתה אכילתו כשראתה השינוי נתנה דעתה וראתה הפרי כי תאוה הוא לעינים, והוא שדקדק הכתוב באומרו **וכי תאוה הוא לעינים**, דקדק לומר תיבת הוא חוזר אל הפרי שאם חוזר אל העץ לא היה צריך לומר הוא אלא וכי תאוה לעינים ומובן שחוזר אל העץ כמו שדקדקנו למעלה. וכשהודיע הבחנת ההשכלה אמר ונחמד העץ להשכיל דקדק לומר העץ להיות כי לא היה בו מאמר הסמוך כי מאמר הסמוך מדבר בפרי ולא נאמר בו אלא הבחנה הניכרת בלא טעימה וחלוקה זו של ההשכלה אינה נבחנת בחוש הראיה אלא באמצעות האכילה לזה דקדק הכתוב לומר **ונחמד העץ** פירוש שאכלה להשכיל שהרגישה בו ההשכלה. ובזה נתאמתו בעיניה דברי השטן שאמר לה טעם שהבדילם ה' מאכילתו הוא לבל יהיו שוים אליו **ותקח מפריו ותאכל** דקדק לומר מפריו כי מעצו כבר אכלה קודם. ובזה נתיישבו כל הכתובים וכל הדקדוקים שדקדקנו על נכון. גם טעם לפעמים מזכיר עץ ולפעמים פרי. וטעם שנתנה לבעלה הוא לצד חיבתו כדי שגם הוא יהיה לאלהים וגו':
@62 **וראיתי** לתת טוב טעם כי אין כל כך אשמה על חוה כי לא חשבה שיש בריה בעולם שבראה ה' להבחין בה אהבת ברואיו שהוא הנחש שנתלבש בו השטן ואם היתה יודעת זה היתה חוששת לו ולא היתה נותנת אוזן לשמוע דבריו כאשר עושים הן היום אנשים צדיקים שאינם מטים אוזן לפיתוייו הגם כי ירבה חלק לשונו והפלגת חשק מעדני מטעמי איסורו וזה הוא לצד שהכירו כי הוא און ומרמה יורד ומסטין עולה ומקטרג, והיא האשה העניה לא עלה בדעתה כי ישנה לבריה זו בעולם לנסותה, ונוסף כי הרגישה בטעימת העץ לצד היותו מותר לפי סברתה וראתה כי משונה הוא לשבח ובהצטרפות דעתה שקלה מאדם, אבל אם היתה יודעת כידיעתינו כי ברא ה' שטן לנסות ידידיו או אם היה לה טעימת העץ באיסור ולא היתה טועמת לא היתה שולחת ידיה לאכול:
@62 **עוד** נראה לתת טעם לחוה שמיהרה לעבור פי ה' שהוא לצד שחשבה שקבלת מצות זו היה בטעות שלא חשבה שכל כך היה העץ ההוא חשוב כשקבלה עליה המצוה. ותמצא כי בנתינת התורה כמה בריתות כרת ה' על התורה עם ישראל הרי זה מגיד כי הוא דבר צורך ולא תספיק המצוה שיכול לחזור בו. ותמצא עוד שאמרו ז''ל (שבת פח.) שקיימו בימי מרדכי מה שכבר קבלו לצד שהיתה השבועה הראשונה באונס שכפה עליהם ההר כגיגית הרי זה מגיד כי צורך בשבועה. ומעתה חוה שלא נשבעה אין עליה חובה. והגם שקבלה ואמירתה לגבוה במקום נדר הוא עם כל זה היא קבלה בטעות. והנה לפניך מה שאמרו ז''ל במסכת נדרים פ''ט (סו.) וזה לשונם קונם יין שאיני טועם שהיין רע למעיים אמרו לו והלא המיושן יפה למעיים הותר וכו' בכל היין וכו' ע''כ. והוא עצמו מציאות שלפנינו שהגם שקבלה עליה הדבר כיון שראתה מה שלא היה בדעתה בעת הקבלה כאומרו ותרא האשה כי טוב העץ וגו':
@62 **ומעתה** נגלה לנו כי ב' סיבות סבבו מכשול האשה הא' הוא בחושבה שלא נאסר להם אלא הפרי ולא העץ אשר לצד זה שלחה ידה וטעמה העץ ונתקיימו לה דברי הנחש, והב' שלא ידעה בשעת הציווי כי העץ הוא מחכים אוכליו שאם היתה יודעת בתחילת המצוה שעל מנת כן הבורא מצוה לה לא היה נשאר מקום למסית אחר שקבלה עליה שלא לאכול אחר שידעה מעלתו:
@62 **והנה** האדון ה' צבאות ידע מה בחשוכא הוא הנחש שעתיד לבוא בטענות אלו ובכסף נבחר לשון צדיק שלל ב' דברים אלו באומרו (ב' י''ז) ומעץ הדעת טוב ורע לא תאכל ממנו, הרי שדקדק לומר ומעץ לאסור אפילו העץ, והודיע גם כן כי הוא מחכים ויש בו דעת הבחנת טוב וכו', ועל מנת כן גזר אומר לבל יאכלו אפילו מהעץ. ובזה אין מקום למסית להסית, אלא שהאדם לא אמר הדברים ככתבן להאשה כמובן מתוך דבריה, כמו שדקדקנו ממה שאמרה לנחש שהאיסור הוא בפרי ולא דקדקה לומר עץ הדעת, גם מאומרו ותרא האשה וגו' ונחמד העץ להשכיל הרי זה מגיד כי לא היתה לה ידיעה מתחילה. וטעם האדם שלא אמר לה לחוה, לא רצה להודיעה כי יש בו מעלה זו שמחכים אוכליו כדי שלא להגדיל בלבה תאותו ולא ידע כי האויב בחדר. גם לא חש לומר לה איסור העץ בחושבו כי אין טעם בעץ לצוותה עליו. והגם שאמר לו ה' ומעץ הדעת, חשב שאין דבר זה בדיוק והכוונה היא על מה שבעץ שהוא הפרי, כי העץ כבר השיג משאר אילנות כי אין בו טעם ולא תבא עליו הצואה. ושגגה זו נולדה משגגת האדמה אשר שינתה עץ הדעת משאר עצי הגן ועיין מה שפירשנו במקומו (א' י''ב) ולזה לקו חוה והאדם והאדמה כי כלם שגו ושל חוה גדול מכלן:
@63 **ותפקחנה עיני וגו'**. לפי מה שפירשנו בפסוק (ב' כ''ה) ויהיו שניהם ערומים שהעון יוליד הרגשת הערוה אשר מצדה יוליד בושת הערום, הוא הדבר שאמר הכתוב ותפקחנה וגו' וכל אחד נתבייש מחברו. עוד ירמוז באומרו **ותפקחנה** על דרך אומרם ז''ל (סוטה ג.) אין אדם עובר עבירה אלא אם כן נסתתמו עיני שכלו, והוא שמיחס הכתוב הסמאון לרשעים כאומרו (ישעי' מב) והעורים הביטו לראות, והוא שהודיע הכתוב כאן באומרו ותפקחנה, פירוש שאחר שעברו העבירה ועבר המסית המכונה במדת חשך שמחשיך עיני האדם תכף ומיד נפקחו עיניהם והרגישו כי ערומים הם פירוש שנפשטו מזהרא דקדושה. וכן יקרה לכל רשע שבגמר מעשה הרע ירגיש כי התעיב ויכלם במעשיו ויאירו עיני שכלו. ולדברי רז''ל (פדר''א פי''ד) שאמרו וזה לשונם לבושו של אדם הראשון עור ציפורן וענן כבוד מכסה עליו יתיישב הכתוב על נכון אומרו **כי ערומים הם** ממלבוש שהיה עליהם:
@64 **וישמעו וגו' לרוח היום**. טעם שהודיע הכתוב סדר מהלכו הוא לומר שבזה ידעו לבחון מקום שיהיו נחבאים מפניו, והוא אומרו **מתהלך לרוח היום**, פירוש לצד מערב הגן והם עמדו באמצע הגן:
@65 **ויאמר לו איכה**. פירוש למה אתה מתחבא ואינך מתראה לפני, והשיב כי ירא לעמוד לפניו לצד ראות עצמו ערום ואסור לעמוד לפני ספר תורה ערום ומכל שכן לפני האדון יתברך. ולפירושינו בפסוק ותפקחנה וגו' שהרגישו בירידתם ובפשעיהם ענה כי נכלם בראות עצמו ערום מזהרא דקדושה, גם לפי מאמרם ז''ל (שם) שנפשט ממלבוש שלבשו המלך, כי אם על היותו ערום ממש הוא אומר, הלא תפר עלה תאנה:
@67 **ויאמר מי הגיד לך וגו'**. פירוש מה נשתנה שעה זו משלפניה שהיית עומד לפני ולא הרגשת בערום עד עתה, דבר זה מעצמך לא תתחדש לך הידיעה זולת על ידי מגיד, והוא אומרו **מי הגיד לך** במה נתחדש בידיעתך דבר זה. ולפי מה שפירשנו כי היתה הכלמתו מהעון או מגריעת המושג לו מהקדושה ומכסות ענן כבוד לא יוצדק לומר מי הגיד לך, אלא טעמו של הבורא הוא לא רצה להבזותו כל כך ודבר אליו בסדר זה מי הגיד לך, כשואל דבר, וישנה לשאלה זו למה שפירש' כי באמצעות אכילה זו הרגישו כי ערומים הם, כי יש לך לדעת כי כל הפירושים שאנו מפרשים כמשמעות הכתובים כלם צודקים:
@67 **המן העץ וגו'**. כאן רמזו כי גם על בחינת העץ צוהו ה':
@68 **ויאמר האדם האשה וגו'**. צריך לדעת מה מענה בלשונו בתשובת האשה וגו' אפילו קל שבקלים לא ישוב תשובה כזה ומכל שכן למלך גדול. ועוד אומרו **מן העץ** שלא היה צריך לומר אלא היא נתנה לי ואוכל ומובן הדבר שעל העץ המוזכר הוא אומר, וכן מצינו שאמרה חוה בתשובתה הנחש השיאני ואוכל ולא הוצרכה לומר מן העץ:
@68 **ונראה** שכוונת האדם היא שלא ידע דבר כי אם האשה הביאה לפניו המזומן ואכל ואינו חייב לשאול על המוגש לפניו דבר זה מנין כי הלא כל הארץ לפניו היא מלאה מעדנים אשר נטע ה'. ודקדק לומר **אשר נתת עמדי** שלא לחייבו לחפש ולדקדק אחריה לדעת המובא לפניו כיון שהאשה הלז נתנה ה' עמו לעזר ולהועיל ואין רע יורד מהשמים ואין לו לבדוק אחריה כי מן הסתם מעשיה נאים. ותמצא שאמרו ז''ל (קידושין עו.) אין בודקין מן המזבח ולמעלה וכו' ע''כ. הרי דכל שהוחזק במקום קדוש חזקת כשרות שלימה עליו ומכל שכן אשה גדולה כזו אשר ברא לו ה' לעזר אינו צריך לחפש אחריה מה נותנת לפניו. ואומרו **מן העץ** פירוש מן העץ הנטוע בגן כי כולה מלאה נטעי ה', וידוייק אומרו **מן העץ** כי לא על העץ המוזכר בדברי ה' הוא אומר אלא על עץ מעצי הגן, ולכשנאמר דעל עץ הדעת הוא אומר אין הכונה שהוא ידע שממנו הביאה לו ואכל אלא אחר שאכל ידע כי ממנו אכל מאמצעות הכרתו בהרגשתו ההשתנות ולעולם בשעת מעשה לא ידע דבר ולא שאל לצד בטחונו באשה שנתן ה' עמו, והוא שטען באומרו אשר נתת עמדי וגו'. עוד אפשר לומר שגם האדם טעה כי לא אסר ה' אלא הפרי ולא העץ והוא אומרו **מן העץ**, ואין זה פירוש נכון מכמה טעמים וראשון עיקר:
@68 **ומעתה** אין ביד אדם עון אלא שוגג, ואפשר שדין אונס יש לו כי לא היה לו מקום לומר לו היה לך לתת לב לבל תחטא, ולא חשד באשה שתאכילהו דבר איסור כיון שניתנה לו מאל עליון. ולזה תמצא שלא קלל ה' לאדם אלא להאדמה. האמת כי שגיונו הוא שלא נשמר בדברו לחוה ולא הזכיר לה אלא הפרי כנשמע מדבריה לנחש שמזה נמשך החטא לחוה, וכמו שפירשנו למ ע לה:
@69 **ויאמר ה' אלהים לאשה וגו'**. טעם שאלה זו היא להתודות על עונה לפני ה' כי בזה היתה ארוכה למחלתה כי אמרה הנחש השיאני וזה הוא וידויה. גם טענה כי שוגגת בדבר לצד פיתוי הנחש. וכבר כתבתי למעלה כי לא ידעה שישנו למסית זה שאם היתה יודעת בו לא היתה נשמעת לו. ואומר' **השיאני** שרמזה לשון נשיאות ראש כי אמר לה שבאמצעות אכילה זו תהיה כאלהים ותתנשא, והודית בשגגתה לפני קונה:
@70 **ויאמר ה' אלהים אל הנחש וגו'**. שלושה דברים גרם בדיבורו. א', שגרם סילוק אור כבודו יתברך שהיה חופף על אדם ואשתו כמו שכתבנו למעלה והוא סוד כתנות אור. ב', גרם שנכרתו אדם וחוה מעולם הזה שלא יחיו לעולם, כעונש הרשום בכתוב (ב' י''ז) כי ביום אכלך ממנו מות תמות. ג' גרם שאפילו בימים אשר הם חיים בעולם לא יתעדנו בעדן אלהים כאמור (פסוק כד) ויגרש את האדם. כנגד שלשתן לקה שלשה, כנגד הפשטת ענן כבוד שהוא בחינת ברוך אמר ה' אליו ארור וגו'. כנגד הכרתת אדם מהעולם הזה נכרתו רגליו (ב''ר פ''כ) שהם בערך אדם בחינת העדר העולם הזה שהוא רגלים של עולם העשיה. כי יש לך לדעת כי אם לא היה אדם אוכל מעץ הדעת היה מצוי בעולם הזה ובעולם העליון כאחת כאדם הדר בבית ובעליה וכשחטא נגשם ואינו יכול לדור בשניהם יחד אלא בעולם הזה בפני עצמו וכשירצה לעלות לעליה צריך השתנות הגשם וזו היא מיתת אדם, לזה נכרתו רגלי נחש. וכנגד מה שגרם לשלול מאדם וחוה התעדנות גן עדן אמר אליו ועפר תאכל וגו' ואמרו ז''ל (יומא עה.) כי כל מה שיאכל לא יטעום אלא טעם עפר. ולפי זה ידוייק על נכון אומרו הקב''ה לנחש בתחילת דבריו כי עשית זאת פירוש כי הקללות שמקללו ה' הם מעשיו שעשה, והם דברינו עצמן והבן:
@71 **ואיבה וגו'**. דן הדיין דין גואל הדם, כי להיות שלכל זרע האשה גרם לו מיתה ירדוף גואל הדם והכה את הרוצח, והוא אומרו **הוא ישופך ראש**, פירוש מה שעשית לו בתחילה כי הוא פתח ברעה. או יאמר ראש על שם ראש ששם תלויים החיים ושם הוא שחיטת מלאך המות. **ואתה תשופנו עקב** על אשר נמשך לך לבסוף מהם שבאו עליו כל הקללות, או יאמר **עקב** שנפסקו עקביו והולך על גחונו:
@71 **ואם** תאמר בשלמא אומרו הוא ישופך ראש יש טעם כי יחם לבב אנוש על אשר עשה הנחש והרוג יהרגנו, אבל הנחש מה שנטל מהקללות הוא עונש על אשר כבר עשהו ומה מקום לשוף עקב. הטעם הוא, להיות כי יש מענה בפי הנחש שלא היה לה לשמוע לדבריו כי דברי הרב ודברי התלמיד דברי מי שומעים (סנהדרין כט.) ולא היה נמשך רע לא לו ולא לה הא למדת שהיא הסובבת, ולצד בחינת טענה זו תהיה לו איבה עמה. ורמז זמן השגת נצחון של כל אחד מהם, ואמר **הוא ישופך** בזמן שיהיה ראש, פירוש שיגדיל מעלתו ויתנשא בבחינת התורה והמצות, **ואתה תשופנו** כשיהיה עקב בירידה. וכן הוא כל זמן שישראל עושים רצונו של מקום נחש כופף ראשו ולהפך בר מינן. עוד ירמוז מעשה של רבי חנינא בן דוסא (ברכות לג.) שנשכו נחש ברגלו ומת הנחש וכפי זה שף אותו ברגלו מראשו של נחש:
@72 **אל האשה אמר וגו'**. נתכוון ה' לומר ג' קללות כנגד ג' דברים האמורים בענין כי טוב העץ וגו' וכי תאוה וגו' ונחמד וגו'. כנגד כי טוב העץ שרצתה להשתעשע ולהתענג הפך רצונו יתברך הרבה עצבונה ואפילו בזמן שמחה בעצב תלדי בנים. וכנגד וכי תאוה וגו' אמר ואל אישך תשוקתך שתתאוה לו תמיד, ויש בזה ב' פרטי קללה הא' היא שתתאוה ואין בידה להשלים מאויה אלא ביד הבעל, ופרט זה נכלל בכלל אומרו והוא ימשל בך. והב' הוא שלא יהיה לה מציאות להשלים תשוקתה ותמצא שתשתנה האשה מאיש בפרט זה כי האיש ישבע בתשוקתו מה שאין כן האשה והבן, וזו קללה גדולה שתמיד חסרה תשוקתה, וזה כנגד מדת תאוה לעינים. וכנגד נחמד וגו' אמר והוא ימשול וגו', היא חשבה להסיר מעליה כח המושל הגדול שתהיה כאלהים וגו' הוסיף לה מושל להכניעה:
@73 **ולאדם אמר וגו'**. צריך לדעת לאיזה ענין מקפיד ה' על שמיעתו לקול אשתו שלא היה לו לומר אלא כי אכלת מן העץ וגו'. עוד למה דקדק לומר **לקול אשתך**. עוד צריך לדעת אומרו תיבת **לאמר**. אכן לפי מה שפירשנו כי אדם לא ידע בעת אוכלו כי עץ הדעת הוא לא יוצדק לומר לו כי אכלת מן העץ וגו', כי הוא לא אכל מן העץ בידיעה אלא בשוגג, לזה אמר אליו ה' **כי שמעת** וגו', פירוש שקבל דברי אשתו ולא בדק אחריה ונמשך לו מזה שאכל מן העץ. ודקדק לומר **לקול** לרמוז שלא בחן בדבריה, אלא להברת דבריה שאמרה לו קח ואכול אכל, והיה לו לשאול מאיזה עץ לקחה. ואומרו **ותאכל מן העץ אשר צויתיך לאמר** כאן רמז החטא ששגג בו, כי הוא צוה לו לאמר לאשה שלא תאכל מן העץ, והוא אומרו העץ אשר צויתיך לאמר, פירוש לומר להאשה, והוא לא אמר להאשה אלא מהפרי כמו שדייקנו דבריה. ואומרו **ארורה האדמה** ולא קלל לאדם כמו שקלל לחוה מטעם האמור בדבריו, כמו שכתבנו, וקלל להאדמה כי היא סיבה, כי הגם שהאדם צוה להאשה על הפרי לבד ולא על העץ עם כל זה לא היה בזה מכשול, אם לא היה השינוי ששנתה האדמה בעץ הדעת והיה עצו כשאר עצי הגן, לא היה סיבה להחטא, כמו שכתבנו למעלה. גם אם היתה עושה כל עצי הגן טעם העץ כטעם הפרי היה האדם נזהר לומר לחוה כי נצטוית גם על העץ והיא גם היא לא היתה שולחת יד בעץ מקודם. גם לא היתה מתפלאת בו בשנותו את טעמו של עץ משאר עצי הגן. לזה קלל ה' להאדמה כי היא היתה סיבה לכל שתוציא מין קללה. ולאדם לא קלל אלא שבאמצעות קללה זו שלם לו ה' מדה כנגד מדה, הוא שמע לאשתו ועשה חפצו בתאוות אכילת דבר איסור גם הוא תמיד בעצבון וגו' ותצמיח לו קוצים וגו'. וכנגד עריבות האכילה אמר לו **ואכלת את עשב השדה**. וכנגד שלא טרח לדעת מנין הובא אליו האוכל אמר **בזעת אפיך** וגו' שלא ישיג אכול במנוחה בלא טורח:
@75 **עד שובך וגו'**. טעם שנתן ב' טעמים **כי ממנה** וגו' **כי עפר** וגו'. להיות שטעם ממנה לוקחת אינו טעם מספיק לשוב אל האדמה כי הלא קודם שחטא גם כן היה בבחינה זו ולא נגזר עליו לשוב למקום שממנו לוקח לזה נתן טעם ב' באומרו כי עפר אתה וגו'. הכוונה בזה כי אם היה ניצול מהחטא בשכר קיום מצות ה' היה ה' מגביר בו צד הרוחניות ויהיה גופו מזדכך ויתהפך החומר ויעשה צורה בהתגברות חלק הרוחני, מה שאין כן אחר שחטא גרם ב' דברים הפליג חלק החומר שבו והגשימו והוחלט ממנו התהפכותו לצורה, גם הוחשך מאור הרוחני שבו ואין בו כח להאיר לבחינת החומר לעשותו צורה, והוא אומרו, כי, פירוש טעם שאני אומר לך עתה שתשוב אל האדמה שלוקחת ממנה ולא מקודם לזה **כי עפר אתה**, פירוש העמדת עצמך במדת עפר שהוגשמת מצד מעשיך שלא שמרת המצוה שבאמצעותה היה הזיכוך, וכיון שכן, כי כל מקור יקו למקורו ושוב ישוכ אליו והוא מקור גולמו הוא מן האדמה לוקח. וטעם אומרו **ואל עפר תשוב** נתכוין עוד לומר כי לא מלבד שישוב אל האדמה אלא שיהיה נרקב גופו ויעשה הוא עצמו עפר. וכן העמידו פירוש הפסוק במסכת שבת (קנב.) במעשה דהנהו קפולאי דר''נ:
@76 **ויקרא האדם שם וגו'**. יש לתת לב למה לא קרא לה שם בשעה ראשונה קודם כל מעשה אשר נעשה. דע כי זאת האשה כבר נתעלית לשבח וקרא לה ה' שם יחד עם בעלה כאומרו ויקרא את שמם אדם שם לתהלה ולתפארת כי שם זה אדם הוא שם מעולה, וכמאמר הנביא (יחזקאל לד) אדם אתם ואמרו ז''ל (ב''מ קיד:) אתם קרויים אדם וכו':
@76 **ומעתה** אין מקום לאדם לקרות שם לחוה, מה שאין כן אחר מעשה ששמעה לדברי מסית והזידה בעץ הדעת ירדה מבחינתה וחסרה שם המעולה. וכן מדה זו בעולם שכל שיזיד אדם יחסר שמו כאומרו (משלי י) ושם רשעים ירקב רחמנא ליצלן, לזה בא האדם וקרא לה שם על מעשיה שהיתה אם כל חי. והגם שגם שאדם חטא כבר כתבתי למעלה ששוגג היה בדבר:
@76 **ועוד** גם לו הוכרה ירידה לפי שעה. שקרא לו הכתוב כאן האדם ג' או ד' פעמים. ויש לך לדעת כי בחינת האדם היא פחותה מבחינת שם אדם כאמור במסכת עבודה זרה (ג.) וזה לשונם אמר ר''י (הגי' בגמ' ר''מ אולם התוס' בסנהד' נט. כת' וי''ם דג' ר' ירמיה, הגה) אשר יעשה אותם האדם וגו' כהנים ולוים לא נאמר וכו' אפי' גוי העוסק בתורה וכו' והקשו רש''י ותוספות מאמר זה עם מאמר רבי שמעון בר יוחאי שאמר אתם קרויים אדם וכו' ותרצו התוספות שיש הפרש ומעלה בין אדם להאדם כי אדם הוא הגדול והמשובח וכו'. והגם שרש''י ז''ל כתב (סנהד' נט.) שחולקים התנאים עם כל זה דברי התוספות עיקר כי מצינו בפירוש בדברי רשב''י שמחלק כדברי התוספות. וטעם הדבר הוא כי אדם הוא בחשבונו מ''ה ושמו של הקב''ה הוי''ה במילוי אלפי''ן יעלה כן ובתוספת הה''א תאבד הכוונה הרמוזה, ולזה קרא לו האדם אחר שחטא אבל לא נשאר בירידה זו שמצינו לו שחזר ה' וקראו אדם דכתיב וידע אדם עוד את אשתו וחזר למעלתו כי חטאו שוגג הוא:
@76 **עוד** יש לומר טעם קריאת שם אחר כל המעשה. וקודם יש להעיר למה יתיחסו אליה החיים ולא יתיחסו אל האדם כי גם הוא אב כל חי. עוד יש להעיר כי לטעם האמור היה צריך לקרותה חיה ולא חוה. אכן הכוונה היא להיות שנתחדשו בה ב' דברים, הא', ששמעה דברי המסית קרא אותה על שמו והוא אומרו **חוה** מלשון חויא שהוא הנחש, וכמו כן הובא בספר הזוהר (ז''ח בראשית י''ט), והב' שנגזר עליה לילד בעצב לזה קרא לה חוה ולא קראה חויא לרמוז כי היא היתה אם כל חי כיון שהיא סובלת העצבון של הריון ושל לידה לה יאתה להתיחם אם כל חי ולא לאדם. ולא אמר הכתוב אלא טעם שהוא בלתי מוחש במשמעות השם כי רמז החויא ניכר הוא בשם. גם סמך הדבר למעשה הנחש יגיד הדבר:
@78 **ויאמר ה' וגו' הן האדם וגו'**. יש להעיר למה לא חש האל לצוות להאדם על עץ החיים לבל יקדים ויאכל ממנו וחי לעולם קודם שיאכל מעץ הדעת:
@78 **עוד** אומרו תיבת **היה** שהיה צריך לומר הוא. עוד לא היה צריך לומר אלא הן האדם כאחד ממנו. עוד איך יוצדק לדמותו לאלהים לצד שיודע טוב ורע. עוד איך יוצדק לומר תיבת ממנו ח''ו שמראה שיש למעלה כדמות, והיה צריך לומר כאחד מכם או כאלהים:
@78 **אכן** להיות שקדם ה' וציוה לאדם על עץ הדעת לא חש ה' להאדם שיאכל מעץ החיים בין מצדו בין מצד המסית, בין מצדו כי הוא מושלל מההכרה והידיעה לכקש תחבולות לעלות ברומי הצלחות גופיות. בין לצד המסית כי המסית מטבעו שלא יסית להאדם על הדבר שיש לו בו הנאה וזכות ופשיטא שלא יסיתהו לאכול מעץ החיים, ואם היה ה' מצוהו על עץ החיים עם עץ הדעת היה המסית מתגרה בו לאכול מעץ החיים לצד ביטול המצוה ואפשר שהיה מוצא מקום להסית גם לאדם עצמו, לזה נתחכם ה' לבל צוותו על זה שבזה לא יתגרה בו מסית, וכאשר אכל מעץ הדעת וישנו בהכרת דבר שיאות לו נכנס בגדר ספק שמא ישלח ידו לאכול לחיות לעולם. ולחששא זו דיבר ה' דבר חכמה וזו היא שיעור דבריו הן האדם היה כאחד פירוש שה' בראו כאחד פירוש כאחדות אחד המוכרת בעולם שהוא אחדותו יתברך כאומרו נעשה אדם בצלמינו כדמותינו והשליטו בתחתונים כאומרו וירדו וגו', ויצתה פעולה זו **ממנו** פירוש מהאדם לדעת טוב ורע כי אני צויתיו לבל יאכל מעץ הדעת טוב ורע אלא שהוא חטא והשיג הידיעה וכיון שהשיג הידיעה יש לחוש שבאמצעות הידיעה יבחר לאכול מעץ החיים וחי לעולם. ומצאתי ראיה לפירוש ממנו מדברי אונקלוס שתרגם ממנו מיניה:
@78 **עוד** יתבאר הענין על זה הדרך כי ה' ביום צוותו על עץ הדעת צוה ב' דברים, הא' הוא בלתי אכול מעץ הדעת, והב' אם יאכל ישנו בתקנת המות, והוא אומרו כי ביום וגו' תמות, כי זה הוא תיקון הדבר והוה ליה כלאו הניתק לעשה שהוא התיקון. וכבר כתבנו למעלה כי זולת החטא היה האדם משיג לעלות להתעדן בעולם הנצחי בדמות שהוא והיה דר בעליה ובחצר, וצא ולמד מאליהו הנביא זכור לטוב ועל ידי החטא נפסלה גוייתו מהשגת עלות למקום קדוש וכשיהיה מושלל אפשריות ההפרדה מהגויה הרי הוא חסר השגת התעדנות הנצחי והערב המקווה, וכפי זה הגם שלא יצו האל להאדם בלתי אכול מעץ החיים האדם מעצמו יפרוש מחשש יום אוכלו מעץ הדעת שאם לא כן אין מציאות לתקן הלאו ונמצא האדם אבוד, אבל אחר שאכל הן אמת אם היה בדעתו שאכילתו היא אכילה שצריך עליה מיתה פשיטא שלא היה ה' חש שיאכל מעץ החיים אלא שאכילתו היתה בשוגג וכמו שכתבנו למעלה ומעתה אין לו לחוש עוד על העון לשמור עצמו בלתי קרוב לעץ **כי** יש לך לדעת כי עיקר טעם מצות המלך על עץ הדעת היא לבלתי יושג בדעת אדם הכרת בחינת הרע ותהיה דעתו מוחלטת בבחינת הטוב מבלי הרגשת בחינת הרע והוייתו בעולם, והוא אומרו (קהלת ז) (ברא) [עשה וגו'] את האדם ישר פירוש בידיעה אחת טובה ואין דמיון הרע מצוייר בדעתו וכאשר הוכר הרע בידיעתו ודעתו, וזה לך האות וידעו כי ערומים ויתבוששו, אין מקום למצוה זו בעולם, ויחשוב האדם שפקעה מצוה זו מעצמה ומעתה לא יחוש לשלוח ידו וחי, ואמר ה' כי טועה בדעתו וצריך הוא למות אפילו על שגגתו אשר שגג מטעם שכתבנו למעלה כי נפסל גופו מעלות אל האלהים יחד עם הנשמה:
@78 **ולפי** דרך זה נשכיל מאמר אחד תמוה (ב''ר פכ''א) וזה לשונם ועתה פן ישלח ידו אמר ר' אבא בר כהנא מלמד שפתח לו הקב''ה פתח של תשובה דכתיב ועתה אין ועתה אלא תשובה שנאמר (דברים י) ועתה ישראל מה וגו', והוא אמר פן אין פן אלא לאו, אמר הקב''ה ישלח ידו ואכל ואם אכל וחי לעולם עכ''ל. דבריהם ז''ל תמוהים ביותר איך יוצדק לומר ה' לאדם שיחזור בתשובה וימרוד מרד גדול כזה לומר לא. עוד למה לא חש ה' שיאכל אלא כשאמר לא. והיה נראה לומר כי אם היה עושה תשובה לא היה ה' מקפיד על חיותו לעולם וזה אינו כי כבר נתחייב מיתה ביום אוכלו מעץ הדעת:
@78 **ולפי** דרכנו יבואו על נכון דברי רבותינו ז''ל כי ה' רצה להודיע להאדם כי חטא באכילתו ובאמצעות הכרתו כן הוא מעצמו יבדל מלאכול מעץ החיים כמו שכתבנו למעלה כי הוא זה תיקונו, ולזה אמר לו שיעשה תשובה ומשמעות תשובה יגיד כי פשע, והאדם השיב לאו פירוש כי לא חטא שיצטרך לשוב, וטוען טענה הנשמעת כי לא ידע בה ואינו אלא שוגג ואינו צריך לעשות תשובה, וכיון שטען כן אמר ה' מעתה ישלח ידו ואכל שאין לו מונע כפי סברתו, לזה שלחו ה' כי משפטו נחתם למות על אכילתו מטעם שכתבנו. ואחר כך שב ונכנם במי גיחון ק''ל שנה לכפרת עון:
@78 **והנה** הגם שה' אמר אליו ביום אכלך ממנו וגו' דברי קדוש אמרם בב' פנים יש במשמעות יום יומו של אדם, ויש במשמעות יומו של הקב''ה שהוא אלף שנה (מדרש רבה פי''ט) והכונה הוא כפי בחינת החטא וכפי הרגשתו בדבר, אם ירשיע לעבור פי ה' בעזות יקיים בו יומו של אדם, ואם ישגוג שגגה כזו ויגלה דעתו כי לא היה חפץ בדבר תהיה הכוונה יומו של הקב''ה אלף שנה כמו שכן היה:
@81 **ותלד את קין ותאמר וגו'**. פירוש על דרך אומרם ז''ל (זהר ח''א נד) כי קין הוא בחינת הרע והבל הוא בחינת הטוב והוא נפשו של משה רבינו עליו השלום (תיקונים סט), והנה באמצעות הפלגת הפצעים שפצע קין בהבל עד שהרגו כאומרם ז''ל (סנהדרין לז:) שלא היה יודע מקום הנפש ובזה הסיר חלק הרע ממנו והוכר הטוב מוחלט, והוא אומרו **קניתי** וגו' פירוש באמצעות זה קניתי איש שהוא משה את ה', שלא השיג מציאות זה להיות עם ה' כמשה עליו השלום אלא באמצעות יסורין שעשה לו קין:
@82 **ותוסף וגו' את אחיו את הבל**. טעם שהוצרך לומר את אחיו ללא צורך, גם האריך לומר פעמים תיבת **את**, יתבאר על דרך אומרם ז''ל (ב''ר פכ''ב) כי אחר שנצח הבל לקין והפילו ריחם עליו הבל וקם מעליו ואחר כך קם קין וגו' והרגו, והוא שרמז באומרו **את אחיו** פירוש כי נהג הוא עם קין במדת האחוה כנזכר, אבל קין נהג עמו בלא אחוה אלא כאדם אחר, והוא אומרו **את הבל** בלא אחוה, ולזה הפסיק באת ב'. עוד רמז בב' אתין על דרך אומרם ז''ל (שם) כי ב' תאומות נולדו עם הבל לזה אמר ב' פעמים את, ובקין פעם אחת את כי לא נולדה אלא אחת:
@84 **וישע ה'וגו' ואל קין וגו'**. טעם שלא התחיל בהודעת המוקדם על זה הדרך ולא שעה אל קין וישע אל הבל, בא ללמדנו הפלגת ריחוק קין שאפילו אחר שהיה נחת רוח לפני ה' באמצעות מנחת הבל לא שעה לקין ואל מנחתו הגם היותו ראשון בתשורה וגדול בסדר הלידה ירד מטה מטה. וטעם שכפל לומר **אל הבל ואל מנחתו ואל קין ואל** וגו' ולא הספיק לומר אל מנחת הבל ואל מנחת קין. כאן רמז כי האדון היה מראה פנים של רצון למקרבי תשורה, והוא אומרו **וישע אל הבל** וגם קבל תשורתו, **ואל קין** לא הראה פנים לא לו ולא לתשורתו:
@85 **ויחר לקין וגו'**. הנה החרון אף יגיד הגבהות, ונפילת אפים יגיד ההשפלה, החרון אף הוא נגד אחיו שעלה במעלות והוא ירד למטה בחושבו כי הוא סיבה, שהביא קרבן משובח ומעולה יותר ממנו ובאמצעותו הוכר חסרון מנחתו. והשפלות בהכרתו פחיתותו בעיני ה'. עוד ירצה על זה הדרך **ויחר לקין** כשראה שלא קבל ה' מנחתו כי זה יגיד שמאם הבורא בברואיו ואינו משגיח בהם לזה חרה אף, ומדה זו בעובדי עבודה זרה היא כאומרו (ישעי' ח) והיה כי ירעב והתקצף נגד אלהיו אשר אינו משגיח בו. וכאשר ראה כי שעה ה' להבל ולא לו אז נפלו פניו וידע כי לא מצד המשגיח אלא מצד הנשגח הוא סיבה למנוע ממנו הרצון, ואחיו יוכיח ב' דברים יוכיח כי ה' משגיח, ויוכיח כי קין מושלל מהרצון כי הם ב' מנחות ופגול אחת. עוד ירמוז הכתוב אומרם ז''ל (זהר ח''ב קפב.) כי כל הכועם נשמתו מסתלקת ממנו, ובחינה זו מתייחסת אל צלם אלהים שעל פני אדם, והוא אומרו **ויחרלקין** ובזה נפלו פניו שנסתלקה ממנו הנשמה והוסר ממנו צלם הפנים. וטעם השפלתו בעיני ה' הגם שלא נודע חטאו מעשיו מעידות שרשע היה:
@86 **ויאמר ה' אל קין וגו'**. קשה אומרו **למה חרה** וגו' ההיטב יחרה לו על הפלגת השפלתו בערך אחיו הקטן ויפלו פניו, ובמה מסיר בושתו באומרו הלא אם תטיב, זה הוא תיקון להבא ולא לשעבר. עוד צריך לדעת אומרו **לפתח חטאת רובץ** אין לו משמעות וכל האמור בענין צריך פירוש:
@86 **אכן** כוונת דבר ה' הוא תחלת דבריו הודיעו כי השגיח ה' בב' הרגשות אשר עברוהו ועל כל אחת הוא אומר למה לכל הפירושים שפירשנו בחרון אפו ונפילת פניו. ונתן לו טעם הדבר ויסודו לדעת דעת עליון וסודו, והוא אומרו **הלא אם תטיב** פירוש אם תהיה מבחינת הטוב כל מעשיך שורה עליהם בחינת הטוב ומעצמן הם מתנשאים כי הקדושה אינה צריכה לאחרים. וצא ולמד (ב''מ פה:) ממעשה כסאו של ר' חייא שהיה עולה מעצמו למעלה והוא אומ' **שאת** פירוש מעצמו, ותתפרש שאת על המנחה גם על קין עצמו שלא יפלו פניו שהוא צלם הנאות אלא תהיה מעלתו נשאה והיא בחינת הטוב שהיא בחינת הרוממות והגדולה והם כנגד ב' בחינות האמורים בענין וישע ה' אל הבל ואל מנחתו שהם ב' דברים, **ואם לא תיטיב** פירוש כשתשלול בדעתך בחינת הטוב לפתח פירוש להתחלתך חשוב רע הנה בחינת הרע שנקראת חטאת רובצת עליך גם על כל מעשיך ושוללת ממך הנשיאות ומושלת במעשיך. ומעתה מה מקום לחרון אפך כיון שאתה סיבה לדבר. ואומרו **ואליך תשוקתו** כאן רמז כי יצר הרע יש בטבעו בחינת התשוקה להחטיא האדם כטבע שבאדם להתאוות תאוה ולחשוק זהב. ואומרו **ואתה תמשל בו** כאן הודיע כי הגם כי הוא בסדר זה ישנו בידו למשול בו, ומעתה למה יפלו פניך אחר שבידך הדבר למשול בו ולהרים המכשול שהוא החטאת:
@86 **עוד** יכוין לומר על זה הדרך **ואם לא תטיב לפתח** שהוא שער קבלת המנחות והתשורות שם רובץ החטאת לבל יהיה מקום לעלות התשורה ואין צריך לומר שאין בה כח להנשאות. ואם תאמר אתה האדון שליט תקבל המנחה ולא יהיה מונע החטאת, לזה אמר הן אמת אם תעשה תשובה יש מקום לטענה זו אבל כיון שאינך חושב בתשובה כרמוז בתיבת לא תטיב שעודך מתאוה וחושק לבחינת הרע והוא אומרו **ואליך תשוקתו** ואתה חפץ למשול בו ולגרש אותו לבל ירבוץ לפתחך, והגם כי ה' ירצה להפרידו מעליך אבל צריך שאתה תרחיקהו מתשוקתך כי כל עוד שאדם חושק בבחינת הרע הוא ממשילו עליו כאומרו (תהלים פא) לא יהיה בך אל זר, וכשהאדם מואס בדבריו ובעצתו זו היא השפלתו, והוא אומרו (משלי טז) ומושל ברוחו מלוכד עיר. וכפי זה ידבר ה' אליו בדרך תמיהא כדרך שהתחיל לדבר אליו למה וגו' ולמה וגו' כי תלונתו על עצמו ולא על מלכו כי איך יחפוץ שימשול הוא בו והוא ממשילו על עצמו והבן:
@88 **ויאמר קין אל הבל אחיו**. פירוש אמר לו דבר אחוה לצד שקדם אליו סיבת השנאה מחמת קנאה ירגיש הבל מאמצעות הדבר שישנאהו וישכיל להשמר ממנו אשר על כן אמר אליו האחוה כי לא נולד בלבו שנאה מחמת הדבר לצד קנאתו, והטעהו כדי להאמין בו לתכלית כוונתו להפילו במכמורת הכתוב אחר זה. ולכן נתחכם מפסיק פסוקים שעשה פיסקא ואינה פיסקא בפסוק זה עם פסוק שלאחריו:
@88 **ויהי בהיותם בשדה**. צריך לדעת לאיזה ענין הודיע הכתוב היותם בשדה. גם אמרו **ויקם** קימה זו למה ולא היה צריך הכתוב לומר אלא ויהרוג קין להבל. עוד לא היה צריך לומר אחיו. עוד צריך לדעת אומרו **אי הבל** מה כונת הבורא בשאלה זו. עוד מי פתי כקין שישיב ליודע ועד לא ידעתי ומי מכיר השגחתו כנבראים ראשונים:
@88 **עוד** מה יאריך לשון לומר **השומר**. עוד אומרו קול דמי אחיך צועקים אלי מן האדמה למה יוצרך לומר **מן האדמה** ומה היא הצעקה. עוד למה קלל האדמה אם הוא הרוצח עליו תבא קללה ומה מעלה ומה מורדת האדמה ברציחתו אם לא תקבל היא דמו יהיה ללקיקת הלוקק ומעשיה נאים בכסות דמו וכמעט אין משמעות לדברי ה':
@88 **אכן** הכוונה היא להיות כי קין נתקנא בהבל בחושבו כי הוא סיבה להשפלתו כי באמצעותו הוכר אופלו, וחשב כי כשלא יהיה הבל במציאות יתרצה ה' בקין כי אין עוד אחר לבחור בו, וחשב להורגו, וחש שתעל צחנתו ובאשו בפגעו בו כי נצטווה על הרציחה, ונתיעץ עצות להורגו מבלי שלוח יד בו והנה זה האיש איש אדמה היה יודע מוצאיה ומובאיה ובקי בחדריה ואמרו ז''ל (קהלת רבה פ''א) כי הארץ יש לה איברים כאיברי אדם עינים ידים ורגלים, פה וכו', ולמכיר בה ידע המקומות, ומעתה מצא היועץ רעה להרגו בערמה מבלי שלוח ידו בו. והוא אומרו **ויהי בהיותם בשדה** מתהלכים באדמה מצא מקום למועצותיו, ובאמצעות מה שקדם שהטעהו בבחינת האחוה האמין בו הבל ובזה קם עליו ובקימה זו שקם פירוש עמד עליו בזה הרגו, והנה העמידה אינה הורגת אלא שנתחכם לעמוד עליו במקום שיהיה נבלע באדמה וזו היא מיתתו והאדמה היא ההורגת. והגם שלא פירש הכתוב כאן אופן ההריגה הנה הוא גילה בפסוק שאחר זה שאמר אשר פצתה. וה' בוחן לבות שאלו אי הבל אחיך לראות היודה על פשעו והשיב לא ידעתי, ואם תאמר היה לך לתת לב עליו לזה אמר **השומר אחי** וגו', וכי שומר עשיתני עליו, ולא הודה על מעשהו הרע, שחשב כי ה' לא יעניש על הסיבה או לא ישגיח בה. והשיבו ה' מה עשית הודיעו כי מעשיו הרעים הם סיבה לאדמה לבלוע הבל והוא אומרו **קול דמי אחיך צועקים אלי מן** האדמה, פירוש כי הבל חושב בדעתו כי אדמה הרגתו וקבל לפני ה' ממנה, ולזה קלל ה' אותו כי הוא הסיבה ובהצטרפות קללתו קלל גם להאדמה אשר פצתה פיה לקחת הבל מידו שלא תפצה עוד פיה, והוא אומרם ז''ל (סנהדרין לז) שלא פצתה עוד פיה ומזמרת היא זמר ושיר לאל עליון חיוב הצריכה לעשות בכנפיה דכתיב (ישעי' כד) מכנף הארץ זמירות שמענו, ופחדה בעת שאמר לה ה' שתבלע המצריים מפחד פתיחת פיה לבלוע הבל עד שנשבע לה ה' (מכילתא) דכתיב (שמות טו) נטית ימינך ונשבע לה ואז בלעה אותם בפיה. ואפשר שלזה נתכוון מאמרם ז''ל (ב''ר פכ''ב) וזה לשונם רבנן אמרו באבן הרגו ע''כ, והנה במציאות הריגה זו יעשה כל גופו פצעים פצעים והוא אומרו דמי לשון רבים ולא היתה מיתתו ממקום א' כדרך הנשחטים ובזה הופשט הבל מכל דבק רע כמו שפירשתי בפסוק קניתי איש את ה', ויש מדרשים רבים בכת וב:
@95 **לכן כל הורג**. טעם לכן, להיות שהכיר וידע שאם ה' לא ישמרנו כל מוצאו יהרגהו, בשביל מצוה זו ריחם ה' עליו ואמר כל הורג וגו'. ורשם ה' אות בפניו כמשפטו הנהוג בעושה מצוה שנרשמת במצחו לטובה אות, והוא אומרו **וישם ה' לקין אות**, והוא על דרך מה שדרשו ז''ל (שמו''ר פי''ז) בפסוק והיה הדם (הזה) לכם לאות פירוש לאות מצוה להם לשמירה:
@107 **זה ספר וגו'**. צריך לדעת כוונת אומרו זה ספר מה הסיפור הלז. עוד אומרו **ביום ברא** וגו' בדמות, שנראה כי ביום ברא היה בדמות ולא אחדי כן. עוד אחר שכבר הודיע דבר זה ביום הבריאה למה חזר פעם ב' על הדבר. עוד למה הוצרך לומר פעם ב' עוד זכר ונקבה וגו' ועוד למה חזר לומר פעם ב' ביום הבראם. אכן כוונת הכתובים לשמור דרך ה' כי כל אורחותיו חיים עד העולם, והנה בבוא אלהים לסדר שני עולם אשר נסדרו בדורות לכמה סיבות נגלות ונסתרות והוצרך להזכיר מיתת אדם ויוצאי חלציו הקדים להסיר טענת טוען כנגדו יתברך איך ימאס יגיע כפיו כביכול יש יוצר אשר ישבר כליו יש בונה סותר בנייניו יש טורח ומפסיד טרחתו ויותר תגדל התמיהא בהגדיל ערך ההווה ונפסד ולמה יעשה ככה הוא היוצר הוא הבורא הוא הבונה עולמו לצורך האדם וישברנו בפתע ונמצא חמדת הכל מופסדת ואין הפסד נוגע אלא לבעליה. אשר על כן קודם שיאמר הכתוב מיתת אדם קדם ואמר כי לא מה' היה הדבר להמית דור חמדת הבריאה אלא הוא הסובב לעצמו למות, והוא אומרו **זה ספר תולדות**, פירוש אשר הוליד אדם באמצעות מעשיו, כי תולדות יאמר על הבנים ועל המעשים כדרך אומרם ז''ל (תנחומא נח) בפרשת אלה תולדות נח ודרשו ז''ל עיקר תולדות של צדיקים מצות ומעשים טובים, הנה שיאמר על אשר יעשה האדם בהנהגותיו לשון תולדות גם כאן יגיד תולדותיו של אדם כי ממנו יצאו הדברים הפך חפץ ה', כי ה' חפץ ביום שבראם להיות בדמות אלהים, והוא אומרו **ביום ברוא אדם בדמות אלהים עשה אותו**, פירוש תקנו לחיות תמיד. על דרך אומרו (תהלים פב) אני אמרתי אלהים אתם וגו' אכן כאדם תמותון, הרי זה מגיד כי באומרו אלהים חיים עד העולם. ואומרו **זכר ונקבה בראם** יגיד כי מה שאמר בדמות אלהים וגו' היתה גם הנקבה בגדר זה. גם נתכוון לומר שהגם שבראם בדמות אלהים לחיות לעולם אף על פי כן בראם זכר ונקבה לפרות ולרבות, ואמר עוד **ויברך** וגו' **ויקרא שמם אדם** שהוא שם המעולה כי הגדיל ה' חסדו עמהם ככל בחינת המעלות. וגמר אומר **ביום הבראם** שכל המעלות היו ביום הבריאה אבל לא עמד הדבר כן בין בבחינת האדם בין בבחינת האשה כמובן מהמאורע. ואחר שהודיע מה שממנו יתברך כתב ויחי אדם וגו' וימת והדבר מובן כי לא מאת ה' היתה זאת ולא חבל מעשה ידיו אלא הוא הסובב:
@109 **ויולד בדמותו כצלמו**. פירוש להיות שקין והבל נולדו בתגבורת בחינת הרע קרוב למעשה הרע ובן זה היה מרוחק מבחינת הרע כי כבר נתרוקן הזיהום לזה אמר **בדמותו** וגו'. עוד להיות כי ב' הראשונים מתו גם שניהם, הבל תכף ומיד, קין באבוד דור המבול, ומשת הושתת העולם לזה אמר **בדמותו כצלמו** אדם שממנו בנין העולם, גם הוא ג' לבטן הוא הקדוש וצא ולמד מלוי (תנחומא יתרו):
@111 **ויהיו כל ימי אדם וגו'**. טעם שהוצרך הכתוב להודיע פרט וכלל של השנים ללא צורך ולא הספיק בפרט לבד כסדר שלקח הכתוב בפרשת נח. הוא להיות שחיי כל הנבראים הם קצובים וחרוצים מיום הלידה דכתיב (איוב יד) אם חרוצים ימיו, ואדם הראשון להיות שנוצר לחיות תמיד אם לא היה חוטא, וכמו שכתבנו למעלה, לא היתה לו קצבה, והוא שאמר **ויהיו כל ימי אדם אשר חי**, הכוונה לא הקצובים לו מיום היותו כי לא היתה לו קצבה, וקצבתו היתה בעולם הזה נעשה לו הקצבה אשר חי ולא אשר נקצבו לו. ומה שכתב פרט וכלל מאדם ועד נח להודיע כי כלם שלמו ימיהם אשר קצבו להם ואין כוונת הכתוב באומרו **ויהיו כל ימי** וגו' לצרף הסך אלא לומר ויהיו כל ימי וגו' הם ימים הקצובים לו מיום היותו שלא קצבו לו יותר מעולם העליון, ולא אמר אשר חי, שתבין שחשבון מה שחי הוא מונה כדרך שכתב באדם כמו שפירשתי והבן:
@141 **ויאמר ה' לא ידון רוחי וגו'**. מקרא זה צריך מגיד ורז''ל דרשו בו (ב''ר פכ''ו) הרבה דרשות אבל פשט הכתוב לא נודע. ונראה שיכוין לומר להיות שהיה ה' מתנהג עם ברואיו להוכיח ולהתדיין עמהם בנגלה ויאמר ה' אל הנחש (ג' י''ד), אל האשה אמר וגו' (שם ט''ז), ולאדם אמר וגו', ויאמר ה' אל קין למה וגו' (ד' י'), ויאמר ה' אי הבל וגו' (שם ט'), וכאשר הגדילו להתעיב אמר ה' לא ידון עוד לעולם רוחי באדם פנים בפנים להשפט עמו יחד, ופירוש **רוחי** הוא שכינתו יתברך שלא יהיה עוד נחשב האדם להדרגה זו. ותמצא כי כפי מעשיו מרחיק הדרגתו מטה מטה, שבתחילה הי' ה' מוכיח לאדם על פניו ונמצאים הנבראים כולם במדרגת נביאים, **ויהי כי החל האדם** פירוש נתחלל או נעשה חולין הובדל מהדרגת נביא, ובהמשך הזמן הנצנים נראו בארץ הם הצדיקים שהחזירו העטרה ליושנה, ומשחרב המעון נסתם חזון ונשארה בחינת רוח הקודש, וכשנסתתמו עיני ישראל אין אתנו משיג ריח הקודש ואין צריך לומר רוח הקודש, וזו היא צרת בית ישראל שאין למעלה ממנה הצמאים להריח ריח אבינו שבשמים ותחי רוחינו. ותחילת קללה זו התחילה מדור המבול. ונתן ה' טעם לדבר זה **בשגם הוא בשר** פירוש בשביל שהוסיף להתעיב בתיעוב מוסרח בעון הניאוף הוא בשר כאמור בענין וה' שונא זימה ומאס מדבר אליו:
@141 **עוד** ירצה על דרך אומרם (הר''י עד אמה ז''ל) כי הצדיקים מהפכים החומר לעשותו צורה והרשעים מהפכים הצורה לחומר וזה הוא איבודן לעולם. והוא אומרו **לאידון רוחי** פירוש לא יהיה לי רצון מהם לעולם פירוש מעתה ועד עולם ואפילו עולם הנצחי, והטעם הוא **בשגם** פירוש בשביל שגם הוא רוחניות שבו הפכו ועשאו **בשר** וזה הוא איבוד הנפש, והוא אומרם ז''ל (סנהררין קז) דור המבול אין להם חלק לעולם הבא:
@141 **עוד** ירצה על זה הדרך **ויאמר ה' לא ידון עוד** מדת רחמים הרמוזה בתיבת **רוחי לעולם** הכונה היא שלא יחזור בו מגזרתו עליהם לרעה כמנהגו הטוב אשר ינחם ה' על הרעה בטענת כי הם מחומר קורצו, והוא אומרו (תהלים עח) ויזכור כי בשר המה, והוא אומרו **בשגם הוא בשר** פירוש עם היות הוא בשר טענה זו וסניגוריא זו לא תועיל להם לחזור לדון אותם לרחמים:
@141 **עוד** ירצה, להיות, שה' קבע השכר והעונש הכל לעולם העליון ישובו רשעים לשאולה, עתה אמר ד' כי לא ידון דין הרשעים לעולם הבא, **בשגם הוא בשר** פירוש בשביל שגם הוא בשר שהוא חומר והחומר יתייסר בעולם העכור והגם הוא עולם הזה השפל, ותלה להם ק''ך שנה אולי יחזרו, גם שבמשך זה ישלימו שנותיהם הצדיקים שהיו בדור ההוא כמתושלח וכדומה. ותמצא שדרשו ז''ל (זהר ח''א כו.) בפסוק (נח ז') כל אשר נשמת רוח וגו' מכל אשר בחרבה מתו שהם הצדיקים שיש להם בחינת הנשמה כולם מתו קודם ביאת המבול ע''כ:
@141 **עוד** ירמוז שנתכוון ה' לומר כי לא ינהיג רחמים גמורים לעולם והוא אומרו **ויאמר ה'** שהוא שם הרחמים **לא ידון רוחי** פירוש רצון שם המיוחד הזה שהוא מרוצה לרחם וכו' לא ידון לעולם פירוש לנבראים שבעולם כי באמצעות ריבוי הרחמים הנבראים מפליאות להתגאות ולבקש תאוות נכריות על דרך אומרו (הושע ב) וזהב הרביתי להם וגו' וסלק ה' הרחמים לעולם העליון. ותמצא שגם הצדיקים אפי' כיעקב אבינו לא השיג הרצון להתישב בשלוה בעולם הזה וקפץ עליו רוגזו של יוסף, וכן כל צדיק וצדיק כשרואה עצמו עברו עליו ל' יום (ערכין טז:) בשלוה מפחד על עצמו שאינו מרוצה לעולם העליון, והטעם הוא כי כן גזר ה' שלא יתנהג במדת רחמים גמורה בעולם הזה ואפילו עם הצדיקים. והוא אומרו **בשגם הוא בשר** פירוש מאותן שיש להם לב בשר על כל פנים תרדפם מדת הדין לשלם דקדוקי העבירות ובזה יתרבה המורא בלב הנבראים כשיעשה דין בצדיקים ויראוהו, וגם הצדיקים להנחילם ש''י עולמות:
@143 **וירא ה' כי רבה רעת האדם וגו' וינחם ה' כיעשה וגו'**. צריך לדעת אומרו **רעת האדם בארץ**, למה ייחס הרעה בארץ, שנראה שרעתם היתה בגוף הארץ, ואחר האמת רשעת הרשעים ההם היתה בזנות ומפורש בכתוב ובחמס וגזל, ואף שיוצדק לומר בארץ על בחינת גזל הארץ עם כל זה יהיה זה פרט מהפרט. עוד למה דקדק לומר **וינחם [ה' כי עשה את האדם] בארץ** למה אמר תיבת בארץ שנראה שאם עשאו במקום אחר לא ינחם לעולם ואין משמעות לזה. עוד איך יוצדק לומר וינחם ה' כי לא איש אל וגו'. עוד אומרו **ויתעצב** עצבון זה למה שאחר שהוא נוקם נקמתו מהם ומוחה כל מורד. ולזה אפשר לומר על הפסד הבדיאה:
@143 **אכן** כוונת הכתובים הוא להיות כי האדם הוא מורכב מד' יסודות אש, רוח, מים, עפר והם בהדרגות, הדרגה הפחותה שבד' הוא העפר כי הוא עכור וגס מכולם, למעלה ממנו יסוד המים, למעלה ממנו יסוד האש, למעלה מהאש יסוד הרוח, שהוא הרוחני שבכולן, ותמצא כי כל הנבראים שבעולם הגם שכולן מד' יסודות בראם עם כל זה כל בריה עיקר בניינה מיסוד א' והוא יסוד היסוד והג' סניפים לו. יש בריה שעיקר יסודה הוא המים כדגים הגדילים במים, ויש שעיקר יסודם מן הרוח כעופות והגם שמן הרקק נבראו עם כל זה ה' הגביר בהם יסוד הרוח ולזה לא ינוחו הציפורים עפות הן כבחינת הרוח. ויש בריה שעיקרה מן האש כסלמנדרא. והן האדם יסוד שעליו נבנו בו היסודות הוא יסוד העפר דכתיב (ב' ז') וייצר ה' וגו' את האדם עפר מן האדמה שהוא יסוד הגס והעב שבד' יסודות, ולזה ישיבתו ומנוחתו באדמה ולא יסבול דירה במים ולא באויר ולא באש, ועשה ה' כן לסיבות הרבה, ואחת מהנה כי הוא הסולם אשר בו עולות המדרגות ממטה למעלה והמדרגה התחתונה היא יסוד העפר וצריך להיות בארץ, ואם היה נבנה יסודו מן הג' האחרים הרוחניות בערך העפר לא היתה הכונה שלימה בבריאתו, והמשכיל יבין כי הוא סוד הבירור, והבן. ולזה כאשר ראה ה' כי רבה רעת האדם הכיר כי רוב התיעוב הוא לצד יסודו שהוא בנוי מן הארץ וגם מקום הנחתו וחיותו בארץ, והוא אומרו **וירא ה' כי רבה רעת האדם בארץ** כי הוא יסוד הגם ונגדי לרוחני בתכלית, ולזה ניחם ה' כי עשה את האדם בארץ ולא עשאו בנוי משאר היסודות הדקים שבזה לא היה רק רע כל היום. ולהיות שמעשהו משאר יסודות לא תצא כוונת היצירה שחשב ה' בלבו לפועל, והוא אומרו **ויתעצב אל לבו** ולא אמר בלבו פירוש אל רצונו ומחשבתו אשר חשב בבריאת האדם, ומצד זה לא הפך ה' הבריאה שאם לא כן היה ה' סותר ובונה בנין חדש בהרכבה מג' יסודות, ולזה הגם שהביא מבול ואבד הכל הניח הבריאה כמות שהיתה לטעם כמוס בלבו יתברך, והגם שבאדון יתברך לא יוצדק לומר וינחם כי הוא צופה ומביט עד סוף כל הדורות, אמר כן, להיות, כי האדון יתברך מדותיו מדות הרחמים, גם בו יתברך צד הדין, ובזמן שהנבראים הולכים בדרך ישר ה' הוא האלהים מסכמת מדת הדין למדת רחמים, וכשהרשעים מכעיסים מדת הרחמים תרחיק הרחמים ותחפוץ בשלילת ההויה מעשות דין בהם, והוא אומרו **וינחם ה'**, פירוש בחינת הרחמים תחפוץ שלא תהיה הבריאה כדי שלא להפך המדה ולא מפני זה תושלל הבריאה:
@143 **עוד** נראה לומר לפי מה שכתב הרמב''ם פרק ה' מהלכות תשובה וזה לשונו כי יתעלה שמו הוא ודעתו אחד ואין דעתו של אדם יכולה להשיג דבר זה על בוריו וכו', ואין בנו כח לידע היאך ידע הקב''ה הברואים ומעשיהם, אבל נדע ודאי שמעשה האדם ביד האדם ואין הקב''ה מושכו וכו', ע''כ. והראב''ד ה' יכפר בעדו נהג מיעוט כבוד בהרמב''ם על דברו בזה והעלה כי טוב לומר שראותו יתברך כראות אצטגנינין וכו' יעוין שם דבריו. ודברי הרמב''ם עיקר כי אין אופן ידיעת ה' מושגת אצלינו ומי ידמה לה' לקחת ידיעה מהנדמה אליו. ואשכילך, כי ה' יכול לשלול הידיעה המושגת בידיעתו לבל ידענה, כשירצה האדון מה שאין כח באנוש לעשות זאת שתגיע אליו הידיעה ולא ידענה, והוא שרמז רמב''ם באומרו ואין דעתו של אדם יכולה להשיג וכו', כי איך אפשר שתגיע עדיו הידיעה מעצמה ותהיה מושללת מעצמה, והוא שאמר הכתוב (במדבר כג) לא הביט און ביעקב ולא ראה עמל, הנך רואה כשירצה ה' שלא לדעת יושלל הידיעה הגם שהידיעה ישנה מעצמה, כי אינו בבחינת האדם שהידיעה הוא חוץ ממנו, לומר ימנע ולא ידענה, כי ה' הוא ודעתו אחד ואינו צריך לתת לב לדעת, שבזה נאמר דכשלא יתן לב לא ידע, לא כן, ואף על פי כן כביכול ישנו בבחינה זו דכתיב לא הביט וגו'. ומעתה נוכל לומר כי ה' בעת ברוא האדם שלל מהידיעה פשעי אדם לב' סיבות, א', לטעם הפשטי כי טוב ה' ולא יביט אל התיעוב וטעם זה לבד לא יספיק כיון שהוא צורך בידיעה לדעת מה יעשה והנמשך. אלא שיש עוד טעם ב' והוא שנתחכם לעשות ה' כן לבל תחול טענת הרשעים שיאמרו ידיעתו מכרחת, כיון שה' ידע כי פלוני זה יעבור על מה שעבר הדבר מעצמו יתחייב להיות הגם שה' לא גזר להיות כן, ומעתה אין עונש לרשעים כי לא מרשעים יצא רשע ובמה יפחד רשע ויחדל מעושק, לזה מנע ה' ידיעה זו של מעשה הרשעים. אבל מעשה הצדיקים לא שללו מהידיעה ובו שמח ולסיבה זו היתה הבריאה, והוא שאמר הכתוב (לעיל א לא) וירא אלהים את כל אשר עשה והנה טוב מאוד. ואם תאמר אם לא הביט און של רשעים היאך קבע עונש לעושי רשעה, וכי צריך לקבוע עונש לפלוני המרשיע אין צריך לקבוע עונש אלא לעושה עון ופשע. ובערך הצדיקים אין מקום לטענת ידיעתו מכרחת כי טענה זו היא התשלום והנה ה' חפץ לשלם ואין טוען נגד עצמו, מה שאין כן בעונש הרשעים שיבואו בטענה לבל יקבלו עונש לזה שמר ה' את הדבר. ואין לטעון ולומר אלו הביט ה' בהם שיהיו צדיקים היו עושי צדק, שטענה זו אינה טענה לפוטרם מפרט הבחירה שנתן בידם ובחרו ברע ומאסו בטוב ברצונם. ואחרי הודיע אלהים אותנו את זה אין תמיהה באומרו וינחם ה' וגו', כי נחמתי, כי הוא עצמו שלל ידיעה זו ממנו:
@145 **ויאמר ה' אמחה וגו'**. הוצרך לומר כי נחמתי וגו' ולא הספיק במה שאמר בסמוך, בא לומר שטעם שאמר אמחה הוא לצד שניחם על עשייתם לא לצד מעשיהם הרעים, כי יש הפרש אם הכליון יהיה לצד מעשיהם הרעים ימצאון שלא יתחייבו כליה והם אותם שלא הגיעו לעונשין, ואם יהיה הכליון לצד כי ניחם ה' קטן וגדול שם הוא בכלל הגזרה, ולזה אמר **אמחה** וגו' **כי נחמתי כי עשיתים** ולטעם זה אין נמלט, ולזה אמר תכף ומיד **ונח מצא חן בעיני ה'** פירוש לא לצד מעשיו כי בבחינת החזרה שחזר ה' מבריאת האדם לא יצילנו היותו צדיק ולזה הוצרך לומר מצא חן ולא מחאו. ואין מזה הוכחה לומר כי לא היה צדיק כי הגם שהיה צדיק לא תצילנו צדקתו אלא בחינת החן שהשיג מאמצעות בחינת המצות, כי יש לך לדעת כי יש מצוה שתועלתה היא להמשיך חן על האדם, או בבחינת ג' או ד' מצות ידועות, וה' לא הודיע תועליות המצות לטעם שאמרו ז''ל (תנחומא עקב) שירוצו כל העולם לתועליות, וזה נח זכה ומצא החן גם שמו יגיד כן נח חן:
@145 **חסלת פרשת בראשית**
